  const initializedCallId = useRef<string | null>(null);

  const activeCall = currentCall || incomingCall;
  const otherId = activeCall?.participantIds?.find(id => id !== currentUser?.id) || activeCall?.initiatorId;
  const otherUser = friends.find(f => f.id === otherId);
  const isConnected = currentCall?.status === 'connected';
  const isIncoming = !!incomingCall && !currentCall;
  const isVideo = activeCall?.type === 'video';

  // Ringtone for incoming calls
  useEffect(() => {
    if (isIncoming) {
      try {
        const ctx = new AudioContext();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.frequency.setValueAtTime(600, ctx.currentTime);
        osc.frequency.setValueAtTime(800, ctx.currentTime + 0.2);
        gain.gain.setValueAtTime(0.1, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);
        osc.start(ctx.currentTime);
        osc.stop(ctx.currentTime + 0.5);
        // Repeat every 2 seconds
        const interval = setInterval(() => {
          const osc2 = ctx.createOscillator();
          const gain2 = ctx.createGain();
          osc2.connect(gain2);
          gain2.connect(ctx.destination);
          osc2.frequency.setValueAtTime(600, ctx.currentTime);
          osc2.frequency.setValueAtTime(800, ctx.currentTime + 0.2);
          gain2.gain.setValueAtTime(0.1, ctx.currentTime);
          gain2.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);
          osc2.start(ctx.currentTime);
          osc2.stop(ctx.currentTime + 0.5);
        }, 2000);
        return () => clearInterval(interval);
      } catch { /* Audio not supported */ }
    }
  }, [isIncoming]);

  // Duration timer
  useEffect(() => {
    if (isConnected) {
      timerRef.current = setInterval(() => {
        setCallDuration((d) => d + 1);
      }, 1000);
    }

    // Avoid state updates directly in the effect body.
    // Cleanup will run before the next render when `isConnected` changes.
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      timerRef.current = null;
      if (!isConnected) return;
      // no-op; call duration is set when connection becomes active
    };
  }, [isConnected]);

  useEffect(() => {
    if (isConnected) return;
    // Schedule outside React render phase to avoid react-hooks/set-state-in-effect.
    queueMicrotask(() => setCallDuration(0));
  }, [isConnected]);





  // WebRTC initialization
  useEffect(() => {
    if (!currentCall || !currentUser) return;
    if (initializedCallId.current === currentCall.id) return;

    const otherId = currentCall.participantIds.find(id => id !== currentUser.id);
    if (!otherId) return;

    const webrtc = new WebRTCCall(
      currentUser.id,
      otherId,
      currentCall.type === 'video',
      (state) => { if (state === 'ended') { useCallStore.getState().endCall(); } },
      (stream) => { if (remoteVideoRef.current) remoteVideoRef.current.srcObject = stream; },
      (stream) => { if (localVideoRef.current) localVideoRef.current.srcObject = stream; }
    );

    webrtcRef.current = webrtc;
    initializedCallId.current = currentCall.id;

    if (currentCall.initiatorId === currentUser.id) {
      webrtc.startCall(currentCall.id);
    } else {
      webrtc.answerCall(currentCall.id);
    }

    return () => {
      if (initializedCallId.current === currentCall.id) {
        webrtcRef.current?.endCall();
        webrtcRef.current = null;
        initializedCallId.current = null;
      }
    };
  }, [currentCall?.id, currentUser?.id]);

  const handleAccept = async () => {
    if (!incomingCall || !currentUser) return;
    const webrtc = new WebRTCCall(
      currentUser.id,
      incomingCall.initiatorId,
      incomingCall.type === 'video',
      (state) => { if (state === 'ended') { useCallStore.getState().endCall(); } },
      (stream) => { if (remoteVideoRef.current) remoteVideoRef.current.srcObject = stream; },
      (stream) => { if (localVideoRef.current) localVideoRef.current.srcObject = stream; }
    );
    webrtcRef.current = webrtc;
    initializedCallId.current = incomingCall.id;
    await webrtc.answerCall(incomingCall.id);
    acceptCall();
  };

  const handleReject = () => { rejectCall(); };
  const handleEndCall = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    webrtcRef.current?.endCall();
    webrtcRef.current = null;
    initializedCallId.current = null;
    endCall();
  };

  const handleToggleMute = () => {
    const next = !isMuted;
    setIsMuted(next);
    webrtcRef.current?.toggleAudio(!next);
  };

  const handleToggleVideo = () => {
    const next = !isVideoOn;
    setIsVideoOn(next);
    webrtcRef.current?.toggleVideo(next);
  };

  const handleFlipCamera = () => {
    webrtcRef.current?.flipCamera();
  };

  const formatDuration = (s: number) => {
    const m = Math.floor(s / 60);
    const sec = s % 60;
    return `${m}:${sec.toString().padStart(2, '0')}`;
  };

  if (!currentCall && !incomingCall) return null;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-[70] bg-[#111111] flex flex-col"
      >
        {/* Video Streams */}
        {isVideo && !isIncoming && (
          <>
            <video ref={remoteVideoRef} autoPlay playsInline className="absolute inset-0 w-full h-full object-cover" />
            <video ref={localVideoRef} autoPlay muted playsInline className="absolute top-4 right-4 w-32 h-40 rounded-lg object-cover shadow-lg bg-black/50 z-10" />
            {/* Camera flip button */}
            <button type="button" onClick={handleFlipCamera}
              className="absolute top-4 left-4 z-20 w-10 h-10 rounded-full bg-black/30 backdrop-blur-sm flex items-center justify-center text-white"
            >
              <RotateCw size={18} />
            </button>
          </>
        )}

        {/* Call Info Panel (toggleable) */}
        <AnimatePresence>
          {showCallInfo && (
            <motion.div
              initial={{ y: -100, opacity: 0 }}
              animate={{ y: 0, opacity: 1 }}
              exit={{ y: -100, opacity: 0 }}
              className="absolute top-0 left-0 right-0 z-20 bg-gradient-to-b from-black/70 to-transparent p-4 pt-12 pb-8"
            >
              <div className="text-center">
                <h2 className="text-white text-xl font-semibold">{otherUser?.name || 'User'}</h2>
                <p className="text-white/60 text-sm mt-1">
                  {isIncoming ? 'Incoming call...' : isConnected ? formatDuration(callDuration) : 'Calling...'}
                </p>
                {isConnected && (
                  <div className="flex items-center justify-center gap-2 mt-2">
                    <Clock size={12} className="text-white/40" />
                    <span className="text-white/40 text-xs">{formatDuration(callDuration)}</span>
                  </div>
                )}
                <div className="flex items-center justify-center gap-2 mt-1">
                  <span className={`w-2 h-2 rounded-full ${isConnected ? 'bg-green-400' : 'bg-yellow-400 animate-pulse'}`} />
                  <span className="text-white/40 text-xs">{isConnected ? 'Connected' : isIncoming ? 'Ringing' : 'Connecting'}</span>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Toggle info button */}
        <button type="button" onClick={() => setShowCallInfo(!showCallInfo)}
          className="absolute top-4 left-1/2 -translate-x-1/2 z-30 w-8 h-8 rounded-full bg-black/30 backdrop-blur-sm flex items-center justify-center text-white/60"
        >
          {showCallInfo ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
        </button>

        {/* Main Avatar / Info Area */}
        <div className={`flex-1 flex items-center justify-center relative z-10 ${isVideo && !isIncoming ? 'pointer-events-none' : ''}`}>
          <div className="text-center">
            <motion.div
              initial={{ scale: 0.8 }}
              animate={{ scale: 1 }}
              className={`w-32 h-32 rounded-full bg-[#F5F5F5] flex items-center justify-center mx-auto mb-6 shadow-2xl overflow-hidden ${isIncoming ? 'ring-4 ring-[#00C300] animate-pulse' : ''}`}
            >
              {sanitizeMediaUrl(otherUser?.avatar) ? (
                <img src={sanitizeMediaUrl(otherUser?.avatar)} className="w-full h-full object-cover" alt="User avatar" />
              ) : (
                <img src={getDefaultAvatar(otherUser?.id || otherUser?.name || 'U')} className="w-full h-full object-cover" alt="User avatar" />
              )}
            </motion.div>
            <h2 className="text-white text-2xl font-semibold">{otherUser?.name || 'User'}</h2>
            <p className="text-white/50 mt-2">
              {isIncoming ? 'Incoming call...' : isConnected ? formatDuration(callDuration) : 'Calling...'}
            </p>
            {isConnected && (
              <div className="flex items-center justify-center gap-2 mt-2">
                <span className="w-2 h-2 rounded-full bg-green-400" />
                <span className="text-green-400 text-xs font-medium">Connected</span>
              </div>
            )}
            {isIncoming && (
              <div className="flex items-center justify-center gap-2 mt-2">
                <span className="w-2 h-2 rounded-full bg-yellow-400 animate-pulse" />
                <span className="text-yellow-400 text-xs font-medium">Ringing...</span>
              </div>
            )}
          </div>
        </div>

        {/* Call Controls */}
        <div className="shrink-0 p-8 pb-12 relative z-10">
          <div className="flex items-center justify-center gap-6">
            {isIncoming ? (
              <>
                <motion.button whileTap={{ scale: 0.95 }} onClick={handleReject} className="w-16 h-16 rounded-full bg-[#FF3B30] flex items-center justify-center shadow-lg">
                  <PhoneOff size={28} className="text-white" />
                </motion.button>
                <motion.button whileTap={{ scale: 0.95 }} onClick={handleAccept} className="w-16 h-16 rounded-full bg-green-500 flex items-center justify-center shadow-lg">
                  <Phone size={28} className="text-white" />
                </motion.button>
              </>
            ) : (
              <>
                {/* Mute */}
                <motion.button whileTap={{ scale: 0.95 }} onClick={handleToggleMute} className={`w-14 h-14 rounded-full flex items-center justify-center transition-colors ${isMuted ? 'bg-[#FF3B30]' : 'bg-white/10'}`}>
                  {isMuted ? <MicOff size={24} className="text-white" /> : <Mic size={24} className="text-white" />}
                </motion.button>

                {/* Speaker */}
                <motion.button whileTap={{ scale: 0.95 }} onClick={() => setIsSpeakerOn(!isSpeakerOn)} className={`w-14 h-14 rounded-full flex items-center justify-center transition-colors ${!isSpeakerOn ? 'bg-[#FF3B30]' : 'bg-white/10'}`}>
                  {isSpeakerOn ? <Volume2 size={24} className="text-white" /> : <VolumeX size={24} className="text-white" />}
                </motion.button>

                {/* Video Toggle */}
                {isVideo && (
                  <motion.button whileTap={{ scale: 0.95 }} onClick={handleToggleVideo} className={`w-14 h-14 rounded-full flex items-center justify-center transition-colors ${!isVideoOn ? 'bg-[#FF3B30]' : 'bg-white/10'}`}>
                    {isVideoOn ? <Video size={24} className="text-white" /> : <VideoOff size={24} className="text-white" />}
                  </motion.button>
                )}

                {/* End Call */}
                <motion.button whileTap={{ scale: 0.95 }} onClick={handleEndCall} className="w-16 h-16 rounded-full bg-[#FF3B30] flex items-center justify-center shadow-lg">
                  <PhoneOff size={28} className="text-white" />
                </motion.button>
              </>
            )}
          </div>
        </div>
      </motion.div>
    </AnimatePresence>
  );
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Heart, MessageCircle, Share2, Bookmark, Music, Volume2, VolumeX,
  Play, Send, ChevronLeft, MoreHorizontal, UserPlus, Download, BarChart3, Camera, Loader
} from 'lucide-react';
import { useAuthStore } from '@/store/useAuthStore';
import { useReelStore } from '@/store/useReelStore';
import EmptyState from '@/components/EmptyState';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import { getDefaultAvatar } from '@/lib/utils';
import { toast } from 'sonner';
import type { Reel } from '@/types';

interface FeedReelsViewerProps {
  onClose?: () => void;
}

export default function FeedReelsViewer({ onClose }: FeedReelsViewerProps) {
  const { user } = useAuthStore();
  const { reels, loading, getReels, likeReel, unlikeReel, saveReel, shareReel, commentOnReel } = useReelStore();
  const [activeIndex, setActiveIndex] = useState(0);
  const [localLiked, setLocalLiked] = useState<Record<string, boolean>>({});
  const [localSaved, setLocalSaved] = useState<Record<string, boolean>>({});
  const [muted, setMuted] = useState(true);
  const [, setPlaying] = useState<Record<string, boolean>>({});
  const [showComments, setShowComments] = useState<Reel | null>(null);
  const [showInsights, setShowInsights] = useState<Reel | null>(null);
  const [commentText, setCommentText] = useState('');
  const [feedType, setFeedType] = useState<'foryou' | 'following'>('foryou');
  const scrollRef = useRef<HTMLDivElement>(null);
  const videoRefs = useRef<Record<string, HTMLVideoElement | null>>({});

  // ─── Infinite scroll ───
  const [hasMore, setHasMore] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const loadMoreRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    getReels(20).then((initial) => {
      if (initial.length < 20) setHasMore(false);
    });
  }, [getReels]);

  // IntersectionObserver for infinite scroll
  useEffect(() => {
    if (!loadMoreRef.current || !hasMore) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && !loadingMore && hasMore) {
          loadMoreReels();
        }
      },
      { root: scrollRef.current, threshold: 0.5 }
    );
    observer.observe(loadMoreRef.current);
    return () => observer.disconnect();
  }, [hasMore, loadingMore, reels.length]);

  const loadMoreReels = async () => {
    if (loadingMore || !hasMore) return;
    setLoadingMore(true);
    try {
      const more = await getReels(reels.length + 20);
      if (more.length <= reels.length) {
        setHasMore(false);
      }
    } catch {
      // ignore
    } finally {
      setLoadingMore(false);
    }
  };

  // Auto-play/pause based on active index
  useEffect(() => {
    const reel = reels[activeIndex];
    if (!reel) return;
    Object.entries(videoRefs.current).forEach(([id, video]) => {
      if (!video) return;
      if (id === reel.id) {
        video.play().catch(() => {});
        setPlaying(prev => ({ ...prev, [id]: true }));
      } else {
        video.pause();
        setPlaying(prev => ({ ...prev, [id]: false }));
      }
    });
  }, [activeIndex, reels]);

  // Track view when reel becomes active (3 second watch)
  useEffect(() => {
    const reel = reels[activeIndex];
    if (!reel || !user?.id) return;
    const timer = setTimeout(() => {
      if (!reel.viewedBy?.includes(user.id)) {
        useReelStore.getState().viewReel?.(reel.id, user.id);
      }
    }, 3000);
    return () => clearTimeout(timer);
  }, [activeIndex, reels, user?.id]);

  const handleScroll = useCallback(() => {
    if (!scrollRef.current) return;
    const scrollTop = scrollRef.current.scrollTop;
    const height = scrollRef.current.clientHeight;
    const index = Math.round(scrollTop / height);
    if (index !== activeIndex) {
      setActiveIndex(index);
    }
  }, [activeIndex]);

  const handleLike = async (reel: Reel) => {
    if (!user?.id) return;
    const isLiked = localLiked[reel.id] ?? reel.likes.includes(user.id);
    setLocalLiked(prev => ({ ...prev, [reel.id]: !isLiked }));
    if (isLiked) {
      await unlikeReel(reel.id, user.id);
    } else {
      await likeReel(reel.id, user.id);
    }
  };

  const handleSave = async (reel: Reel) => {
    if (!user?.id) return;
    const isSaved = localSaved[reel.id] ?? reel.savedBy.includes(user.id);
    setLocalSaved(prev => ({ ...prev, [reel.id]: !isSaved }));
    await saveReel(reel.id, user.id);
  };

  const handleShare = async (reel: Reel) => {
    if (!user?.id) return;
    await shareReel(reel.id, user.id);
    try {
      await navigator.clipboard.writeText(`https://oumagachat.web.app/reel/${reel.id}`);
      toast.success('Link copied to clipboard');
    } catch { /* noop */ }
  };

  const handleDownload = async (reel: Reel) => {
    if (!reel.videoUrl) { toast.error('No video to download'); return; }
    try {
      const a = document.createElement('a');
      a.href = reel.videoUrl;
      a.download = `gaga-reel-${reel.id.slice(0, 8)}.mp4`;
      a.target = '_blank';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      toast.success('Download started');
    } catch {
      toast.error('Download failed');
    }
  };

  const handleAddComment = async () => {
    if (!user?.id || !showComments || !commentText.trim()) return;
    await commentOnReel(showComments.id, user.id, commentText.trim());
    setCommentText('');
    getReels(20);
  };

  const isLiked = (reel: Reel) => {
    if (localLiked[reel.id] !== undefined) return localLiked[reel.id];
    return user?.id ? reel.likes.includes(user.id) : false;
  };

  const isSaved = (reel: Reel) => {
    if (localSaved[reel.id] !== undefined) return localSaved[reel.id];
    return user?.id ? reel.savedBy.includes(user.id) : false;
  };

  return (
    <div className="h-full flex flex-col bg-black relative">
      {/* Header overlay */}
      <div className="absolute top-0 left-0 right-0 z-20 flex flex-col px-4 py-3 bg-gradient-to-b from-black/70 to-transparent">
        <div className="flex items-center justify-between mb-2">
          <button type="button" onClick={onClose} className="text-white p-1">
            <ChevronLeft size={24} />
          </button>
          <div className="flex items-center gap-4">
            <button type="button" onClick={() => setFeedType('following')}
              className={`text-sm font-semibold transition-colors ${feedType === 'following' ? 'text-white' : 'text-white/50'}`}
            >
              Following
            </button>
            <button type="button" onClick={() => setFeedType('foryou')}
              className={`text-sm font-semibold transition-colors ${feedType === 'foryou' ? 'text-white' : 'text-white/50'}`}
            >
              For You
            </button>
          </div>
          <button type="button" onClick={() => { window.location.href = '/create-reel'; }} className="text-white p-1">
            <Camera size={22} />
          </button>
          <button type="button" className="text-white p-1">
            <MoreHorizontal size={24} />
          </button>
        </div>
        {feedType === 'following' && (
          <div className="text-center">
            <span className="text-white/70 text-xs">Following feed coming soon</span>
          </div>
        )}
      </div>

      {/* Reels feed */}
      <div
        ref={scrollRef}
        onScroll={handleScroll}
        className="flex-1 overflow-y-auto snap-y snap-mandatory scroll-smooth"
      >
        {loading && reels.length === 0 && (
          <div className="h-full flex items-center justify-center">
            <LoadingSkeleton />
          </div>
        )}

        {!loading && reels.length === 0 && (
          <div className="h-full flex items-center justify-center">
            <EmptyState icon={Play} title="No reels yet" description="Be the first to share a reel!" />
          </div>
        )}

        {reels.map((reel) => (
          <div
            key={reel.id}
            className="h-full w-full snap-start relative shrink-0 overflow-hidden"
          >
            {/* Video / Placeholder */}
            {reel.videoUrl ? (
              <video
                ref={el => { videoRefs.current[reel.id] = el; }}
                src={reel.videoUrl}
                muted={muted}
                loop
                playsInline
                className="absolute inset-0 w-full h-full object-cover"
                poster={reel.thumbnailUrl}
              />
            ) : (
              <div className="absolute inset-0 bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] flex items-center justify-center">
                <div className="w-24 h-24 rounded-full bg-[#2a2a2a] flex items-center justify-center">
                  <Play size={40} className="text-white/50" />
                </div>
              </div>
            )}

            {/* Gradient overlay */}
            <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-black/30 pointer-events-none" />

            {/* Play/Pause overlay tap */}
            <button type="button" className="absolute inset-0 z-10"
              onClick={() => {
                const video = videoRefs.current[reel.id];
                if (!video) return;
                if (video.paused) {
                  video.play().catch(() => {});
                  setPlaying(prev => ({ ...prev, [reel.id]: true }));
                } else {
                  video.pause();
                  setPlaying(prev => ({ ...prev, [reel.id]: false }));
                }
              }}
            />

            {/* Mute toggle */}
            <button type="button" onClick={() => setMuted(!muted)}
              className="absolute top-20 right-4 z-20 p-2 rounded-full bg-black/40 text-white"
            >
              {muted ? <VolumeX size={18} /> : <Volume2 size={18} />}
            </button>

            {/* Right side actions */}
            <div className="absolute right-3 bottom-24 z-20 flex flex-col items-center gap-5">
              {/* Avatar */}
              <div className="relative">
                <img
                  src={reel.userAvatar || getDefaultAvatar(reel.userId)}
                  alt={reel.userName}
                  className="w-10 h-10 rounded-full object-cover border border-white/20"
                />
                <button type="button" className="absolute -bottom-2 left-1/2 -translate-x-1/2 bg-[#00C300] rounded-full p-0.5">
                  <UserPlus size={12} className="text-black" />
                </button>
              </div>

              {/* Like */}
              <button type="button" onClick={() => handleLike(reel)} className="flex flex-col items-center gap-0.5">
                <Heart
                  size={28}
                  className={isLiked(reel) ? 'text-red-500 fill-red-500' : 'text-white'}
                />
                <span className="text-white text-xs font-medium">
                  {(reel.likes.length + (localLiked[reel.id] && !reel.likes.includes(user?.id || '') ? 1 : 0)).toLocaleString()}
                </span>
              </button>

              {/* Comment */}
              <button type="button" onClick={() => setShowComments(reel)} className="flex flex-col items-center gap-0.5">
                <MessageCircle size={28} className="text-white" />
                <span className="text-white text-xs font-medium">{reel.comments.length}</span>
              </button>

              {/* Save */}
              <button type="button" onClick={() => handleSave(reel)} className="flex flex-col items-center gap-0.5">
                <Bookmark
                  size={28}
                  className={isSaved(reel) ? 'text-[#00C300] fill-[#00C300]' : 'text-white'}
                />
              </button>

              {/* Share */}
              <button type="button" onClick={() => handleShare(reel)} className="flex flex-col items-center gap-0.5">
                <Share2 size={28} className="text-white" />
                <span className="text-white text-xs font-medium">{reel.shares.length}</span>
              </button>

              {/* Download */}
              <button type="button" onClick={() => handleDownload(reel)} className="flex flex-col items-center gap-0.5">
                <Download size={28} className="text-white" />
                <span className="text-white text-xs font-medium">Save</span>
              </button>

              {/* Insights */}
              <button type="button" onClick={() => setShowInsights(reel)} className="flex flex-col items-center gap-0.5">
                <BarChart3 size={28} className="text-white" />
                <span className="text-white text-xs font-medium">{reel.viewCount.toLocaleString()}</span>
              </button>

              {/* More */}
              <button type="button" className="text-white">
                <MoreHorizontal size={24} />
              </button>
            </div>

            {/* Bottom info */}
            <div className="absolute left-4 bottom-8 right-20 z-20">
