import { useEffect, useRef } from 'react';
import { useChatStore } from '@/store/useChatStore';
import { useGroupStore } from '@/store/useGroupStore';
import { toast } from 'sonner';

interface QueuedMessage {
  id: string;
  type: 'direct' | 'group';
  chatId: string;
  senderId: string;
  content: string;
  messageType?: string;
  mediaUrl?: string;
  replyTo?: string;
  timestamp: number;
}

const QUEUE_KEY = 'gaga-message-queue';

function getQueue(): QueuedMessage[] {
  try {
    return JSON.parse(localStorage.getItem(QUEUE_KEY) || '[]');
  } catch {
    return [];
  }
}

function saveQueue(queue: QueuedMessage[]) {
  localStorage.setItem(QUEUE_KEY, JSON.stringify(queue));
}

function addToQueue(msg: QueuedMessage) {
  const queue = getQueue();
  queue.push(msg);
  saveQueue(queue);
}

function removeFromQueue(id: string) {
  const queue = getQueue().filter(m => m.id !== id);
  saveQueue(queue);
}

export function useOfflineQueue() {
  const { sendMessage } = useChatStore();
  const { sendGroupMessage } = useGroupStore();
  const isProcessing = useRef(false);

  const queueMessage = (msg: Omit<QueuedMessage, 'id' | 'timestamp'>) => {
    const queued: QueuedMessage = {
      ...msg,
      id: `${Date.now()}_${Math.random().toString(36).slice(2)}`,
      timestamp: Date.now(),
    };
    addToQueue(queued);
    toast.info('Message queued - will send when online');
  };

  const processQueue = async () => {
    if (isProcessing.current) return;
    isProcessing.current = true;

    const queue = getQueue();
    if (queue.length === 0) {
      isProcessing.current = false;
      return;
    }

    let sent = 0;
    for (const msg of queue) {
      try {
        if (msg.type === 'direct') {
          await sendMessage(msg.chatId, msg.senderId, msg.content, msg.messageType || 'text', msg.mediaUrl, msg.replyTo);
        } else {
          await sendGroupMessage(msg.chatId, msg.senderId, msg.content, msg.messageType || 'text', msg.mediaUrl, msg.replyTo);
        }
        removeFromQueue(msg.id);
        sent++;
      } catch (err) {
        // Keep in queue for next attempt
        console.error('Failed to send queued message:', err);
      }
    }

    if (sent > 0) {
      toast.success(`${sent} queued message${sent > 1 ? 's' : ''} sent`);
    }
    isProcessing.current = false;
  };

  useEffect(() => {
    const handleOnline = () => {
      toast.success('Back online');
      processQueue().catch(() => {});
    };

    const handleOffline = () => {
      toast.error('You are offline. Messages will be queued.');
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    // Process any existing queue on mount if online
    if (navigator.onLine) {
      processQueue().catch(() => {});
    }

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  return { queueMessage, processQueue };
}

export function isOnline() {
  return navigator.onLine;
}

import { useState, useEffect, useCallback } from 'react';
import { toast } from 'sonner';
import { useAuthStore } from '@/store/useAuthStore';
import {
  isFirebaseConfigured,
  getFcmToken,
  onForegroundMessage,
  getFirebaseMessaging,
  trackEvent,
} from '@/lib/firebase';

const VAPID_KEY = import.meta.env.VITE_FIREBASE_VAPID_KEY as string | undefined;

export function usePushNotifications() {
  const [permission, setPermission] = useState<NotificationPermission>('default');
  const [supported, setSupported] = useState(false);
  const [subscribed, setSubscribed] = useState(false);
  const [fcmToken, setFcmToken] = useState<string | null>(null);
  const { user } = useAuthStore();

  useEffect(() => {
    const check = () => {
      const isSupported =
        typeof window !== 'undefined' &&
        'Notification' in window &&
        'serviceWorker' in navigator;
      setSupported(isSupported);
      if (isSupported) {
        setPermission(Notification.permission);
      }
    };
    check();
  }, []);

  // Listen for foreground FCM messages
  useEffect(() => {
    if (!isFirebaseConfigured() || !VAPID_KEY) return;

    const unsubscribe = onForegroundMessage((payload) => {
      const title = payload.notification?.title || 'GaGa Chat';
      const body = payload.notification?.body || 'You have a new message';

      // Show toast for foreground messages
      toast.info(title, { description: body, duration: 5000 });

      // Also trigger a local notification if tab is not focused
      if (document.visibilityState === 'hidden') {
        sendLocalNotification(title, { body });
      }
    });

    return unsubscribe;
  }, []);

  const requestPermission = useCallback(async () => {
    if (!supported) {
      toast.error('Push notifications not supported on this device');
      return false;
    }

    try {
      const result = await Notification.requestPermission();
      setPermission(result);
      if (result === 'granted') {
        toast.success('Push notifications enabled!');

        // Try Firebase FCM first (preferred)
        if (isFirebaseConfigured() && VAPID_KEY) {
          try {
            const token = await getFcmToken(VAPID_KEY);
            if (token) {
              setFcmToken(token);
              setSubscribed(true);

              trackEvent('push_notification_subscribed', { method: 'fcm' });
              return true;
            }
          } catch (fcmErr) {
            console.warn('[FCM] Token acquisition failed, falling back to Web Push:', fcmErr);
          }
        }

        // Fallback: Web Push via service worker (legacy)
        const registration = await navigator.serviceWorker.ready;
        const subscription = await registration.pushManager.getSubscription();
        if (subscription) {
          setSubscribed(true);
          trackEvent('push_notification_subscribed', { method: 'web_push' });
        } else {
          setSubscribed(true); // Mark as subscribed even without FCM token
        }
        return true;
      } else if (result === 'denied') {
        toast.error('Notification permission denied. Enable in browser settings.');
        return false;
      }
      return false;
    } catch {
      toast.error('Failed to request notification permission');
      return false;
    }
  }, [supported, user?.id]);

  const sendLocalNotification = useCallback(
    (title: string, options?: NotificationOptions) => {
      if (!supported || permission !== 'granted') return;
      try {
        navigator.serviceWorker.ready.then((registration) => {
          registration.showNotification(title, {
            icon: '/icons/icon-192x192.png',
            badge: '/icons/icon-72x72.png',
            ...options,
          });
        });
      } catch {
        // Fallback
        new Notification(title, options);
      }
    },
    [supported, permission]
  );

  /** Delete the current FCM token (unsubscribe) */
  const unsubscribe = useCallback(async () => {
    const msg = getFirebaseMessaging();
    if (msg) {
      try {
        const { deleteToken } = await import('firebase/messaging');
        await deleteToken(msg);
      } catch {
        // Ignore
      }
    }
    setFcmToken(null);
    setSubscribed(false);
  }, [user?.id, fcmToken]);

  return {
    permission,
    supported,
    subscribed,
    fcmToken,
    requestPermission,
    sendLocalNotification,
    unsubscribe,
  };
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { useAuthStore } from '@/store/useAuthStore';
import { isSupabaseConfigured, getSupabase } from '@/lib/supabase';
import { getFirestoreDB } from '@/lib/firebase';
import { doc, setDoc, onSnapshot, serverTimestamp } from 'firebase/firestore';

export function useTyping(chatId: string | undefined) {
  const { user } = useAuthStore();
  const [typingUsers, setTypingUsers] = useState<Record<string, string>>({});
  const stopTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const isTypingRef = useRef(false);
  const unsubRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    if (!chatId || !user) {
      queueMicrotask(() => setTypingUsers({}));
      return;
    }

    const supabase = isSupabaseConfigured() ? getSupabase() : null;
    const db = getFirestoreDB();

    // ─── Supabase path ───
    if (supabase) {
      const channel = supabase
        .channel(`typing-${chatId}`)
        .on('postgres_changes', { event: '*', schema: 'public', table: 'typing', filter: `chat_id=eq.${chatId}` }, (payload) => {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const data = payload.new as any;
          if (!data || data.user_id === user.id) return;
          const now = Date.now();
          const ts = new Date(data.updated_at).getTime();
          if (data.is_typing && now - ts < 6000) {
            setTypingUsers((prev) => ({
              ...prev,
              [data.user_id]: String(data.user_name || '').replace(/[<>"&]/g, '').slice(0, 50),
            }));
          } else {
            setTypingUsers((prev) => {
              const next = { ...prev };
              delete next[data.user_id];
              return next;
            });
          }
        })
        .subscribe();

      return () => {
        supabase.removeChannel(channel);
        setTypingUsers({});
      };
    }

    // ─── Firebase fallback ───
    if (!db) return;

    const typingRef = doc(db, 'typing', chatId);
    const unsub = onSnapshot(typingRef, (snap) => {
      const data = snap.exists() ? snap.data() : null;
      if (!data) {
        setTypingUsers({});
        return;
      }
      const now = Date.now();
      const users: Record<string, string> = {};
      Object.entries(data).forEach(([key, value]) => {
        if (key === user.id) return;
        const typed = value as { name: string; timestamp: unknown };
        const ts = (typed.timestamp as { toMillis?: () => number }).toMillis?.() || new Date(typed.timestamp as string).getTime();
        if (now - ts < 6000) {
          users[key] = String(typed.name ?? '').replace(/[<>"&]/g, '').slice(0, 50);
        }
      });
      setTypingUsers(users);
    }, () => {});

    unsubRef.current = unsub;

    return () => {
      unsub();
      unsubRef.current = null;
      setTypingUsers({});
    };
  }, [chatId, user?.id]);

  useEffect(() => {
    return () => {
      if (stopTimerRef.current) clearTimeout(stopTimerRef.current);
    };
  }, []);

  const broadcast = useCallback(
    async (isTyping: boolean) => {
      if (!chatId || !user) return;

      const supabase = isSupabaseConfigured() ? getSupabase() : null;
      const db = getFirestoreDB();

      if (supabase) {
        await supabase.from('typing').upsert({
          id: `${chatId}_${user.id}`,
          chat_id: chatId,
          user_id: user.id,
          is_typing: isTyping,
          updated_at: new Date().toISOString(),
        }, { onConflict: 'id' });
        return;
      }

      if (!db) return;
      const typingRef = doc(db, 'typing', chatId);
      await setDoc(typingRef, {
        [user.id]: {
          name: user.name || 'User',
          timestamp: serverTimestamp(),
        },
      }, { merge: true });
    },
    [chatId, user]
  );

  const sendTyping = useCallback(() => {
    if (!isTypingRef.current) {
      isTypingRef.current = true;
      broadcast(true);
    }
    if (stopTimerRef.current) clearTimeout(stopTimerRef.current);
    stopTimerRef.current = setTimeout(() => {
      isTypingRef.current = false;
      broadcast(false);
    }, 4000);
  }, [broadcast]);

  const stopTyping = useCallback(() => {
    if (stopTimerRef.current) clearTimeout(stopTimerRef.current);
    if (isTypingRef.current) {
      isTypingRef.current = false;
      broadcast(false);
    }
  }, [broadcast]);

  return { typingUsers, sendTyping, stopTyping };
}

