                        <ChevronRight size={14} className="text-[#8D8D8D]" />
                      </button>
                    </div>
                  </div>
                </>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowLeft, Shield, UserPlus } from 'lucide-react';
import { useAuthStore } from '@/store/useAuthStore';
import { useFriendStore } from '@/store/useFriendStore';
import EmptyState from '@/components/EmptyState';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import { getDefaultAvatar, sanitizeMediaUrl } from '@/lib/utils';
import { toast } from 'sonner';

export default function BlockedUsersPage() {
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const { blockedUsers, loadingBlocked, unblockUser, getBlockedUsers } = useFriendStore();

  useEffect(() => {
    if (user?.id) {
      getBlockedUsers(user.id);
    }
  }, [user?.id, getBlockedUsers]);

  const handleUnblock = async (blockedId: string) => {
    if (!user?.id) return;
    try {
      await unblockUser(blockedId, user.id);
      toast.success('User unblocked');
    } catch (err: any) {
      toast.error(err.message || 'Failed to unblock user');
    }
  };

  return (
    <div className="min-h-[100dvh] bg-[#F5F5F5] flex flex-col">
      {/* Header */}
      <div className="bg-white border-b border-[#EBEBEB] flex items-center gap-3 p-4 sticky top-0 z-10">
        <button type="button" onClick={() => navigate(-1)} className="p-2 -ml-2 active:bg-gray-100 rounded-full text-[#111111]">
          <ArrowLeft size={22} />
        </button>
        <h1 className="text-lg font-bold text-[#111111]">Blocked Users</h1>
        <span className="ml-auto text-xs text-[#8D8D8D] font-medium">{blockedUsers.length} blocked</span>
      </div>

      <div className="flex-1 p-4 space-y-3">
        <AnimatePresence mode="wait">
          {loadingBlocked ? (
            <LoadingSkeleton count={4} variant="list" />
          ) : blockedUsers.length === 0 ? (
            <motion.div
              key="empty"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="h-64 flex items-center justify-center"
            >
              <EmptyState
                icon={Shield}
                title="No blocked users"
                description="Users you block will appear here"
              />
            </motion.div>
          ) : (
            <motion.div
              key="list"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="space-y-3"
            >
              {blockedUsers.map((record, i) => (
                <motion.div
                  key={record.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: i * 0.05 }}
                  className="bg-white border border-[#EBEBEB] rounded-xl p-4 flex items-center gap-3"
                >
                  <div className="w-12 h-12 rounded-full bg-[#F5F5F5] flex items-center justify-center overflow-hidden shrink-0">
                    {sanitizeMediaUrl(record.blockedUser?.avatar) ? (
                      <img src={sanitizeMediaUrl(record.blockedUser?.avatar)} className="w-full h-full object-cover" alt="User avatar" />
                    ) : (
                      <img src={getDefaultAvatar(record.blockedUser?.id || record.blockedUser?.name || 'U')} className="w-full h-full object-cover" alt="User avatar" />
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-[#111111] text-sm font-medium">{record.blockedUser?.name || 'User'}</p>
                    <p className="text-[#8D8D8D] text-xs">@{record.blockedUser?.username || record.blockedId.slice(0, 8)}</p>
                    {record.reason && (
                      <p className="text-[#8D8D8D] text-[11px] mt-0.5 truncate">Reason: {record.reason}</p>
                    )}
                  </div>
                  <button type="button" onClick={() => handleUnblock(record.blockedId)}
                    className="flex items-center gap-1 px-3 py-1.5 bg-[#00C300]/10 text-[#00C300] text-xs rounded-full font-medium active:bg-[#00C300]/20 transition-colors"
                  >
                    <UserPlus size={12} /> Unblock
                  </button>
                </motion.div>
              ))}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import { useAuthStore } from '@/store/useAuthStore';
import { useEnhancedTimelineStore } from '@/store/useEnhancedTimelineStore';
import { Bookmark, Search, Plus, Folder, Clock, Heart, X, Trash2, Image } from 'lucide-react';
import { getDefaultAvatar } from '@/lib/utils';

export default function BookmarksPage() {
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const { savedPosts, loadingSaved, getSavedPosts, bookmarkCollections, createCollection } = useEnhancedTimelineStore();
  const [search, setSearch] = useState('');
  const [activeCollection, setActiveCollection] = useState<string | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCollectionName, setNewCollectionName] = useState('');
  const [sortBy, setSortBy] = useState<'newest' | 'oldest' | 'most_liked'>('newest');

  useEffect(() => {
    if (user?.id) getSavedPosts(user.id);
  }, [user?.id, getSavedPosts]);

  const filtered = savedPosts.filter((p) => {
    const match = search.toLowerCase();
    return (
      p.content.toLowerCase().includes(match) ||
      p.userName?.toLowerCase().includes(match) ||
      p.hashtags?.some((h) => h.toLowerCase().includes(match))
    );
  });

  const sorted = [...filtered].sort((a, b) => {
    if (sortBy === 'newest') return b.timestamp.getTime() - a.timestamp.getTime();
    if (sortBy === 'oldest') return a.timestamp.getTime() - b.timestamp.getTime();
    if (sortBy === 'most_liked') return (b.likes?.length || 0) - (a.likes?.length || 0);
    return 0;
  });

  const handleCreateCollection = () => {
    if (!newCollectionName.trim() || !user?.id) return;
    createCollection(user.id, newCollectionName.trim());
    setNewCollectionName('');
    setShowCreateModal(false);
  };

  return (
    <div className="min-h-[100dvh] bg-white">
      {/* Header */}
      <div className="sticky top-0 bg-white border-b border-gray-100 z-10 px-4 py-3">
        <div className="flex items-center gap-3">
          <button type="button" onClick={() => navigate(-1)} className="p-2 hover:bg-gray-100 rounded-full">
            <X size={20} className="text-gray-500" />
          </button>
          <h1 className="font-bold text-lg text-gray-900">Saved Posts</h1>
        </div>
      </div>

      {/* Search */}
      <div className="px-4 py-3">
        <div className="relative">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search saved posts..."
            className="w-full pl-9 pr-3 py-2.5 bg-gray-100 rounded-xl text-sm outline-none focus:ring-2 focus:ring-[#00C300]/20"
          />
        </div>
      </div>

      {/* Collections */}
      <div className="px-4 pb-3">
        <div className="flex items-center gap-2 overflow-x-auto pb-1">
          <button type="button" onClick={() => setActiveCollection(null)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap transition-colors ${activeCollection === null ? 'bg-[#00C300] text-white' : 'bg-gray-100 text-gray-600'}`}
          >
            <Bookmark size={12} /> All ({savedPosts.length})
          </button>
          <button type="button" onClick={() => setShowCreateModal(true)}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium bg-gray-100 text-gray-600 hover:bg-gray-200 transition-colors"
          >
            <Plus size={12} /> New Collection
          </button>
          {bookmarkCollections.map((c) => (
            <button type="button" key={c.id}
              onClick={() => setActiveCollection(c.id)}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap transition-colors ${activeCollection === c.id ? 'bg-[#00C300] text-white' : 'bg-gray-100 text-gray-600'}`}
            >
              <Folder size={12} /> {c.name} ({c.count})
            </button>
          ))}
        </div>
      </div>

      {/* Sort */}
      <div className="px-4 pb-2 flex items-center gap-2">
        <span className="text-xs text-gray-400">Sort by:</span>
        {(['newest', 'oldest', 'most_liked'] as const).map((s) => (
          <button type="button" key={s}
            onClick={() => setSortBy(s)}
            className={`text-xs px-2 py-1 rounded-full transition-colors ${sortBy === s ? 'bg-[#00C300]/10 text-[#00C300]' : 'text-gray-400 hover:text-gray-600'}`}
          >
            {s === 'most_liked' ? 'Most Liked' : s === 'newest' ? 'Newest' : 'Oldest'}
          </button>
        ))}
      </div>

      {/* Saved posts */}
      <div className="px-4 pb-8">
        {loadingSaved ? (
          <div className="flex justify-center py-12">
            <div className="w-8 h-8 border-2 border-gray-200 border-t-[#00C300] rounded-full animate-spin" />
          </div>
        ) : sorted.length === 0 ? (
          <div className="text-center py-16">
            <Bookmark size={48} className="mx-auto text-gray-200 mb-4" />
            <p className="text-gray-400 font-medium">No saved posts yet</p>
            <p className="text-gray-300 text-sm mt-1">Save posts from your timeline to view them here</p>
          </div>
        ) : (
          <div className="space-y-3">
            {sorted.map((post) => (
              <motion.div
                key={post.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-white border border-gray-100 rounded-xl p-3 cursor-pointer hover:shadow-sm transition-shadow"
                onClick={() => navigate(`/timeline`)}
              >
                <div className="flex items-start gap-3">
                  {post.images?.[0] ? (
                    <div className="w-16 h-16 rounded-lg bg-gray-100 overflow-hidden shrink-0">
                      <img src={post.images[0]} alt="Post image" className="w-full h-full object-cover" />
                    </div>
                  ) : (
                    <div className="w-16 h-16 rounded-lg bg-gray-100 flex items-center justify-center shrink-0">
                      <Image size={20} className="text-gray-300" />
                    </div>
                  )}
                  <div className="flex-1 min-w-0">
                    <p className="text-sm text-gray-900 line-clamp-2">{post.content}</p>
                    <div className="flex items-center gap-2 mt-1.5">
                      <div className="w-5 h-5 rounded-full bg-gray-200 overflow-hidden">
                        <img src={post.userAvatar || getDefaultAvatar(post.userName || 'U')} alt="User avatar" className="w-full h-full object-cover" />
                      </div>
                      <span className="text-xs text-gray-500">{post.userName || 'User'}</span>
                      <span className="text-xs text-gray-400">·</span>
                      <span className="text-xs text-gray-400 flex items-center gap-0.5">
                        <Clock size={10} /> {post.timestamp.toLocaleDateString()}
                      </span>
                    </div>
                    <div className="flex items-center gap-3 mt-2">
                      <span className="text-xs text-gray-400 flex items-center gap-1">
                        <Heart size={12} /> {post.likes?.length || 0}
                      </span>
                      <span className="text-xs text-gray-400">
                        {post.comments?.length || 0} comments
                      </span>
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        )}
      </div>

      {/* Create collection modal */}
      <AnimatePresence>
        {showCreateModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/40 z-50 flex items-center justify-center p-4"
            onClick={() => setShowCreateModal(false)}
          >
            <motion.div
              initial={{ scale: 0.9 }}
              animate={{ scale: 1 }}
              exit={{ scale: 0.9 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white rounded-2xl p-5 w-full max-w-sm"
            >
              <h3 className="font-bold text-gray-900 mb-3">New Collection</h3>
              <input
                type="text"
                value={newCollectionName}
                onChange={(e) => setNewCollectionName(e.target.value)}
                placeholder="Collection name..."
                className="w-full px-3 py-2.5 bg-gray-100 rounded-xl text-sm outline-none focus:ring-2 focus:ring-[#00C300]/20 mb-4"
                onKeyDown={(e) => { if (e.key === 'Enter') handleCreateCollection(); }}
                autoFocus
              />
              <div className="flex gap-2">
                <button type="button" onClick={() => setShowCreateModal(false)}
                  className="flex-1 py-2.5 rounded-xl text-sm font-medium text-gray-600 bg-gray-100"
                >
                  Cancel
                </button>
                <button type="button" onClick={handleCreateCollection}
                  className="flex-1 py-2.5 rounded-xl text-sm font-medium text-white bg-[#00C300]"
                >
                  Create
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  ArrowLeft, Plus, Users, Trash2, Send, Check, X, ChevronRight, Search
} from 'lucide-react';
import { useAuthStore } from '@/store/useAuthStore';
import { useFriendStore } from '@/store/useFriendStore';
import { getDefaultAvatar, sanitizeMediaUrl } from '@/lib/utils';
import { toast } from 'sonner';
import EmptyState from '@/components/EmptyState';
import LoadingSkeleton from '@/components/LoadingSkeleton';

export default function BroadcastListsPage() {
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const { friends, loadingFriends, subscribeFriends, getBroadcastLists, createBroadcastList, deleteBroadcastList } = useFriendStore();
  const [lists, setLists] = useState<any[]>([]);
  const [loadingLists, setLoadingLists] = useState(true);
  const [showCreate, setShowCreate] = useState(false);
  const [listName, setListName] = useState('');
  const [selectedFriends, setSelectedFriends] = useState<string[]>([]);
  const [friendSearch, setFriendSearch] = useState('');
  const [deleteConfirm, setDeleteConfirm] = useState<string | null>(null);

  useEffect(() => {
    if (!user?.id) return;
    const unsub = subscribeFriends(user.id);
    return () => unsub();
  }, [user?.id, subscribeFriends]);

  useEffect(() => {
    if (!user?.id) return;
    const load = async () => {
      setLoadingLists(true);
      const data = await getBroadcastLists(user.id);
      setLists(data || []);
      setLoadingLists(false);
    };
    load();
  }, [user?.id, getBroadcastLists]);

  const handleCreate = async () => {
    if (!user?.id || !listName.trim() || selectedFriends.length === 0) {
      toast.error('Please enter a name and select at least one recipient');
      return;
    }
    const id = await createBroadcastList(user.id, listName.trim(), selectedFriends);
    if (id) {
      toast.success('Broadcast list created');
      setShowCreate(false);
      setListName('');
      setSelectedFriends([]);
      const data = await getBroadcastLists(user.id);
      setLists(data || []);
    }
  };

  const handleDelete = async (listId: string) => {
    await deleteBroadcastList(listId);
    toast.success('Broadcast list deleted');
    setDeleteConfirm(null);
    if (user?.id) {
      const data = await getBroadcastLists(user.id);
      setLists(data || []);
    }
  };

  const toggleFriend = (id: string) => {
    setSelectedFriends(prev =>
      prev.includes(id) ? prev.filter(f => f !== id) : [...prev, id]
    );
  };

  const filteredFriends = friends.filter(f => {
    const q = friendSearch.toLowerCase();
    return f.name?.toLowerCase().includes(q) || f.username?.toLowerCase().includes(q);
  });

  return (
    <div className="h-[100dvh] bg-[#F5F5F5] flex flex-col">
      {/* Header */}
      <div className="bg-white border-b border-[#EBEBEB] shrink-0">
        <div className="flex items-center gap-3 p-4">
          <button type="button" onClick={() => navigate(-1)} className="p-2 -ml-2 hover:bg-[#F5F5F5] rounded-full text-[#111111]">
            <ArrowLeft size={22} />
          </button>
          <h1 className="text-lg font-bold text-[#111111] flex-1">Broadcast Lists</h1>
          <button type="button" onClick={() => setShowCreate(true)} className="p-2 hover:bg-[#F5F5F5] rounded-full text-[#00C300]">
            <Plus size={22} />
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4">
        {loadingLists ? (
          <LoadingSkeleton count={3} variant="list" />
        ) : lists.length === 0 ? (
          <EmptyState
            icon={Users}
            title="No broadcast lists"
            description="Create a broadcast list to send messages to multiple contacts at once"
            action={
              <button type="button" onClick={() => setShowCreate(true)}
                className="px-4 py-2 bg-[#00C300] text-white rounded-full text-sm font-medium"
              >
                New Broadcast List
              </button>
            }
          />
        ) : (
          <div className="space-y-2">
            {lists.map((list, i) => (
              <motion.div
                key={list.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.05 }}
                className="bg-white rounded-2xl border border-[#EBEBEB] overflow-hidden"
              >
                <div className="flex items-center gap-3 p-4">
                  <div className="w-10 h-10 rounded-full bg-[#00C300]/10 flex items-center justify-center shrink-0">
                    <Users size={18} className="text-[#00C300]" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-[#111111] text-sm font-medium truncate">{list.name}</p>
                    <p className="text-[#8D8D8D] text-xs">{(list.recipientIds || []).length} recipients</p>
                  </div>
                  <div className="flex items-center gap-1">
                    <button
                      type="button"
                      onClick={() => setDeleteConfirm(list.id)}
                      className="p-2 hover:bg-[#FF3B30]/10 rounded-full text-[#FF3B30] transition-colors"
                    >
                      <Trash2 size={16} />
                    </button>
                    <ChevronRight size={16} className="text-[#C7C7CC]" />
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        )}
      </div>

      {/* Create Broadcast List Modal */}
      <AnimatePresence>
        {showCreate && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4"
            onClick={() => setShowCreate(false)}
          >
            <motion.div
              initial={{ y: '100%' }}
              animate={{ y: 0 }}
              exit={{ y: '100%' }}
              transition={{ type: 'spring', damping: 25, stiffness: 300 }}
              className="bg-white rounded-t-2xl sm:rounded-2xl w-full max-w-sm max-h-[85vh] flex flex-col"
              onClick={e => e.stopPropagation()}
            >
              <div className="p-4 border-b border-[#EBEBEB] flex items-center justify-between shrink-0">
                <h3 className="text-lg font-bold text-[#111111]">New Broadcast List</h3>
                <button type="button" onClick={() => setShowCreate(false)} className="p-2 hover:bg-[#F5F5F5] rounded-full">
                  <X size={20} className="text-[#8D8D8D]" />
                </button>
              </div>

              <div className="p-4 space-y-4 overflow-y-auto flex-1">
                <div>
                  <label className="text-[#8D8D8D] text-xs mb-1 block">List Name</label>
                  <input
                    value={listName}
                    onChange={e => setListName(e.target.value)}
                    placeholder="e.g., Team, Family, Work"
                    className="w-full bg-[#F5F5F5] rounded-xl px-4 py-3 text-[#111111] text-sm focus:outline-none focus:ring-2 focus:ring-[#00C300] placeholder:text-[#8D8D8D]"
                  />
                </div>

                <div>
                  <label className="text-[#8D8D8D] text-xs mb-1 block">
                    Select Recipients ({selectedFriends.length} selected)
                  </label>
                  <div className="bg-[#F5F5F5] rounded-xl p-2.5 flex items-center gap-2 mb-2">
                    <Search size={16} className="text-[#8D8D8D] ml-1" />
                    <input
                      type="text"
                      placeholder="Search friends..."
                      value={friendSearch}
                      onChange={e => setFriendSearch(e.target.value)}
                      className="bg-transparent border-none focus:outline-none text-[15px] w-full text-[#111111] placeholder-[#8D8D8D]"
                    />
                  </div>

                  {loadingFriends ? (
                    <LoadingSkeleton count={3} variant="list" />
                  ) : filteredFriends.length === 0 ? (
                    <p className="text-[#8D8D8D] text-sm text-center py-4">No friends found</p>
                  ) : (
                    <div className="space-y-1">
                      {filteredFriends.map(f => {
                        const isSelected = selectedFriends.includes(f.id);
                        return (
                          <button
                            type="button"
                            key={f.id}
                            onClick={() => toggleFriend(f.id)}
                            className={`w-full flex items-center gap-3 p-3 rounded-xl transition-colors text-left ${
                              isSelected ? 'bg-[#00C300]/10 border border-[#00C300]/20' : 'hover:bg-[#F5F5F5]'
                            }`}
                          >
                            <div className="w-10 h-10 rounded-full bg-[#F5F5F5] flex items-center justify-center overflow-hidden shrink-0">
                              {sanitizeMediaUrl(f.avatar) ? (
                                <img src={sanitizeMediaUrl(f.avatar)} className="w-full h-full object-cover" alt="User avatar" />
                              ) : (
                                <img src={getDefaultAvatar(f.id || f.name || 'U')} className="w-full h-full object-cover" alt="User avatar" />
                              )}
                            </div>
                            <div className="flex-1 min-w-0">
                              <p className="text-[#111111] text-sm font-medium">{f.name}</p>
                              <p className="text-[#8D8D8D] text-xs">@{f.username}</p>
                            </div>
                            <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 ${
                              isSelected ? 'border-[#00C300] bg-[#00C300]' : 'border-[#C7C7CC]'
                            }`}>
                              {isSelected && <Check size={12} className="text-white" />}
                            </div>
                          </button>
                        );
                      })}
                    </div>
                  )}
                </div>
              </div>

              <div className="p-4 border-t border-[#EBEBEB] shrink-0">
                <button
                  type="button"
                  onClick={handleCreate}
                  disabled={!listName.trim() || selectedFriends.length === 0}
                  className="w-full py-3 bg-[#00C300] text-white rounded-xl text-sm font-bold disabled:opacity-50 transition-colors"
                >
                  Create List
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Delete Confirm */}
      <AnimatePresence>
        {deleteConfirm && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4"
            onClick={() => setDeleteConfirm(null)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="bg-white rounded-2xl p-6 max-w-sm w-full"
              onClick={e => e.stopPropagation()}
            >
              <h3 className="text-lg font-bold text-[#111111] mb-2">Delete Broadcast List?</h3>
              <p className="text-[#8D8D8D] text-sm mb-4">This action cannot be undone.</p>
              <div className="flex gap-2">
                <button type="button" onClick={() => setDeleteConfirm(null)}
                  className="flex-1 py-3 bg-[#F5F5F5] text-[#111111] rounded-xl text-sm font-bold"
                >
                  Cancel
                </button>
                <button type="button" onClick={() => handleDelete(deleteConfirm)}
                  className="flex-1 py-3 bg-[#FF3B30] text-white rounded-xl text-sm font-bold"
                >
                  Delete
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { PhoneOff, Mic, MicOff, Video, VideoOff, RefreshCw, Wifi, WifiOff, Signal, SignalHigh, SignalMedium, SignalLow, ArrowLeft, Phone, MessageSquare, RotateCcw, Home, Clock, Star, ThumbsUp, ThumbsDown } from 'lucide-react';
import { useAuthStore } from '@/store/useAuthStore';
import { useFriendStore } from '@/store/useFriendStore';
import { useCallStore } from '@/store/useCallStore';
import { WebRTCCall } from '@/lib/webrtc';

export default function CallPage() {
  const location = useLocation();
  const navigate = useNavigate();
  const { userId, mode } = (location.state || {}) as { userId?: string; mode?: 'voice' | 'video' };
  const { user: currentUser } = useAuthStore();
  const { friends } = useFriendStore();
  const { startCall, endCall, currentCall, subscribeCalls } = useCallStore();

  const [networkQuality, setNetworkQuality] = useState<'excellent' | 'good' | 'fair' | 'poor'>('good');
  const [showEndScreen, setShowEndScreen] = useState(false);
  const [callStats, setCallStats] = useState({ duration: 0, quality: 'good' as string });
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOn, setIsVideoOn] = useState(true);
  const [callDuration, setCallDuration] = useState(0);

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const localVideoRef = useRef<HTMLVideoElement>(null);
  const remoteVideoRef = useRef<HTMLVideoElement>(null);
  const webrtcRef = useRef<WebRTCCall | null>(null);
  const callStartedRef = useRef(false);

  const friend = friends.find(f => f.id === userId);
  const isVideo = mode === 'video';
  const isConnected = currentCall?.status === 'connected';
  const callStatus = currentCall?.status || 'calling';

  // Subscribe to call updates
  useEffect(() => {
    if (!currentUser?.id) return;
    return subscribeCalls(currentUser.id);
  }, [currentUser?.id]);

  // Network quality monitoring (simplified - checks connection state)
  useEffect(() => {
    if (!isConnected || !webrtcRef.current) return;
    const interval = setInterval(() => {
      try {
        const pc = (webrtcRef.current as any)?.peerConnection;
        if (!pc) return;
        pc.getStats().then((stats: any) => {
          let packetsLost = 0;
          let packetsReceived = 0;
          let jitter = 0;
          stats.forEach((report: any) => {
            if (report.type === 'inbound-rtp' && report.kind === 'audio') {
              packetsLost += report.packetsLost || 0;
              packetsReceived += report.packetsReceived || 0;
              jitter = report.jitter || 0;
            }
          });
          const lossRate = packetsReceived > 0 ? packetsLost / packetsReceived : 0;
          if (lossRate < 0.01 && jitter < 0.05) setNetworkQuality('excellent');
          else if (lossRate < 0.03 && jitter < 0.1) setNetworkQuality('good');
          else if (lossRate < 0.08 && jitter < 0.2) setNetworkQuality('fair');
          else setNetworkQuality('poor');
        });
      } catch { /* ignore stats errors */ }
    }, 3000);
    return () => clearInterval(interval);
  }, [isConnected]);

  const handleEndCall = async () => {
    if (timerRef.current) clearInterval(timerRef.current);
    webrtcRef.current?.endCall();
    webrtcRef.current = null;
    callStartedRef.current = false;
    const duration = callDuration;
    await endCall();
    setCallStats({ duration, quality: networkQuality });
    setShowEndScreen(true);
  };

  const handleCloseEndScreen = () => {
    setShowEndScreen(false);
    navigate(-1);
  };

  // Initiate the call
  useEffect(() => {
    if (!userId || !currentUser || callStartedRef.current) return;
    callStartedRef.current = true;

    (async () => {
      try {
        const callId = await startCall(userId, currentUser.id, isVideo ? 'video' : 'voice');
        if (!callId) return;

        const webrtc = new WebRTCCall(
          currentUser.id,
          userId,
          isVideo,
          (state) => { if (state === 'ended') void handleEndCall(); },
          (stream) => { if (remoteVideoRef.current) remoteVideoRef.current.srcObject = stream; },
          (stream) => { if (localVideoRef.current) localVideoRef.current.srcObject = stream; }
        );
        webrtcRef.current = webrtc;
        await webrtc.startCall(callId);
      } catch (err) {
        console.error('Call init failed:', err);
      }
    })();

    return () => {
      webrtcRef.current?.endCall();
      webrtcRef.current = null;
    };
  }, [userId, currentUser?.id, isVideo]);

  // Duration timer
  useEffect(() => {
    if (isConnected) {
      timerRef.current = setInterval(() => setCallDuration(d => d + 1), 1000);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isConnected]);
  const formatDuration = (s: number) => {
    const m = Math.floor(s / 60);
    const sec = s % 60;
    return `${m}:${sec.toString().padStart(2, '0')}`;
  };

  if (!userId) {
    return (
      <div className="h-[100dvh] bg-white flex items-center justify-center">
        <p className="text-[#8D8D8D]">No call in progress</p>
      </div>
    );
  }

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="h-[100dvh] bg-[#111111] flex flex-col relative">
      {/* Quality indicator */}
      {isConnected && (
        <div className="absolute top-4 left-4 z-20 flex items-center gap-1.5 bg-black/40 backdrop-blur-sm rounded-full px-3 py-1.5">
          {networkQuality === 'excellent' && <SignalHigh size={14} className="text-[#00C300]" />}
          {networkQuality === 'good' && <Signal size={14} className="text-[#00C300]" />}
          {networkQuality === 'fair' && <SignalMedium size={14} className="text-[#FF9800]" />}
          {networkQuality === 'poor' && <SignalLow size={14} className="text-[#FF3B30]" />}
          <span className={`text-xs font-medium capitalize ${
            networkQuality === 'excellent' || networkQuality === 'good' ? 'text-[#00C300]' :
            networkQuality === 'fair' ? 'text-[#FF9800]' : 'text-[#FF3B30]'
          }`}>
            {networkQuality}
          </span>
        </div>
      )}

      {isVideo && (
        <>
          <video ref={remoteVideoRef} autoPlay playsInline className="absolute inset-0 w-full h-full object-cover" />
          <video ref={localVideoRef} autoPlay muted playsInline className="absolute top-4 right-4 w-32 h-40 rounded-lg object-cover shadow-lg bg-black/50 z-10" />
        </>
      )}

      <div className="flex-1 flex items-center justify-center relative z-10">
        <div className="text-center">
          <motion.div
            initial={{ scale: 0.8 }}
            animate={{ scale: 1 }}
            className="w-28 h-28 rounded-full bg-[#F5F5F5] flex items-center justify-center mx-auto mb-6 shadow-2xl overflow-hidden"
          >
            {friend?.avatar ? (
              <img src={friend.avatar} className="w-full h-full object-cover" alt="User avatar" />
            ) : (
              <span className="text-[#111111] text-4xl font-bold">{(friend?.name || 'U')[0]}</span>
            )}
          </motion.div>
          <h2 className="text-white text-xl font-semibold">{friend?.name || 'User'}</h2>
          <p className="text-white/50 mt-1 text-sm">
            {callStatus === 'calling' ? 'Calling...' : callStatus === 'connected' ? formatDuration(callDuration) : 'Call ended'}
          </p>
        </div>
      </div>

      <div className="shrink-0 pb-16 px-8 relative z-10">
        <div className="flex items-center justify-center gap-6">
          <motion.button
            whileTap={{ scale: 0.95 }}
            onClick={() => { const next = !isMuted; setIsMuted(next); webrtcRef.current?.toggleAudio(!next); }}
            className={`w-14 h-14 rounded-full flex items-center justify-center transition-colors ${isMuted ? 'bg-[#FF3B30]' : 'bg-white/10'}`}
          >
            {isMuted ? <MicOff size={24} className="text-white" /> : <Mic size={24} className="text-white" />}
          </motion.button>

          {isVideo && (
            <motion.button
              whileTap={{ scale: 0.95 }}
              onClick={() => { const next = !isVideoOn; setIsVideoOn(next); webrtcRef.current?.toggleVideo(next); }}
              className={`w-14 h-14 rounded-full flex items-center justify-center transition-colors ${!isVideoOn ? 'bg-[#FF3B30]' : 'bg-white/10'}`}
            >
              {isVideoOn ? <Video size={24} className="text-white" /> : <VideoOff size={24} className="text-white" />}
            </motion.button>
          )}

          {isVideo && (
            <motion.button
              whileTap={{ scale: 0.95 }}
              onClick={() => { webrtcRef.current?.flipCamera(); }}
              className="w-14 h-14 rounded-full bg-white/10 flex items-center justify-center"
            >
              <RefreshCw size={24} className="text-white" />
            </motion.button>
          )}

          <motion.button
            whileTap={{ scale: 0.95 }}
            onClick={handleEndCall}
            className="w-16 h-16 rounded-full bg-[#FF3B30] flex items-center justify-center shadow-lg"
          >
            <PhoneOff size={28} className="text-white" />
          </motion.button>
        </div>
      </div>

      {/* Call End Screen */}
      <AnimatePresence>
        {showEndScreen && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 z-50 bg-[#111111] flex flex-col items-center justify-center p-6"
          >
            <div className="text-center max-w-sm">
              <div className="w-20 h-20 rounded-full bg-[#F5F5F5] flex items-center justify-center mx-auto mb-4">
                <Phone size={32} className="text-[#00C300]" />
              </div>
              <h2 className="text-white text-xl font-bold mb-1">Call Ended</h2>
              <p className="text-white/50 text-sm mb-6">with {friend?.name || 'User'}</p>

              <div className="bg-white/5 rounded-2xl p-4 mb-6">
                <div className="flex items-center justify-center gap-2 mb-2">
                  <Clock size={16} className="text-white/50" />
                  <span className="text-white text-lg font-bold">{formatDuration(callStats.duration)}</span>
                </div>
                <div className="flex items-center justify-center gap-2">
                  {callStats.quality === 'excellent' && <Star size={14} className="text-[#FFD700]" />}
                  {callStats.quality === 'good' && <ThumbsUp size={14} className="text-[#00C300]" />}
                  {callStats.quality === 'fair' && <ThumbsUp size={14} className="text-[#FF9800]" />}
                  {callStats.quality === 'poor' && <ThumbsDown size={14} className="text-[#FF3B30]" />}
                  <span className={`text-sm capitalize ${
                    callStats.quality === 'excellent' ? 'text-[#FFD700]' :
                    callStats.quality === 'good' ? 'text-[#00C300]' :
                    callStats.quality === 'fair' ? 'text-[#FF9800]' : 'text-[#FF3B30]'
                  }`}>
                    {callStats.quality} quality
                  </span>
                </div>
              </div>

              <div className="flex gap-3">
                <button type="button" onClick={() => { setShowEndScreen(false); navigate(`/chat/${userId}`); }}
                  className="flex-1 py-3 bg-white/10 text-white rounded-xl text-sm font-medium hover:bg-white/20 transition-colors flex items-center justify-center gap-2"
                >
                  <MessageSquare size={16} /> Message
                </button>
                <button type="button" onClick={() => { setShowEndScreen(false); window.location.reload(); }}
                  className="flex-1 py-3 bg-[#00C300] text-white rounded-xl text-sm font-bold hover:bg-[#00A300] transition-colors flex items-center justify-center gap-2"
                >
                  <RotateCcw size={16} /> Call Back
                </button>
              </div>
              <button type="button" onClick={handleCloseEndScreen}
                className="w-full mt-3 py-3 text-white/50 text-sm hover:text-white transition-colors flex items-center justify-center gap-2"
              >
                <Home size={16} /> Go Home
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Search, MessageCircle, Plus, Users, UserPlus, Archive } from 'lucide-react';
import { useAuthStore } from '@/store/useAuthStore';
import { useFilteredOnline } from '@/hooks/usePresence';
import { useChatStore } from '@/store/useChatStore';
import { useGroupStore } from '@/store/useGroupStore';
import { useFriendStore } from '@/store/useFriendStore';
import { usePageTitle } from '@/hooks/useDocumentTitle';
import BottomNav from '@/components/layout/BottomNav';
import EmptyState from '@/components/EmptyState';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import { formatTime, getDefaultAvatar, sanitizeMediaUrl } from '@/lib/utils';
import { toast } from 'sonner';

export default function ChatsPage() {
  const navigate = useNavigate();
  usePageTitle('Chats');
  const { user } = useAuthStore();
  const { chats, loadingChats, subscribeChats, archiveChat, unarchiveChat } = useChatStore();
  const { groups, loading: loadingGroups, subscribeGroups } = useGroupStore();
  const { friends, sendRequest } = useFriendStore();
  const { filtered: visibleOnline } = useFilteredOnline(user?.id || '', friends);
  const [search, setSearch] = useState('');
  const [activeTab, setActiveTab] = useState<'all' | 'direct' | 'groups' | 'archived'>('all');
  const [refreshing, setRefreshing] = useState(false);
  const refreshTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (refreshTimeoutRef.current) clearTimeout(refreshTimeoutRef.current);
    };
  }, []);

  useEffect(() => {
    if (!user) return;
    const unsubChats = subscribeChats(user.id);
    const unsubGroups = subscribeGroups(user.id);
    return () => { unsubChats(); unsubGroups(); };
  }, [user]);

  const handleRefresh = useCallback(() => {
    if (!user?.id || refreshing) return;
    setRefreshing(true);
    // Existing subscriptions already handle real-time updates.
    // Just show a brief visual refresh indicator.
    refreshTimeoutRef.current = setTimeout(() => setRefreshing(false), 800);
  }, [user?.id, refreshing]);

  // Combine chats and groups, deduplicate by id
  const allChatsMap = new Map<string, typeof chats[0] & { itemType: 'direct' | 'group' }>();
  chats.forEach(c => allChatsMap.set(c.id, { ...c, itemType: 'direct' as const }));
  groups.forEach(g => allChatsMap.set(g.id, { ...g, itemType: 'group' as const }));
  const allChats = Array.from(allChatsMap.values()).sort((a, b) => {
    const aTime = a.updatedAt ? new Date(a.updatedAt).getTime() : 0;
    const bTime = b.updatedAt ? new Date(b.updatedAt).getTime() : 0;
    return bTime - aTime;
  });

  const activeChats = allChats.filter(c => !c.archived);
  const archivedChats = allChats.filter(c => c.archived);

  const filtered = (activeTab === 'archived' ? archivedChats : activeChats).filter(c => {
    if (activeTab === 'direct') return c.itemType === 'direct';
    if (activeTab === 'groups') return c.itemType === 'group';
    if (activeTab === 'archived') return true;
    return true;
  }).filter(c => {
    if (!search) return true;
    if (c.type === 'group') return c.name?.toLowerCase().includes(search.toLowerCase());
    const otherId = c.participants.find(p => p !== user?.id) || '';
    const f = friends.find(fr => fr.id === otherId);
    const name = f?.name || 'Chat';
    return name.toLowerCase().includes(search.toLowerCase());
  });

  const totalUnread = activeChats.reduce((sum, c) => sum + (c.unreadCount || 0), 0);

  return (
    <div className="h-[100dvh] bg-white flex flex-col relative">
      {/* Header */}
      <div className="shrink-0 px-5 py-4 flex justify-between items-center border-b border-[#EBEBEB]">
        <div>
          <h1 className="text-2xl font-bold text-[#111111]">Chats</h1>
          {totalUnread > 0 && <p className="text-[#00C300] text-xs font-medium">{totalUnread} unread</p>}
        </div>
        <div className="flex gap-3 text-[#111111]">
          <button type="button" onClick={() => navigate('/add-friends')} className="p-2 hover:bg-gray-50 rounded-full transition-colors" title="Add friends">
            <UserPlus size={22} strokeWidth={1.5} />
          </button>
          <button type="button" onClick={() => navigate('/create-group')} className="p-2 hover:bg-gray-50 rounded-full transition-colors" title="New group">
            <Plus size={22} strokeWidth={1.5} />
          </button>
        </div>
      </div>

      {/* Search */}
      <div className="shrink-0 px-4 py-2">
        <div className="relative">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8D8D8D]" />
          <input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Search chats..."
            className="w-full bg-[#F5F5F5] rounded-xl pl-10 pr-4 py-2.5 text-[#111111] text-sm focus:outline-none focus:ring-2 focus:ring-[#00C300] placeholder:text-[#8D8D8D]"
          />
        </div>
      </div>

      {/* Tabs */}
      <div className="shrink-0 flex border-b border-[#EBEBEB] px-4">
        {(['all', 'direct', 'groups', 'archived'] as const).map(tab => (
          <button type="button" key={tab}
            onClick={() => setActiveTab(tab)}
            className={`flex-1 py-3 text-sm font-medium transition-colors capitalize ${
              activeTab === tab
                ? 'text-[#00C300] border-b-2 border-[#00C300]'
                : 'text-[#8D8D8D]'
            }`}
          >
            {tab === 'all' ? `All (${activeChats.length})` : tab === 'direct' ? 'Direct' : tab === 'groups' ? 'Groups' : `Archived (${archivedChats.length})`}
          </button>
        ))}
      </div>

      {/* Chat List */}
      <div
        className="flex-1 overflow-y-auto scrollbar-hide scroll-smooth relative"
        onTouchStart={(e) => {
          const el = e.currentTarget;
          if (el.scrollTop <= 0) {
            const startY = e.touches[0].clientY;
            const handleMove = (me: TouchEvent) => {
              const diff = me.touches[0].clientY - startY;
              if (diff > 80) {
                handleRefresh();
                el.removeEventListener('touchmove', handleMove);
              }
            };
            el.addEventListener('touchmove', handleMove, { once: true });
          }
        }}
      >
        {/* Pull to refresh */}
        {refreshing && (
          <div className="flex justify-center py-3">
            <motion.div
              animate={{ rotate: 360 }}
              transition={{ duration: 1, repeat: Infinity, ease: 'linear' }}
              className="w-5 h-5 border-2 border-[#00C300] border-t-transparent rounded-full"
            />
          </div>
        )}

        {loadingChats || loadingGroups ? (
          <LoadingSkeleton count={4} variant="list" />
        ) : filtered.length === 0 ? (
          <EmptyState
            icon={activeTab === 'groups' ? Users : activeTab === 'archived' ? Archive : MessageCircle}
            title={activeTab === 'groups' ? 'No groups yet' : activeTab === 'archived' ? 'No archived chats' : search ? 'No results found' : 'No conversations yet'}
            description={activeTab === 'groups' ? 'Create a group to start chatting' : activeTab === 'archived' ? 'Long press a chat to archive it' : 'Start a conversation with friends'}
            action={
              activeTab === 'groups' ? (
                <button type="button" onClick={() => navigate('/create-group')}
                  className="bg-[#00C300] text-white text-sm font-medium px-4 py-2 rounded-full active:bg-[#00A300] transition-colors"
                >
                  Create Group
                </button>
              ) : activeTab === 'archived' ? null : (
                <button type="button" onClick={() => navigate('/contacts')}
                  className="bg-[#00C300] text-white text-sm font-medium px-4 py-2 rounded-full active:bg-[#00A300] transition-colors"
                >
                  Start Chatting
                </button>
              )
            }
          />
        ) : (
          filtered.map((chat, i) => {
            const isGroup = chat.type === 'group';
            const otherId = isGroup ? '' : (chat.participants.find(p => p !== user?.id) || '');
            const f = friends.find(fr => fr.id === otherId);
            const isFriend = !!f;
            const name = isGroup ? (chat.name || 'Group') : (f?.name || 'Chat');
            const avatar = isGroup ? (chat.avatar || '') : (f?.avatar || '');
            const lastMsg = typeof chat.lastMessage === 'string' ? chat.lastMessage : 'No messages yet';
            const hasUnread = (chat.unreadCount || 0) > 0;

            const handleAddFriend = async (e: React.MouseEvent) => {
              e.stopPropagation();
              if (!user?.id || !otherId) return;
              try {
                await sendRequest(otherId, user.id);
                toast.success('Friend request sent');
              } catch (err: any) {
                toast.error(err.message || 'Failed to send request');
              }
            };

            return (
              <motion.button
                key={chat.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: Math.min(i * 0.03, 0.3) }}
                onClick={() => navigate(isGroup ? `/group/${chat.id}` : `/chat/${otherId}`)}
                className={`w-full flex items-center p-4 active:bg-gray-50 transition-colors text-left press-scale ${hasUnread ? 'bg-[#00C300]/5' : ''}`}
              >
                <div className={`relative w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 overflow-hidden mr-4 ${
                  isGroup ? 'bg-[#00C300]/10' : 'bg-[#F5F5F5]'
                }`}>
                  {sanitizeMediaUrl(avatar) ? (
                    <img src={sanitizeMediaUrl(avatar)} className="w-full h-full object-cover" alt="User avatar" />
                  ) : isGroup ? (
                    <Users size={24} className="text-[#00C300]" />
                  ) : (
                    <img src={getDefaultAvatar(otherId || name)} className="w-full h-full object-cover" alt="User avatar" />
                  )}
                  {!isGroup && visibleOnline[otherId] && (
                    <div className="absolute bottom-0 right-0 w-3.5 h-3.5 bg-[#00C300] rounded-full border-2 border-white" />
                  )}
                  {!isGroup && hasUnread && !visibleOnline[otherId] && (
                    <div className="absolute bottom-0 right-0 w-3.5 h-3.5 bg-[#FF3B30] rounded-full border-2 border-white" />
                  )}
                </div>
                <div className="flex-1 min-w-0 border-b border-[#EBEBEB] py-1">
                  <div className="flex justify-between items-start mb-0.5">
                    <div className="flex items-center gap-1.5">
                      <h3 className={`text-[16px] truncate ${hasUnread ? 'font-bold text-[#111111]' : 'font-medium text-[#111111]'}`}>{name}</h3>
                      {isGroup && (
                        <span className="text-[10px] bg-[#00C300]/10 text-[#00C300] px-1.5 py-0.5 rounded-full font-medium">
                          Group
                        </span>
                      )}
                      {!isGroup && !isFriend && (
                        <span className="text-[10px] bg-[#FF9800]/10 text-[#FF9800] px-1.5 py-0.5 rounded-full font-medium">
                          Not Friends
                        </span>
                      )}
                    </div>
                    <span className={`text-[12px] shrink-0 ml-2 ${hasUnread ? 'text-[#00C300] font-bold' : 'text-[#8D8D8D]'}`}>{formatTime(chat.updatedAt)}</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <p className={`text-[14px] truncate ${hasUnread ? 'text-[#111111] font-medium' : 'text-[#8D8D8D]'}`}>{lastMsg}</p>
                    <div className="flex items-center gap-2">
                      {!isGroup && !isFriend && (
                        <button type="button" onClick={handleAddFriend}
                          className="px-2.5 py-1 bg-[#00C300] text-white text-[10px] rounded-full font-medium active:bg-[#00A300] transition-colors"
                        >
                          Add Friend
                        </button>
                      )}
                      {hasUnread && (
                        <span className="bg-[#FF3B30] text-white text-[11px] font-bold rounded-full min-w-[20px] h-5 flex items-center justify-center px-1.5 shrink-0">
                          {chat.unreadCount}
                        </span>
                      )}
                      {chat.archived && (
                        <button type="button" onClick={(e) => {
                            e.stopPropagation();
                            unarchiveChat(chat.id);
                            toast.success('Chat unarchived');
                          }}
                          className="p-1.5 hover:bg-[#F5F5F5] rounded-full text-[#8D8D8D] transition-colors"
                          title="Unarchive"
                        >
                          <Archive size={14} />
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              </motion.button>
            );
          })
        )}
      </div>

      {/* Floating New Chat Button */}
      <button type="button" onClick={() => navigate('/contacts')}
        className="absolute bottom-20 right-4 w-14 h-14 bg-[#00C300] text-white rounded-full shadow-lg flex items-center justify-center hover:bg-[#00A300] active:scale-95 transition-all z-30"
        title="New Chat"
      >
        <MessageCircle size={24} />
      </button>

      <BottomNav />
    </div>
  );
}

import { useState, useRef, useCallback, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  ArrowLeft, Upload, Video, X, Send, Music, Hash, Image as ImageIcon,
  Loader, Play, Pause, Trash2, CheckCircle, AlertCircle, Sparkles
} from 'lucide-react';
import { useAuthStore } from '@/store/useAuthStore';
import { useReelStore } from '@/store/useReelStore';
import { uploadMediaBlob } from '@/lib/storage';
import { toast } from 'sonner';

export default function CreateReelsPage() {
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const { createReel } = useReelStore();

  const [videoFile, setVideoFile] = useState<File | null>(null);
  const [videoPreviewUrl, setVideoPreviewUrl] = useState<string>('');
  const [thumbnailUrl, setThumbnailUrl] = useState<string>('');
  const [caption, setCaption] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [tagInput, setTagInput] = useState('');
  const [musicTitle, setMusicTitle] = useState('');
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [duration, setDuration] = useState(0);
  const [error, setError] = useState('');

  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const thumbnailInputRef = useRef<HTMLInputElement>(null);

  // Cleanup blob URLs on unmount to prevent memory leaks
  useEffect(() => {
    return () => {
      if (videoPreviewUrl) URL.revokeObjectURL(videoPreviewUrl);
      if (thumbnailUrl) URL.revokeObjectURL(thumbnailUrl);
    };
  }, [videoPreviewUrl, thumbnailUrl]);

  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate file type
    if (!file.type.startsWith('video/')) {
      setError('Please select a video file');
      return;
    }

    // Validate file size (100MB max)
    if (file.size > 100 * 1024 * 1024) {
      setError('Video must be less than 100MB');
      return;
    }

    setError('');
    setVideoFile(file);
    const url = URL.createObjectURL(file);
    setVideoPreviewUrl(url);

    // Get video duration
    const video = document.createElement('video');
    video.preload = 'metadata';
    video.onloadedmetadata = () => {
      setDuration(video.duration);
      URL.revokeObjectURL(video.src);
    };
    video.src = url;
  }, []);

  const handleThumbnailSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) {
      toast.error('Please select an image file');
      return;
    }
    const url = URL.createObjectURL(file);
    setThumbnailUrl(url);
  }, []);

  const generateThumbnail = useCallback(() => {
    if (!videoRef.current || !videoPreviewUrl) return;
    const video = videoRef.current;
    const canvas = document.createElement('canvas');
    canvas.width = video.videoWidth || 640;
    canvas.height = video.videoHeight || 360;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    canvas.toBlob((blob) => {
      if (blob) {
        const url = URL.createObjectURL(blob);
        setThumbnailUrl(url);
      }
    }, 'image/jpeg', 0.8);
  }, [videoPreviewUrl]);

  const handleAddTag = () => {
    const tag = tagInput.trim().replace(/^#/, '');
    if (!tag) return;
    if (tags.includes(tag)) {
      setTagInput('');
      return;
    }
    if (tags.length >= 10) {
      toast.error('Max 10 tags allowed');
      return;
    }
    setTags([...tags, tag]);
    setTagInput('');
  };

  const handleRemoveTag = (tag: string) => {
    setTags(tags.filter(t => t !== tag));
  };

  const handlePost = async () => {
    if (!user?.id) {
      toast.error('Please log in to post reels');
      navigate('/auth');
      return;
    }
    if (!videoFile) {
      setError('Please select a video');
      return;
    }
    if (!caption.trim()) {
      setError('Please add a caption');
      return;
    }

    setUploading(true);
    setUploadProgress(10);

    try {
      // Upload video
      setUploadProgress(30);
      const videoUrl = await uploadMediaBlob({
        kind: 'reels',
        file: videoFile,
        mimeType: videoFile.type,
      });

      setUploadProgress(60);

      // Upload thumbnail if custom one selected
      let finalThumbnail = thumbnailUrl;
      if (thumbnailUrl && thumbnailUrl.startsWith('blob:')) {
        // Need to fetch the blob and re-upload
        const response = await fetch(thumbnailUrl);
        const blob = await response.blob();
        const thumbFile = new File([blob], 'thumbnail.jpg', { type: 'image/jpeg' });
        finalThumbnail = await uploadMediaBlob({
          kind: 'reels',
          file: thumbFile,
          mimeType: 'image/jpeg',
        });
      }

      setUploadProgress(80);

      // Create reel
      await createReel(user.id, {
        videoUrl,
        thumbnailUrl: finalThumbnail || undefined,
        caption: caption.trim(),
        musicTitle: musicTitle.trim() || undefined,
        duration: Math.round(duration),
        tags: tags.length > 0 ? tags : undefined,
      });

      setUploadProgress(100);
      toast.success('Reel posted successfully!');
      navigate('/timeline');
    } catch (err) {
      console.error('Post reel error:', err);
      toast.error('Failed to post reel. Please try again.');
      setUploading(false);
    }
  };

  const handleClear = () => {
    if (videoPreviewUrl) URL.revokeObjectURL(videoPreviewUrl);
    if (thumbnailUrl && thumbnailUrl.startsWith('blob:')) URL.revokeObjectURL(thumbnailUrl);
    setVideoFile(null);
    setVideoPreviewUrl('');
    setThumbnailUrl('');
    setCaption('');
    setTags([]);
    setTagInput('');
    setMusicTitle('');
    setDuration(0);
    setError('');
    if (fileInputRef.current) fileInputRef.current.value = '';
    if (thumbnailInputRef.current) thumbnailInputRef.current.value = '';
  };

  return (
    <div className="min-h-[100dvh] bg-[#0d0d0d] text-white">
      {/* Header */}
      <div className="sticky top-0 z-20 bg-[#0d0d0d]/90 backdrop-blur-sm border-b border-[#1a1a1a] px-4 py-3">
        <div className="flex items-center justify-between">
          <button
            type="button"
            onClick={() => navigate(-1)}
            className="p-2 rounded-xl hover:bg-[#1a1a1a] transition-colors"
          >
            <ArrowLeft size={22} />
          </button>
          <h1 className="text-base font-bold">Create Reel</h1>
          <button
            type="button"
            onClick={handlePost}
            disabled={uploading || !videoFile || !caption.trim()}
            className="px-5 py-2 bg-[#00C300] text-black rounded-full text-sm font-bold disabled:opacity-50 disabled:cursor-not-allowed hover:bg-[#00A300] transition-colors"
          >
            {uploading ? <Loader size={16} className="animate-spin" /> : 'Post'}
          </button>
        </div>
      </div>

      <div className="max-w-lg mx-auto px-4 py-6 space-y-6">
        {/* Error */}
        <AnimatePresence>
          {error && (
            <motion.div
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="flex items-center gap-2 bg-red-500/10 border border-red-500/20 text-red-400 px-4 py-3 rounded-xl text-sm"
            >
              <AlertCircle size={16} />
              {error}
            </motion.div>
          )}
        </AnimatePresence>

        {/* Video Upload Area */}
        {!videoPreviewUrl ? (
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            className="w-full aspect-[9/16] max-h-[60vh] bg-[#1a1a1a] border-2 border-dashed border-[#2a2a2a] rounded-2xl flex flex-col items-center justify-center gap-4 hover:border-[#00C300]/50 hover:bg-[#1a1a1a]/80 transition-all group"
          >
            <div className="w-16 h-16 rounded-full bg-[#2a2a2a] group-hover:bg-[#00C300]/20 flex items-center justify-center transition-colors">
              <Video size={28} className="text-[#8D8D8D] group-hover:text-[#00C300]" />
            </div>
            <div className="text-center">
              <p className="text-white font-medium text-sm">Upload a video</p>
              <p className="text-[#8D8D8D] text-xs mt-1">MP4, MOV up to 100MB</p>
              <p className="text-[#8D8D8D] text-xs">15 seconds to 3 minutes</p>
            </div>
            <div className="flex items-center gap-2 text-[#00C300] text-xs font-medium">
              <Upload size={14} /> Select from device
            </div>
          </button>
        ) : (
          <div className="relative bg-[#1a1a1a] rounded-2xl overflow-hidden">
            {/* Video Preview */}
            <video
              ref={videoRef}
              src={videoPreviewUrl}
              className="w-full aspect-[9/16] max-h-[60vh] object-cover"
              playsInline
              onClick={() => {
                if (videoRef.current) {
                  if (videoRef.current.paused) {
                    videoRef.current.play();
                    setIsPlaying(true);
                  } else {
                    videoRef.current.pause();
                    setIsPlaying(false);
                  }
                }
              }}
            />
            {/* Play/Pause Overlay */}
            <button
              type="button"
              onClick={() => {
                if (videoRef.current) {
                  if (videoRef.current.paused) {
                    videoRef.current.play();
                    setIsPlaying(true);
                  } else {
                    videoRef.current.pause();
                    setIsPlaying(false);
                  }
                }
              }}
              className="absolute inset-0 flex items-center justify-center bg-black/20"
            >
              {!isPlaying && (
                <div className="w-14 h-14 rounded-full bg-white/20 backdrop-blur-sm flex items-center justify-center">
                  <Play size={28} className="text-white ml-1" />
                </div>
              )}
            </button>
            {/* Duration badge */}
            {duration > 0 && (
              <div className="absolute bottom-3 right-3 bg-black/60 px-2 py-1 rounded-full text-xs">
                {Math.floor(duration / 60)}:{String(Math.floor(duration % 60)).padStart(2, '0')}
              </div>
            )}
            {/* Clear button */}
            <button
              type="button"
              onClick={handleClear}
              className="absolute top-3 right-3 w-8 h-8 rounded-full bg-black/60 flex items-center justify-center hover:bg-black/80 transition-colors"
            >
              <X size={16} />
            </button>
          </div>
        )}
        <input
          type="file"
          ref={fileInputRef}
          accept="video/*"
          className="hidden"
          onChange={handleFileSelect}
        />

        {/* Thumbnail */}
        {videoPreviewUrl && (
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <label className="text-sm font-medium text-[#8D8D8D]">Cover Image</label>
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={generateThumbnail}
                  className="text-xs text-[#00C300] hover:underline"
                >
                  Auto-generate
                </button>
                <button
                  type="button"
                  onClick={() => thumbnailInputRef.current?.click()}
                  className="text-xs text-[#00C300] hover:underline"
                >
                  Upload custom
                </button>
              </div>
            </div>
            {thumbnailUrl ? (
              <div className="relative w-24 h-36 rounded-xl overflow-hidden">
                <img src={thumbnailUrl} alt="Thumbnail" className="w-full h-full object-cover" />
                <button
                  type="button"
                  onClick={() => setThumbnailUrl('')}
                  className="absolute top-1 right-1 w-6 h-6 rounded-full bg-black/60 flex items-center justify-center"
                >
                  <X size={12} />
                </button>
              </div>
            ) : (
              <button
                type="button"
                onClick={() => thumbnailInputRef.current?.click()}
                className="w-24 h-36 rounded-xl border-2 border-dashed border-[#2a2a2a] flex items-center justify-center hover:border-[#00C300]/50 transition-colors"
              >
                <ImageIcon size={20} className="text-[#8D8D8D]" />
              </button>
            )}
            <input
              type="file"
              ref={thumbnailInputRef}
              accept="image/*"
              className="hidden"
              onChange={handleThumbnailSelect}
            />
          </div>
        )}

        {/* Caption */}
        <div className="space-y-2">
          <label className="text-sm font-medium text-[#8D8D8D]">Caption</label>
          <textarea
            value={caption}
            onChange={(e) => setCaption(e.target.value)}
            placeholder="Describe your reel..."
            rows={3}
            className="w-full bg-[#1a1a1a] rounded-xl px-4 py-3 text-sm text-white placeholder:text-[#8D8D8D] outline-none focus:ring-2 focus:ring-[#00C300]/30 resize-none transition-all"
            maxLength={500}
          />
          <p className="text-[#8D8D8D] text-xs text-right">{caption.length}/500</p>
        </div>

        {/* Tags */}
        <div className="space-y-2">
          <label className="text-sm font-medium text-[#8D8D8D]">Tags</label>
          <div className="flex gap-2">
            <div className="relative flex-1">
              <Hash size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8D8D8D]" />
              <input
                type="text"
                value={tagInput}
                onChange={(e) => setTagInput(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); handleAddTag(); } }}
                placeholder="Add tags (press Enter)"
                className="w-full bg-[#1a1a1a] rounded-xl pl-10 pr-4 py-3 text-sm text-white placeholder:text-[#8D8D8D] outline-none focus:ring-2 focus:ring-[#00C300]/30 transition-all"
              />
            </div>
            <button
              type="button"
              onClick={handleAddTag}
              className="px-4 py-3 bg-[#2a2a2a] rounded-xl text-[#00C300] text-sm font-medium hover:bg-[#333] transition-colors"
            >
              Add
            </button>
          </div>
          {tags.length > 0 && (
            <div className="flex flex-wrap gap-2">
              {tags.map((tag) => (
                <span
                  key={tag}
                  className="inline-flex items-center gap-1 px-3 py-1.5 bg-[#00C300]/10 text-[#00C300] rounded-full text-xs font-medium"
                >
                  #{tag}
                  <button type="button" onClick={() => handleRemoveTag(tag)} className="hover:text-white">
                    <X size={12} />
                  </button>
                </span>
              ))}
            </div>
          )}
        </div>

        {/* Music */}
        <div className="space-y-2">
          <label className="text-sm font-medium text-[#8D8D8D]">Music / Sound</label>
          <div className="relative">
            <Music size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8D8D8D]" />
            <input
              type="text"
              value={musicTitle}
              onChange={(e) => setMusicTitle(e.target.value)}
              placeholder="Add a music title or sound name..."
              className="w-full bg-[#1a1a1a] rounded-xl pl-10 pr-4 py-3 text-sm text-white placeholder:text-[#8D8D8D] outline-none focus:ring-2 focus:ring-[#00C300]/30 transition-all"
            />
          </div>
        </div>

        {/* Upload Progress */}
        <AnimatePresence>
          {uploading && (
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: 10 }}
              className="bg-[#1a1a1a] rounded-xl p-4 space-y-3"
            >
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Sparkles size={16} className="text-[#00C300]" />
                  <span className="text-sm font-medium">Posting your reel...</span>
                </div>
                <span className="text-xs text-[#8D8D8D]">{uploadProgress}%</span>
              </div>
              <div className="h-2 bg-[#2a2a2a] rounded-full overflow-hidden">
                <motion.div
                  className="h-full bg-[#00C300] rounded-full"
                  initial={{ width: 0 }}
                  animate={{ width: `${uploadProgress}%` }}
                  transition={{ duration: 0.3 }}
                />
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Tips */}
        <div className="bg-[#1a1a1a] rounded-xl p-4 space-y-2">
          <p className="text-xs font-medium text-[#8D8D8D]">Tips for great reels:</p>
          <ul className="text-xs text-[#8D8D8D] space-y-1 list-disc list-inside">
            <li>Keep it engaging in the first 3 seconds</li>
            <li>Use trending sounds to boost discoverability</li>
            <li>Add captions for accessibility</li>
            <li>Use relevant tags to reach more people</li>
          </ul>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useMemo, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import {
  ArrowLeft, Coins, Gift, Flame, Target, Users, Clock, Check,
  ChevronRight, Sparkles, Zap, Star, Trophy, TrendingUp
} from 'lucide-react';
import { useAuthStore } from '@/store/useAuthStore';
import { useWalletStore, STAKING_TIERS } from '@/store/useWalletStore';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';

interface Mission {
  id: string;
  title: string;
  description: string;
  reward: number;
  icon: typeof Coins;
  color: string;
  completed: boolean;
  progress: number;
  maxProgress: number;
}

const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

export default function GagaRewardsPage() {
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const { wallet, earnCoins, claimDailyInterest, getDailyInterestAmount, subscribeWallet } = useWalletStore();
  const [activeTab, setActiveTab] = useState<'checkin' | 'missions' | 'refer'>('checkin');

  useEffect(() => {
    if (!user?.id) return;
    return subscribeWallet(user.id);
  }, [user?.id, subscribeWallet]);
  const [showClaimed, setShowClaimed] = useState(false);
  const [claimedAmount, setClaimedAmount] = useState(0);
  const [interestLoading, setInterestLoading] = useState(false);
  const [referralCode] = useState(() => {
    return user ? `GAGA-${user.id.slice(0, 6).toUpperCase()}` : '';
  });
  const [copiedRef, setCopiedRef] = useState(false);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  const coins = wallet?.coins || 0;
  const dailyInterest = getDailyInterestAmount(user?.id || '');

  // Check-in streak data (simulated - would come from backend)
  const today = new Date().getDay(); // 0 = Sunday
  const adjustedToday = today === 0 ? 6 : today - 1; // Convert to 0=Monday
  const [checkInDays, setCheckInDays] = useState<boolean[]>(() => {
    const days = Array(7).fill(false);
    // Mark previous days as checked in for demo
    for (let i = 0; i < adjustedToday; i++) days[i] = true;
    return days;
  });

  const checkInRewards = [5, 5, 10, 5, 5, 15, 25];

  const handleCheckIn = async (dayIndex: number) => {
    if (!user || checkInDays[dayIndex]) return;
    const reward = checkInRewards[dayIndex];
    await earnCoins(user.id, reward, `Day ${dayIndex + 1} check-in reward`);
    setCheckInDays(prev => {
      const next = [...prev];
      next[dayIndex] = true;
      return next;
    });
    setClaimedAmount(reward);
    setShowClaimed(true);
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => setShowClaimed(false), 2000);
  };

  const handleClaimStaking = async () => {
    if (!user) return;
    setInterestLoading(true);
    const earned = await claimDailyInterest(user.id);
    setInterestLoading(false);
    if (earned > 0) {
      setClaimedAmount(earned);
      setShowClaimed(true);
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      timeoutRef.current = setTimeout(() => setShowClaimed(false), 3000);
    }
  };

  const [missions, setMissions] = useState<Mission[]>([
    { id: '1', title: 'Send a Message', description: 'Send 5 messages to friends', reward: 5, icon: Zap, color: 'text-[#00C300]', completed: false, progress: 3, maxProgress: 5 },
    { id: '2', title: 'Make a Voice Call', description: 'Complete 1 voice call', reward: 10, icon: Users, color: 'text-[#2196F3]', completed: false, progress: 0, maxProgress: 1 },
    { id: '3', title: 'Post on Timeline', description: 'Create 1 timeline post', reward: 15, icon: Star, color: 'text-[#FF9800]', completed: false, progress: 0, maxProgress: 1 },
    { id: '4', title: 'Refer a Friend', description: 'Invite 1 friend to GaGa Chat', reward: 50, icon: Users, color: 'text-[#8B5CF6]', completed: false, progress: 0, maxProgress: 1 },
    { id: '5', title: 'Daily Login Streak', description: 'Login for 3 days in a row', reward: 20, icon: Flame, color: 'text-[#FF3B30]', completed: false, progress: 2, maxProgress: 3 },
    { id: '6', title: 'Save 100 Gaga Coins', description: 'Keep a balance of 100+ GAGA', reward: 25, icon: TrendingUp, color: 'text-[#00C300]', completed: coins >= 100, progress: Math.min(coins, 100), maxProgress: 100 },
  ]);

  const handleClaimMission = async (mission: Mission) => {
    if (!user || mission.completed) return;
    await earnCoins(user.id, mission.reward, `Mission reward: ${mission.title}`);
    setMissions(prev => prev.map(m => m.id === mission.id ? { ...m, completed: true } : m));
    setClaimedAmount(mission.reward);
    setShowClaimed(true);
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => setShowClaimed(false), 2000);
  };

  const completedCount = missions.filter(m => m.completed).length;

  const stakingAPY = useMemo(() => useWalletStore.getState().getStakingAPY(), []);

  return (
    <div className="min-h-[100dvh] bg-[#F5F5F5]">
      {/* Header */}
      <div className="bg-gradient-to-br from-[#00C300] to-[#00A300] text-white">
        <div className="flex items-center gap-3 p-4">
          <button type="button" onClick={() => navigate(-1)} className="p-2 -ml-2 active:bg-white/20 rounded-full text-white transition-colors">
            <ArrowLeft size={22} />
          </button>
          <h1 className="text-lg font-bold">Gaga Rewards</h1>
          <div className="ml-auto flex items-center gap-1 bg-white/20 rounded-full px-3 py-1">
            <Coins size={14} />
            <span className="text-sm font-bold">{coins.toLocaleString()}</span>
          </div>
        </div>

        <div className="px-4 pb-6">
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-white/10 backdrop-blur-sm rounded-3xl p-5 border border-white/20"
          >
            <div className="flex items-center justify-between mb-4">
              <div>
                <p className="text-white/70 text-xs">Total Earnings</p>
                <p className="text-2xl font-bold">{coins.toLocaleString()} <span className="text-sm font-normal text-white/70">GAGA</span></p>
              </div>
              <div className="w-14 h-14 rounded-full bg-gradient-to-br from-[#FFD700] to-[#FFA500] flex items-center justify-center">
                <Trophy size={28} className="text-white" />
              </div>
            </div>
            <div className="flex items-center gap-4 text-xs text-white/70">
              <span className="flex items-center gap-1"><Target size={12} /> {completedCount}/{missions.length} missions</span>
              <span className="flex items-center gap-1"><Flame size={12} /> {checkInDays.filter(Boolean).length} day streak</span>
              <span className="flex items-center gap-1"><TrendingUp size={12} /> {stakingAPY}% APY</span>
            </div>
          </motion.div>
        </div>
      </div>

      {/* Staking Banner */}
      {dailyInterest > 0 && (
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="mx-4 -mt-3 bg-white rounded-2xl p-4 shadow-sm border border-[#EBEBEB] relative z-10"
        >
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-gradient-to-br from-[#FFD700] to-[#FFA500] flex items-center justify-center">
                <Sparkles size={18} className="text-white" />
              </div>
              <div>
                <p className="text-[#111111] text-sm font-medium">Daily Staking Reward</p>
                <p className="text-[#00C300] text-lg font-bold">+{dailyInterest} GAGA</p>
              </div>
            </div>
            <button type="button" onClick={handleClaimStaking}
              disabled={interestLoading}
              className="px-4 py-2 bg-[#00C300] text-white rounded-xl text-sm font-bold active:bg-[#00A300] transition-colors disabled:opacity-50"
            >
              {interestLoading ? '...' : 'Claim'}
            </button>
          </div>
        </motion.div>
      )}

      {/* Tabs */}
      <div className="flex border-b border-[#EBEBEB] px-4 mt-4 bg-white">
        {(['checkin', 'missions', 'refer'] as const).map(tab => (
          <button type="button" key={tab}
            onClick={() => setActiveTab(tab)}
            className={`flex-1 py-3 text-sm font-medium transition-colors capitalize ${
              activeTab === tab ? 'text-[#00C300] border-b-2 border-[#00C300]' : 'text-[#8D8D8D]'
            }`}
          >
            {tab === 'checkin' ? 'Daily Check-in' : tab === 'missions' ? 'Missions' : 'Refer Friends'}
          </button>
        ))}
      </div>

      <div className="p-4 pb-20">
        {/* Daily Check-in */}
        {activeTab === 'checkin' && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
            <div className="bg-white rounded-2xl p-4 border border-[#EBEBEB] mb-4">
              <div className="flex items-center justify-between mb-4">
                <div>
                  <h3 className="text-[#111111] font-bold">7-Day Streak</h3>
                  <p className="text-[#8D8D8D] text-xs">Check in daily for bigger rewards</p>
                </div>
                <div className="flex items-center gap-1 bg-[#FF9800]/10 px-3 py-1 rounded-full">
                  <Flame size={14} className="text-[#FF9800]" />
                  <span className="text-[#FF9800] text-xs font-bold">{checkInDays.filter(Boolean).length}/7</span>
                </div>
              </div>
              <div className="grid grid-cols-7 gap-2">
                {DAYS.map((day, i) => {
                  const isToday = i === adjustedToday;
                  const checked = checkInDays[i];
                  return (
                    <button type="button" key={day}
                      onClick={() => isToday && handleCheckIn(i)}
                      disabled={!isToday || checked}
                      className={`flex flex-col items-center gap-1 py-3 rounded-xl transition-all ${
                        checked
                          ? 'bg-[#00C300]/10 border border-[#00C300]/30'
                          : isToday
                          ? 'bg-[#00C300] text-white active:scale-95'
                          : 'bg-[#F5F5F5] text-[#8D8D8D]'
                      }`}
                    >
                      <span className="text-[10px] font-medium">{day}</span>
                      {checked ? (
                        <Check size={16} className="text-[#00C300]" />
                      ) : (
                        <span className="text-xs font-bold">+{checkInRewards[i]}</span>
                      )}
                    </button>
                  );
                })}
              </div>
              <p className="text-center text-[#8D8D8D] text-xs mt-3">
                {checkInDays[adjustedToday] ? 'Come back tomorrow for +5 GAGA!' : 'Tap today to claim your reward!'}
              </p>
            </div>

            {/* Staking Info */}
            <div className="bg-white rounded-2xl p-4 border border-[#EBEBEB]">
              <h3 className="text-[#111111] font-bold mb-3 flex items-center gap-2">
                <TrendingUp size={16} className="text-[#00C300]" /> Staking Tiers
              </h3>
              <div className="space-y-2">
                {STAKING_TIERS.filter(t => t.minCoins > 0).map(t => (
                  <div
                    key={t.label}
                    className={`flex items-center justify-between p-3 rounded-xl ${
                      coins >= t.minCoins ? 'bg-[#00C300]/5 border border-[#00C300]/20' : 'bg-[#F5F5F5]'
                    }`}
                  >
                    <div className="flex items-center gap-2">
                      <Trophy size={14} className={coins >= t.minCoins ? 'text-[#FFD700]' : 'text-[#C7C7CC]'} />
                      <span className={`text-sm ${coins >= t.minCoins ? 'text-[#00C300] font-medium' : 'text-[#8D8D8D]'}`}>
                        {t.label}
                      </span>
                    </div>
                    <div className="text-right">
                      <span className="text-sm font-bold">{t.apy}% APY</span>
                      <p className="text-[#8D8D8D] text-[10px]">{t.minCoins.toLocaleString()}+ GAGA</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </motion.div>
        )}

        {/* Missions */}
        {activeTab === 'missions' && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-3">
            {missions.map((mission, i) => (
              <motion.div
                key={mission.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.05 }}
                className={`bg-white rounded-2xl p-4 border ${
                  mission.completed ? 'border-[#00C300]/30 opacity-60' : 'border-[#EBEBEB]'
                }`}
              >
                <div className="flex items-start justify-between mb-2">
                  <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-full bg-[#F5F5F5] flex items-center justify-center ${mission.completed ? 'bg-[#00C300]/10' : ''}`}>
                      {mission.completed ? (
                        <Check size={18} className="text-[#00C300]" />
                      ) : (
                        <mission.icon size={18} className={mission.color} />
                      )}
                    </div>
                    <div>
                      <p className={`text-sm font-medium ${mission.completed ? 'text-[#8D8D8D] line-through' : 'text-[#111111]'}`}>
                        {mission.title}
                      </p>
                      <p className="text-[#8D8D8D] text-[11px]">{mission.description}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="text-[#00C300] font-bold text-sm">+{mission.reward}</span>
                    <p className="text-[#8D8D8D] text-[10px]">GAGA</p>
                  </div>
                </div>
                {!mission.completed && (
                  <div className="ml-13 pl-[52px]">
                    <div className="w-full h-1.5 bg-[#F5F5F5] rounded-full overflow-hidden">
                      <div
                        className="h-full bg-[#00C300] rounded-full transition-all"
                        style={{ width: `${(mission.progress / mission.maxProgress) * 100}%` }}
                      />
                    </div>
                    <div className="flex items-center justify-between mt-1.5">
                      <span className="text-[#8D8D8D] text-[10px]">{mission.progress}/{mission.maxProgress}</span>
                      {mission.progress >= mission.maxProgress && (
                        <button type="button" onClick={() => handleClaimMission(mission)}
                          className="px-3 py-1 bg-[#00C300] text-white text-[10px] rounded-full font-medium active:bg-[#00A300]"
                        >
                          Claim
                        </button>
                      )}
                    </div>
                  </div>
                )}
              </motion.div>
            ))}
          </motion.div>
        )}

        {/* Refer Friends */}
        {activeTab === 'refer' && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
            <div className="bg-white rounded-2xl p-6 border border-[#EBEBEB] text-center mb-4">
              <div className="w-16 h-16 rounded-full bg-gradient-to-br from-[#00C300] to-[#00A300] flex items-center justify-center mx-auto mb-3">
                <Gift size={32} className="text-white" />
              </div>
              <h3 className="text-[#111111] font-bold text-lg mb-1">Invite & Earn</h3>
              <p className="text-[#8D8D8D] text-sm mb-4">Share your referral code with friends and earn 50 GAGA for each signup!</p>
              <div className="bg-[#F5F5F5] rounded-xl p-4 flex items-center justify-between mb-4">
                <span className="text-[#111111] font-mono font-bold">{referralCode}</span>
                <button type="button" onClick={() => {
                    navigator.clipboard.writeText(referralCode);
                    setCopiedRef(true);
                    if (timeoutRef.current) clearTimeout(timeoutRef.current);
                    timeoutRef.current = setTimeout(() => setCopiedRef(false), 2000);
                  }}
                  className="text-[#00C300] text-sm font-medium"
                >
                  {copiedRef ? 'Copied!' : 'Copy'}
                </button>
              </div>
              <button type="button" onClick={async () => {
                  try {
                    await navigator.share({
                      title: 'Join me on GaGa Chat!',
                      text: `Use my referral code ${referralCode} and get 50 free Gaga Coins!`,
                      url: window.location.origin,
                    });
                  } catch { /* cancelled */ }
                }}
                className="w-full py-3 bg-[#00C300] text-white rounded-xl text-sm font-bold active:bg-[#00A300] transition-colors"
              >
                Share with Friends
              </button>
            </div>

            {/* How it works */}
            <div className="bg-white rounded-2xl p-4 border border-[#EBEBEB]">
              <h3 className="text-[#111111] font-bold text-sm mb-3">How it works</h3>
              {[
                { step: '1', text: 'Share your unique referral code' },
                { step: '2', text: 'Friend signs up using your code' },
                { step: '3', text: 'Both get 50 GAGA bonus!' },
              ].map(item => (
                <div key={item.step} className="flex items-center gap-3 py-2.5">
                  <div className="w-6 h-6 rounded-full bg-[#00C300] text-white flex items-center justify-center text-xs font-bold shrink-0">
                    {item.step}
                  </div>
                  <p className="text-[#111111] text-sm">{item.text}</p>
                </div>
              ))}
            </div>
          </motion.div>
        )}
      </div>

      {/* Claimed Toast */}
      <Dialog open={showClaimed} onOpenChange={setShowClaimed}>
        <DialogContent className="bg-white border-[#00C300] text-[#111111] sm:max-w-sm text-center p-6">
          <motion.div
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            className="w-16 h-16 rounded-full bg-[#00C300]/10 flex items-center justify-center mx-auto mb-3"
          >
            <Coins size={32} className="text-[#00C300]" />
          </motion.div>
          <p className="text-2xl font-bold text-[#00C300]">+{claimedAmount} GAGA</p>
          <p className="text-[#8D8D8D] text-sm">Claimed successfully!</p>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  ChevronLeft, MoreHorizontal, Mic, Send, Smile, Camera,
  Image as ImageIcon, MapPin, File as FileIcon, User, Plus, Users, Phone, UserPlus, Settings, LogOut,
  Search, X, Copy, Trash2, Reply, Forward, Heart, ThumbsUp, Laugh, Flame, Star,
  Clock, FileText, ArrowRight, Calendar, Check
} from 'lucide-react';
import { useAuthStore } from '@/store/useAuthStore';
import { useGroupStore } from '@/store/useGroupStore';
import { useFriendStore } from '@/store/useFriendStore';
import { useVoiceRecorder } from '@/hooks/useVoiceRecorder';
import { useTyping } from '@/hooks/useTyping';
import { useOfflineQueue, isOnline } from '@/hooks/useOfflineQueue';
import { useScheduledMessages } from '@/hooks/useScheduledMessages';
import { formatTime } from '@/lib/utils';
import type { Message } from '@/types';
import { toast } from 'sonner';

const reactionEmojis = [
  { icon: ThumbsUp, label: 'like', color: 'text-[#2196F3]' },
  { icon: Heart, label: 'love', color: 'text-[#FF3B30]' },
  { icon: Laugh, label: 'laugh', color: 'text-[#FF9800]' },
  { icon: Star, label: 'wow', color: 'text-[#8B5CF6]' },
  { icon: Flame, label: 'fire', color: 'text-[#FF5722]' },
];

const quickEmojis = ['\u{1F44D}', '\u{2764}', '\u{1F602}', '\u{1F62E}', '\u{1F64F}', '\u{1F525}'];

const attachmentOptions = [
  { icon: <ImageIcon size={28} strokeWidth={1.5} />, label: 'Photos', color: 'bg-[#4CAF50]' },
  { icon: <Camera size={28} strokeWidth={1.5} />, label: 'Camera', color: 'bg-[#2196F3]' },
  { icon: <Phone size={28} strokeWidth={1.5} />, label: 'Audio', color: 'bg-[#00C300]' },
  { icon: <User size={28} strokeWidth={1.5} />, label: 'Contact', color: 'bg-[#FF9800]' },
  { icon: <MapPin size={28} strokeWidth={1.5} />, label: 'Location', color: 'bg-[#E91E63]' },
  { icon: <FileIcon size={28} strokeWidth={1.5} />, label: 'File', color: 'bg-[#673AB7]' },
];

export default function GroupChatPage() {
  const navigate = useNavigate();
  const { groupId } = useParams<{ groupId: string }>();
  const { user: currentUser } = useAuthStore();
  const {
    groups, groupMessages, subscribeGroupMessages, sendGroupMessage,
    deleteGroupMessage, addGroupReaction, leaveGroup
  } = useGroupStore();
  const { friends } = useFriendStore();
  const { isRecording, duration, startRecording, stopRecording, cancelRecording } = useVoiceRecorder();

  const [input, setInput] = useState('');
  const [showAttachments, setShowAttachments] = useState(false);
  const [showMenu, setShowMenu] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [showSearch, setShowSearch] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [contextMenu, setContextMenu] = useState<{ msg: Message; x: number; y: number } | null>(null);
  const [selectedReactionMsg, setSelectedReactionMsg] = useState<string | null>(null);
  const [showForwardModal, setShowForwardModal] = useState(false);
  const [forwardMsg, setForwardMsg] = useState<Message | null>(null);
  const [showSchedulePicker, setShowSchedulePicker] = useState(false);
  const [scheduleDate, setScheduleDate] = useState('');
  const [pendingSchedules, setPendingSchedules] = useState<ReturnType<typeof getPending>>([]);
  const { typingUsers, sendTyping, stopTyping } = useTyping(groupId);
  const { queueMessage } = useOfflineQueue();
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const photoInputRef = useRef<HTMLInputElement>(null);
  const videoInputRef = useRef<HTMLInputElement>(null);

  const sendGroupMessageForScheduler = useCallback(
    async (chatId: string, senderId: string, content: string, type?: string, mediaUrl?: string, replyTo?: Message | string) => {
      const replyId = typeof replyTo === 'string' ? replyTo : replyTo?.id;
      await sendGroupMessage(chatId, senderId, content, (type || 'text') as any, mediaUrl, replyId);
    },
    [sendGroupMessage]
  );

  const { schedule, getPending } = useScheduledMessages(groupId || '', sendGroupMessageForScheduler);

  // Refresh pending scheduled messages periodically
  useEffect(() => {
    setPendingSchedules(getPending());
    const interval = setInterval(() => setPendingSchedules(getPending()), 5000);
    return () => clearInterval(interval);
  }, [groupId, getPending]);

  const group = groups.find(g => g.id === groupId);
  const msgs = groupId ? (groupMessages[groupId] || []) : [];
  const participants = group?.participants || [];
  const memberCount = participants.length;

  const filteredMsgs = searchQuery
    ? msgs.filter(m => m.content.toLowerCase().includes(searchQuery.toLowerCase()))
    : msgs;

  useEffect(() => {
    if (!groupId) return;
    const unsub = subscribeGroupMessages(groupId);
    return unsub;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [groupId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [msgs.length]);

  useEffect(() => {
    const handleClick = () => setContextMenu(null);
    window.addEventListener('click', handleClick);
    return () => window.removeEventListener('click', handleClick);
  }, []);

  // Typing indicators: stop when unmounting or clearing input
  useEffect(() => {
    if (!input.trim()) stopTyping();
    return () => { stopTyping(); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [input]);

  const getSenderName = (senderId: string) => {
    if (senderId === 'system') return 'System';
    if (senderId === currentUser?.id) return 'You';
    const f = friends.find(f => f.id === senderId);
    return f?.name || 'Member';
  };

  const getSenderAvatar = (senderId: string) => {
    if (senderId === currentUser?.id) return currentUser?.avatar;
    const f = friends.find(f => f.id === senderId);
    return f?.avatar;
  };

  const handleSend = async () => {
    if (!input.trim() || !currentUser || !groupId) return;
    stopTyping();
    if (!isOnline()) {
      queueMessage({ type: 'group', chatId: groupId, senderId: currentUser.id, content: input.trim(), replyTo: replyingTo?.id });
      setInput('');
      setShowAttachments(false);
      setReplyingTo(null);
      return;
    }
    try {
      await sendGroupMessage(groupId, currentUser.id, input.trim(), 'text', undefined, replyingTo?.id);
      setInput('');
      setShowAttachments(false);
      setReplyingTo(null);
    } catch {
      toast.error('Failed to send message');
    }
  };

  const handleMediaUpload = async (e: React.ChangeEvent<HTMLInputElement>, mediaType: string) => {
    const file = e.target.files?.[0];
    if (!file || !currentUser || !groupId) return;
    setIsUploading(true);
    try {
      const { uploadMediaBlob } = await import('@/lib/storage');
      const url = await uploadMediaBlob({ kind: 'chats', chatId: groupId, file, mimeType: file.type });
      await sendGroupMessage(groupId, currentUser.id, mediaType === 'image' ? '\u{1F4F7} Photo' : '\u{1F4F9} Video', mediaType, url);
    } catch (err) {
      console.error('Upload error:', err);
    }
    setIsUploading(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !currentUser || !groupId) return;
    setIsUploading(true);
    try {
      const { uploadMediaBlob } = await import('@/lib/storage');
      const url = await uploadMediaBlob({ kind: 'chats', chatId: groupId, file, mimeType: file.type });
      await sendGroupMessage(groupId, currentUser.id, `\u{1F4C1} ${file.name}`, 'file', url);
    } catch (err) {
      console.error('File upload error:', err);
    }
    setIsUploading(false);
  };

  const handleVoiceSend = async () => {
    if (!currentUser || !groupId) return;
    const blob = await stopRecording();
    if (!blob) return;
    try {
      const { uploadMediaBlob } = await import('@/lib/storage');
      const file = new File([blob], 'voice-message.webm', { type: 'audio/webm' });
      const url = await uploadMediaBlob({ kind: 'voice', chatId: groupId, file, mimeType: 'audio/webm' });
      await sendGroupMessage(groupId, currentUser.id, '\u{1F3A4} Voice message', 'voice', url);
    } catch (err) {
      console.error('Voice upload error:', err);
      toast.error('Failed to send voice message');
    }
  };

  const handleLocationShare = () => {
    if (!navigator.geolocation) {
      toast.error('Geolocation not supported');
      return;
    }
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        if (!currentUser || !groupId) return;
        const lat = pos.coords.latitude;
        const lng = pos.coords.longitude;
        const url = `https://www.google.com/maps?q=${lat},${lng}`;
        await sendGroupMessage(groupId, currentUser.id, `\u{1F4CD} Location: ${lat.toFixed(4)}, ${lng.toFixed(4)}`, 'location', url);
        toast.success('Location shared');
      },
      (err) => { toast.error('Location access denied'); }
    );
  };

  const handleContactShare = async () => {
    if (!currentUser || !groupId) return;
    try {
      await sendGroupMessage(groupId, currentUser.id, `\u{1F464} Contact: ${currentUser.name}`, 'contact');
      toast.success('Contact shared');
    } catch {
      toast.error('Failed to share contact');
    }
  };

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    toast.success('Message copied');
    setContextMenu(null);
  };

  const handleDelete = (msgId: string) => {
    deleteGroupMessage(groupId || '', msgId);
    toast.success('Message deleted');
    setContextMenu(null);
  };

  const handleReact = (msgId: string, reaction: string) => {
    if (currentUser && groupId) {
      addGroupReaction(groupId, msgId, reaction, currentUser.id);
    }
    setSelectedReactionMsg(null);
    setContextMenu(null);
  };

  const handleContextMenu = (e: React.MouseEvent, msg: Message) => {
    e.preventDefault();
    setContextMenu({ msg, x: e.clientX, y: e.clientY });
  };

  const handleForward = async (targetChatId: string) => {
    if (!forwardMsg || !currentUser || !groupId) return;
    try {
      await sendGroupMessage(targetChatId, currentUser.id, forwardMsg.content, forwardMsg.type, forwardMsg.mediaUrl);
      toast.success('Message forwarded');
      setShowForwardModal(false);
      setForwardMsg(null);
    } catch (err) {
      toast.error('Failed to forward message');
    }
  };

  const handleScheduleSend = async () => {
    if (!input.trim() || !currentUser || !groupId || !scheduleDate) return;
    const scheduledTime = new Date(scheduleDate).getTime();
    if (scheduledTime <= Date.now()) {
      toast.error('Please select a future time');
      return;
    }
    try {
      schedule({
        senderId: currentUser.id,
        content: input.trim(),
        type: 'text',
        mediaUrl: undefined,
        replyTo: replyingTo?.id,
        scheduledAt: scheduledTime,
      });
      toast.success(`Message scheduled for ${new Date(scheduleDate).toLocaleString()}`);
    } catch {
      toast.error('Failed to schedule message');
    }
    setShowSchedulePicker(false);
    setScheduleDate('');
    setPendingSchedules(getPending());
  };

  const formatDateSeparator = (date: Date) => {
    const now = new Date();
    const d = new Date(date);
    if (d.toDateString() === now.toDateString()) return 'Today';
    const yesterday = new Date(now); yesterday.setDate(yesterday.getDate() - 1);
    if (d.toDateString() === yesterday.toDateString()) return 'Yesterday';
    return d.toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' });
  };

  const menuItems = [
    { icon: UserPlus, label: 'Add Member', action: () => { navigate(`/add-friends`); setShowMenu(false); } },
    { icon: Users, label: 'View Members', action: () => { toast.info(`${memberCount} members in this group`); setShowMenu(false); } },
    { icon: Settings, label: 'Group Settings', action: () => { setShowMenu(false); } },
    { icon: LogOut, label: 'Leave Group', action: () => { if (groupId && currentUser) { leaveGroup(groupId, currentUser.id); navigate('/chats'); } } },
  ];

  const dateSeparatorMap = useMemo(() => {
    const map = new Map<string, boolean>();
    let last: string | null = null;
    filteredMsgs.forEach((msg) => {
      const msgDate = formatDateSeparator(msg.timestamp);
      map.set(msg.id, msgDate !== last);
      last = msgDate;
    });
    return map;
  }, [filteredMsgs]);

  if (!group) {
    return (
      <div className="h-[100dvh] bg-[#8BA3C7] flex items-center justify-center">
        <div className="text-center text-white">
          <Users size={48} className="mx-auto mb-4 opacity-50" />
          <p className="text-lg font-medium">Group not found</p>
          <button type="button" onClick={() => navigate('/chats')} className="mt-4 text-sm underline">Go back</button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-[#8BA3C7]">
      {/* Header */}
      <div className="shrink-0 flex justify-between items-center px-2 py-3 bg-white border-b border-[#EBEBEB] z-10">
        <div className="flex items-center gap-2">
          <button type="button" onClick={() => navigate(-1)} className="p-2 -ml-2 active:bg-gray-100 rounded-full text-[#111111]">
            <ChevronLeft size={28} strokeWidth={1.5} />
          </button>
          <div className="w-9 h-9 rounded-full bg-[#00C300]/10 flex items-center justify-center shrink-0">
            {group.avatar ? (
              <img src={group.avatar} className="w-full h-full object-cover rounded-full" alt="User avatar" />
            ) : (
              <Users size={18} className="text-[#00C300]" />
            )}
          </div>
          <div>
            <h3 className="text-base font-bold text-[#111111] leading-tight">{group.name || 'Group'}</h3>
            <p className="text-[11px] text-[#8D8D8D]">{memberCount} members</p>
          </div>
        </div>
        <div className="flex items-center gap-4 pr-3 text-[#111111]">
          <button type="button" onClick={() => setShowSearch(!showSearch)} className="active:opacity-60" title="Search messages">
            <Search size={22} strokeWidth={1.5} className={showSearch ? 'text-[#00C300]' : ''} />
          </button>
          <button type="button" className="active:opacity-60" onClick={() => navigate('/call', { state: { userId: participants.find(p => p !== currentUser?.id), mode: 'voice' } })}><Phone size={22} strokeWidth={1.5} /></button>
          <button type="button" onClick={() => setShowMenu(!showMenu)} className="active:opacity-60 relative">
            <MoreHorizontal size={22} strokeWidth={1.5} />
          </button>
        </div>
      </div>

      {/* Dropdown Menu */}
      <AnimatePresence>
        {showMenu && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="absolute top-16 right-4 bg-white rounded-xl shadow-lg border border-[#EBEBEB] z-30 overflow-hidden w-48"
          >
            {menuItems.map((item, i) => (
              <button type="button" key={i}
                onClick={() => { item.action(); setShowMenu(false); }}
                className="w-full flex items-center gap-3 px-4 py-3 text-left hover:bg-[#F5F5F5] active:bg-gray-100 transition-colors"
              >
                <item.icon size={18} className={item.label === 'Leave Group' ? 'text-[#FF3B30]' : 'text-[#8D8D8D]'} />
                <span className={`text-sm ${item.label === 'Leave Group' ? 'text-[#FF3B30]' : 'text-[#111111]'}`}>{item.label}</span>
              </button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Search Bar */}
      <AnimatePresence>
        {showSearch && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            className="shrink-0 bg-white border-b border-[#EBEBEB] overflow-hidden"
          >
            <div className="flex items-center gap-2 px-4 py-2">
              <Search size={16} className="text-[#8D8D8D]" />
              <input
                autoFocus
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
                placeholder="Search messages..."
                className="flex-1 bg-[#F5F5F5] rounded-xl px-3 py-2 text-sm text-[#111111] focus:outline-none focus:ring-2 focus:ring-[#00C300] placeholder:text-[#8D8D8D]"
              />
              <button type="button" onClick={() => { setShowSearch(false); setSearchQuery(''); }} className="text-[#8D8D8D]">
                <X size={18} />
              </button>
            </div>
            {searchQuery && (
              <p className="px-4 pb-2 text-[#8D8D8D] text-xs">
                {filteredMsgs.length} result{filteredMsgs.length !== 1 ? 's' : ''}
              </p>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 scrollbar-hide">
        <div className="space-y-4">
          {/* Group info banner */}
          <div className="flex justify-center my-4">
            <div className="bg-black/20 text-white text-center text-[11px] px-4 py-2 rounded-2xl backdrop-blur-sm max-w-[80%]">
              <p className="font-medium text-xs mb-0.5">{group.name}</p>
              <p className="opacity-80">{group.description || `${memberCount} members`}</p>
            </div>
          </div>

          {filteredMsgs.map((msg) => {
            const isMe = msg.senderId === currentUser?.id;
            const isSystem = msg.senderId === 'system';
            const msgDate = formatDateSeparator(msg.timestamp);
            const showDate = dateSeparatorMap.get(msg.id) || false;
            const isSearchMatch = searchQuery && msg.content.toLowerCase().includes(searchQuery.toLowerCase());
            const reactions = msg.reactions || {};
            const hasReactions = Object.values(reactions).some((users: string[]) => users.length > 0);

            if (isSystem) {
              return (
                <div key={msg.id} className="flex justify-center my-2">
                  <span className="bg-black/15 text-white text-[10px] px-3 py-1 rounded-full">{msg.content}</span>
                </div>
              );
            }

            return (
              <div key={msg.id}>
                {showDate && (
                  <div className="flex justify-center my-4">
                    <span className="bg-black/20 text-white text-[11px] px-3 py-1 rounded-full backdrop-blur-sm">{msgDate}</span>
                  </div>
                )}
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}
                  onContextMenu={(e) => handleContextMenu(e, msg)}
                >
                  {!isMe && (
                    <div className="w-8 h-8 rounded-full bg-[#F5F5F5] flex items-center justify-center mr-2 self-end shrink-0 overflow-hidden">
                      {getSenderAvatar(msg.senderId) ? (
                        <img src={getSenderAvatar(msg.senderId)} className="w-full h-full object-cover" alt="User avatar" />
                      ) : (
                        <span className="text-[#8D8D8D] text-xs font-bold">{getSenderName(msg.senderId)[0]}</span>
                      )}
                    </div>
                  )}
                  <div className="max-w-[70%]">
                    {!isMe && <p className="text-[10px] text-gray-200 ml-1 mb-0.5">{getSenderName(msg.senderId)}</p>}
                    {msg.replyTo && (
                      <div className="bg-black/10 rounded-t-2xl px-3 py-1.5 mb-0.5">
                        <p className="text-white/70 text-[10px] truncate">Replying to message</p>
                      </div>
                    )}
                    {msg.type === 'image' && msg.mediaUrl && (
                      <img src={msg.mediaUrl} className="rounded-2xl mb-1 max-w-full cursor-pointer hover:opacity-95 transition-opacity" alt="Shared image" />
                    )}
                    {msg.type === 'video' && msg.mediaUrl && (
                      <video src={msg.mediaUrl} className="rounded-2xl mb-1 max-w-full" controls />
                    )}
                    {msg.type === 'voice' && msg.mediaUrl && (
                      <audio src={msg.mediaUrl} className="max-w-full mb-1" controls />
                    )}
                    {msg.type === 'file' && msg.mediaUrl && (
                      <a href={msg.mediaUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-2 bg-black/10 rounded-xl px-3 py-2 mb-1 max-w-full hover:bg-black/20 transition-colors" onClick={(e) => e.stopPropagation()}>
                        <FileText size={18} className="text-white shrink-0" />
                        <span className="text-white text-sm truncate">{msg.content.replace('\ud83d\udcc1 ', '')}</span>
                      </a>
                    )}
                    {msg.type === 'location' && msg.mediaUrl && (
                      <a href={msg.mediaUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-2 bg-black/10 rounded-xl px-3 py-2 mb-1 max-w-full hover:bg-black/20 transition-colors" onClick={(e) => e.stopPropagation()}>
                        <MapPin size={18} className="text-[#FF3B30] shrink-0" />
                        <span className="text-white text-sm">Open in Maps</span>
                      </a>
                    )}
                    <div
                      className={`inline-block px-3 py-2 rounded-2xl text-[15px] cursor-pointer active:scale-[0.98] transition-transform ${isSearchMatch ? 'ring-2 ring-[#FFD700]' : ''} ${
                        isMe ? 'bg-[#00C300] text-white rounded-br-none' : 'bg-white text-[#111111] rounded-bl-none'
                      }`}
                      onClick={() => setSelectedReactionMsg(selectedReactionMsg === msg.id ? null : msg.id)}
                      onDoubleClick={() => setReplyingTo(msg)}
                    >
                      <p className="whitespace-pre-wrap break-words">{msg.content}</p>
                    </div>
                    {/* Reactions */}
                    {hasReactions && (
                      <div className={`flex gap-1 mt-1 ${isMe ? 'justify-end' : 'justify-start'}`}>
                        {Object.entries(reactions).map(([reaction, users]) => {
                          if ((users as string[]).length === 0) return null;
                          const rc = reactionEmojis.find(r => r.label === reaction);
                          if (!rc) return null;
                          return (
                            <span key={reaction} className="bg-white rounded-full px-1.5 py-0.5 text-xs shadow-sm flex items-center gap-0.5">
                              <rc.icon size={12} className={rc.color} />
                              <span className="text-[#8D8D8D] text-[10px]">{(users as string[]).length}</span>
                            </span>
                          );
                        })}
                      </div>
                    )}
                    <div className={`text-[10px] mt-1 ${isMe ? 'text-white text-right' : 'text-gray-200'}`}>
                      {formatTime(msg.timestamp)} {isMe && <span>{msg.read ? '\u2713\u2713' : '\u2713'}</span>}
                    </div>
                  </div>
                </motion.div>

                {/* Reaction Picker */}
                <AnimatePresence>
                  {selectedReactionMsg === msg.id && (
                    <motion.div
                      initial={{ opacity: 0, scale: 0.9, y: 10 }}
                      animate={{ opacity: 1, scale: 1, y: 0 }}
                      exit={{ opacity: 0, scale: 0.9, y: 10 }}
                      className={`flex ${isMe ? 'justify-end' : 'justify-start'} mt-1`}
                    >
                      <div className="bg-white rounded-full shadow-lg px-2 py-1 flex gap-1">
                        {reactionEmojis.map((reaction) => (
                          <button type="button" key={reaction.label}
                            onClick={() => handleReact(msg.id, reaction.label)}
                            className="p-1 hover:bg-[#F5F5F5] rounded-full transition-colors"
                          >
                            <reaction.icon size={20} className={reaction.color} />
                          </button>
                        ))}
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            );
          })}

          {/* Typing indicator */}
          {Object.entries(typingUsers).length > 0 && (
            <div className="flex justify-start">
              <div className="bg-white rounded-2xl rounded-bl-none px-4 py-2 flex items-center gap-2">
                <div className="flex gap-1">
                  <span className="w-2 h-2 bg-[#8D8D8D] rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                  <span className="w-2 h-2 bg-[#8D8D8D] rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                  <span className="w-2 h-2 bg-[#8D8D8D] rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                </div>
                <span className="text-xs text-[#8D8D8D]">
                  {Object.values(typingUsers).slice(0, 2).join(', ')} {Object.keys(typingUsers).length > 2 ? `+${Object.keys(typingUsers).length - 2} more` : ''} typing
                </span>
              </div>
            </div>
          )}

          {/* Quick emoji reactions */}
          {msgs.length > 0 && !searchQuery && (
            <div className="flex justify-center gap-2 py-2">
              {quickEmojis.map(emoji => (
                <button type="button" key={emoji}
                  onClick={() => currentUser && groupId && sendGroupMessage(groupId, currentUser.id, emoji)}
                  className="w-8 h-8 rounded-full bg-white/40 hover:bg-white/70 flex items-center justify-center text-lg transition-all active:scale-90"
                >
                  {emoji}
                </button>
              ))}
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>
      </div>

      {/* Reply preview */}
      <AnimatePresence>
        {replyingTo && (
          <motion.div
            initial={{ height: 0 }}
            animate={{ height: 'auto' }}
            exit={{ height: 0 }}
            className="shrink-0 bg-white border-t border-[#EBEBEB] px-4 py-2 flex items-center gap-2"
          >
            <div className="flex-1 min-w-0">
              <p className="text-[10px] text-[#00C300] font-medium">Replying to {getSenderName(replyingTo.senderId)}</p>
              <p className="text-[#8D8D8D] text-xs truncate">{replyingTo.content}</p>
            </div>
            <button type="button" onClick={() => setReplyingTo(null)} className="text-[#8D8D8D] hover:text-[#111111]">
              <X size={16} />
            </button>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Attachments Panel */}
      <AnimatePresence>
        {showAttachments && (
          <motion.div
            initial={{ height: 0 }}
            animate={{ height: 220 }}
            exit={{ height: 0 }}
            className="shrink-0 bg-[#F5F5F5] border-t border-gray-200 overflow-hidden z-10"
          >
            <div className="grid grid-cols-4 gap-y-5 px-6 pt-5 pb-8">
              {attachmentOptions.map((item, i) => (
                <div key={i} className="flex flex-col items-center gap-2 active:opacity-70">
                  <button type="button" onClick={() => {
                      if (item.label === 'Photos') {
                        photoInputRef.current?.click();
                      } else if (item.label === 'Camera') {
                        videoInputRef.current?.click();
                      } else if (item.label === 'Location') {
                        handleLocationShare();
                        setShowAttachments(false);
                      } else if (item.label === 'File') {
                        const fileEl = document.createElement('input');
                        fileEl.type = 'file';
                        fileEl.onchange = (e) => {
                          handleFileUpload(e as unknown as React.ChangeEvent<HTMLInputElement>);
                          setShowAttachments(false);
                        };
                        fileEl.click();
                      } else if (item.label === 'Audio') {
                        startRecording();
                        setShowAttachments(false);
                      } else if (item.label === 'Contact') {
                        handleContactShare();
                      }
                    }}
                    className={`w-14 h-14 ${item.color} rounded-full flex items-center justify-center text-white shadow-sm cursor-pointer`}
                  >
                    {item.icon}
                  </button>
                  <span className="text-[11px] text-[#111111]">{item.label}</span>
                </div>
              ))}
              <input ref={photoInputRef} type="file" accept="image/*" className="hidden" onChange={(e) => { handleMediaUpload(e, 'image'); setShowAttachments(false); }} />
              <input ref={videoInputRef} type="file" accept="video/*" className="hidden" onChange={(e) => { handleMediaUpload(e, 'video'); setShowAttachments(false); }} />
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Pending Scheduled Messages Indicator */}
      {pendingSchedules.length > 0 && (
        <div className="shrink-0 bg-[#8B5CF6]/10 px-3 py-1.5 flex items-center gap-2 z-20">
          <Clock size={14} className="text-[#8B5CF6]" />
          <span className="text-xs text-[#8B5CF6] font-medium">
            {pendingSchedules.length} scheduled message{pendingSchedules.length > 1 ? 's' : ''}
          </span>
        </div>
      )}

      {/* Input */}
      <div className="shrink-0 bg-[#F5F5F5] px-3 py-2.5 flex items-end gap-3 z-20">
        <button type="button" onClick={() => setShowAttachments(!showAttachments)}
          className={`p-1.5 mb-0.5 rounded-full transition-colors ${showAttachments ? 'bg-gray-300 text-gray-700' : 'text-gray-500 hover:bg-gray-200'}`}
        >
          <Plus size={24} strokeWidth={1.5} />
        </button>

        {isRecording ? (
          <div className="flex-1 bg-white rounded-2xl border border-[#FF3B30] flex items-center px-4 min-h-[40px] gap-3">
            <div className="w-3 h-3 rounded-full bg-[#FF3B30] animate-pulse" />
            <span className="text-[#FF3B30] text-sm font-medium">{Math.floor(duration / 60)}:{(duration % 60).toString().padStart(2, '0')}</span>
            <span className="text-[#8D8D8D] text-xs">Recording...</span>
            <button type="button" onClick={cancelRecording} className="ml-auto text-[#8D8D8D] hover:text-[#111111]">
              <X size={18} />
            </button>
          </div>
        ) : (
          <div className="flex-1 bg-white rounded-2xl border border-gray-200 flex items-center px-3 min-h-[40px]">
            <input
              ref={inputRef}
              value={input}
              onChange={(e) => { setInput(e.target.value); sendTyping(); }}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); }
              }}
              onBlur={() => stopTyping()}
              onClick={() => setShowAttachments(false)}
              placeholder="Aa"
              className="flex-1 py-2 text-[15px] focus:outline-none bg-transparent text-[#111111] placeholder:text-[#8D8D8D]"
            />
            <button type="button" className="text-gray-400 p-1 hover:text-gray-600 transition-colors mx-1"
              onClick={() => setShowEmojiPicker(!showEmojiPicker)}
            >
              <Smile size={20} strokeWidth={1.5} />
            </button>
            <button type="button" className="text-gray-400 p-1 hover:text-gray-600 transition-colors"
              onClick={() => {
                if (isRecording) { handleVoiceSend(); } else { startRecording(); }
              }}
            >
              <Mic size={20} strokeWidth={1.5} />
            </button>
          </div>
        )}

        {isRecording ? (
          <button type="button" onClick={handleVoiceSend}
            className="mb-1 p-1.5 text-white bg-[#FF3B30] rounded-full active:scale-95 transition-transform shadow-sm"
          >
            <Send size={18} />
          </button>
        ) : input.trim() ? (
          <button type="button" onClick={handleSend}
            className="mb-1 p-1.5 text-white bg-[#00C300] rounded-full active:scale-95 transition-transform shadow-sm"
          >
            <Send size={18} />
          </button>
        ) : (
          <button type="button" className="mb-0.5 p-1.5 text-gray-500 hover:bg-gray-200 rounded-full transition-colors"
            onClick={() => setShowSchedulePicker(true)}
          >
            <Clock size={24} strokeWidth={1.5} />
          </button>
        )}
      </div>

      {/* Context Menu */}
      <AnimatePresence>
        {contextMenu && (
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.95 }}
            style={{ top: Math.min(contextMenu.y, window.innerHeight - 200), left: Math.min(contextMenu.x, window.innerWidth - 160) }}
            className="fixed bg-white rounded-xl shadow-xl border border-[#EBEBEB] py-1 z-50 w-40"
          >
            <button type="button" onClick={() => { setReplyingTo(contextMenu.msg); setContextMenu(null); }}
              className="w-full flex items-center gap-2 px-3 py-2 text-sm text-[#111111] hover:bg-[#F5F5F5] transition-colors"
            >
              <Reply size={14} /> Reply
            </button>
            <button type="button" onClick={() => handleCopy(contextMenu.msg.content)}
              className="w-full flex items-center gap-2 px-3 py-2 text-sm text-[#111111] hover:bg-[#F5F5F5] transition-colors"
            >
              <Copy size={14} /> Copy
            </button>
            <button type="button" onClick={() => { setForwardMsg(contextMenu.msg); setShowForwardModal(true); setContextMenu(null); }}
              className="w-full flex items-center gap-2 px-3 py-2 text-sm text-[#111111] hover:bg-[#F5F5F5] transition-colors"
            >
              <Forward size={14} /> Forward
            </button>
            {contextMenu.msg.senderId === currentUser?.id && (
              <button type="button" onClick={() => handleDelete(contextMenu.msg.id)}
                className="w-full flex items-center gap-2 px-3 py-2 text-sm text-[#FF3B30] hover:bg-[#FF3B30]/10 transition-colors"
              >
                <Trash2 size={14} /> Delete
              </button>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Forward Modal */}
      <AnimatePresence>
        {showForwardModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4"
            onClick={() => setShowForwardModal(false)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="bg-white rounded-2xl p-6 max-w-sm w-full max-h-[80vh] overflow-y-auto"
              onClick={e => e.stopPropagation()}
            >
              <h3 className="text-lg font-bold text-[#111111] mb-4">Forward to</h3>
              <div className="space-y-2">
                {groups.length === 0 ? (
                  <p className="text-[#8D8D8D] text-sm text-center py-4">No groups to forward to</p>
                ) : (
                  groups.map((g) => (
                    <button type="button" key={g.id}
                      onClick={async () => { await handleForward(g.id); }}
                      className="w-full flex items-center gap-3 p-3 rounded-xl hover:bg-[#F5F5F5] transition-colors text-left"
                    >
                      <div className="w-10 h-10 rounded-full bg-[#00C300]/10 flex items-center justify-center shrink-0">
                        <Users size={18} className="text-[#00C300]" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-[#111111] text-sm font-medium truncate">{g.name}</p>
                        <p className="text-[#8D8D8D] text-xs truncate">{g.participants.length} members</p>
                      </div>
                      <ArrowRight size={18} className="text-[#C7C7CC] shrink-0" />
                    </button>
                  ))
                )}
              </div>
              <button type="button" onClick={() => setShowForwardModal(false)}
                className="w-full mt-4 py-3 bg-[#F5F5F5] text-[#111111] rounded-xl text-sm font-bold"
              >
                Cancel
              </button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Schedule Picker */}
      <AnimatePresence>
        {showSchedulePicker && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4"
            onClick={() => setShowSchedulePicker(false)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="bg-white rounded-2xl p-6 max-w-sm w-full"
              onClick={e => e.stopPropagation()}
            >
              <h3 className="text-lg font-bold text-[#111111] mb-4 flex items-center gap-2">
                <Calendar size={20} className="text-[#8B5CF6]" /> Schedule Message
              </h3>
              <p className="text-[#8D8D8D] text-sm mb-3">Select a date and time to send this message:</p>
              <input
                type="datetime-local"
                value={scheduleDate}
                onChange={(e) => setScheduleDate(e.target.value)}
                className="w-full bg-[#F5F5F5] rounded-xl px-3 py-3 text-sm text-[#111111] focus:outline-none focus:ring-2 focus:ring-[#8B5CF6]"
              />
              <p className="text-[#8D8D8D] text-xs mt-2 mb-4">Message: {input || 'No message'}</p>
              <div className="flex gap-2">
                <button type="button" onClick={() => setShowSchedulePicker(false)} className="flex-1 py-3 bg-[#F5F5F5] text-[#111111] rounded-xl text-sm font-bold">
                  Cancel
                </button>
                <button type="button" onClick={handleScheduleSend}
                  disabled={!scheduleDate || !input.trim()}
                  className="flex-1 py-3 bg-[#8B5CF6] text-white rounded-xl text-sm font-bold disabled:opacity-50"
                >
                  Schedule
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import { useAuthStore } from '@/store/useAuthStore';
import { useEnhancedTimelineStore } from '@/store/useEnhancedTimelineStore';
import { usePremiumStore } from '@/store/usePremiumStore';
import {
  TrendingUp, Hash, Search, ChevronRight, Users, Plus, Bookmark, X, Flame
} from 'lucide-react';
import type { Hashtag } from '@/types';

const MOCK_HASHTAGS: Hashtag[] = [
  { id: '1', tag: 'gagachat', postCount: 12450, followers: ['u1','u2','u3'], trending: true, trendRank: 1, relatedTags: ['chat','messaging'], description: 'Official GaGa Chat community' },
  { id: '2', tag: 'tech', postCount: 8920, followers: ['u1','u4'], trending: true, trendRank: 2, relatedTags: ['technology','innovation'], description: 'Technology and innovation' },
  { id: '3', tag: 'gaming', postCount: 7650, followers: ['u2','u5'], trending: true, trendRank: 3, relatedTags: ['games','esports'], description: 'Gaming community' },
  { id: '4', tag: 'music', postCount: 6200, followers: ['u3','u6'], trending: true, trendRank: 4, relatedTags: ['songs','artists'], description: 'Music and artists' },
  { id: '5', tag: 'food', postCount: 5400, followers: ['u4'], trending: false, relatedTags: ['cooking','recipes'], description: 'Food and recipes' },
  { id: '6', tag: 'travel', postCount: 4800, followers: ['u5'], trending: false, relatedTags: ['adventure','explore'], description: 'Travel and adventure' },
  { id: '7', tag: 'photography', postCount: 4200, followers: ['u6'], trending: false, relatedTags: ['photos','camera'], description: 'Photography community' },
  { id: '8', tag: 'memes', postCount: 8900, followers: ['u1','u2','u3','u4'], trending: true, trendRank: 5, relatedTags: ['funny','humor'], description: 'Funny memes and humor' },
  { id: '9', tag: 'coding', postCount: 3100, followers: ['u1'], trending: false, relatedTags: ['programming','dev'], description: 'Coding and programming' },
  { id: '10', tag: 'fitness', postCount: 2800, followers: ['u2'], trending: false, relatedTags: ['gym','health'], description: 'Fitness and health' },
];

export default function HashtagsPage() {
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const { trendingHashtags, followedHashtags, getTrendingHashtags, followHashtag, unfollowHashtag } = useEnhancedTimelineStore();
  const { isPremium } = usePremiumStore();
  const [tab, setTab] = useState<'trending' | 'following' | 'discover'>('trending');
  const [search, setSearch] = useState('');
  const [localHashtags, setLocalHashtags] = useState<Hashtag[]>(MOCK_HASHTAGS);

  useEffect(() => {
    getTrendingHashtags(20);
  }, [getTrendingHashtags]);

  const displayHashtags = trendingHashtags.length > 0 ? trendingHashtags : localHashtags;

  const filtered = displayHashtags.filter((h) =>
    h.tag.toLowerCase().includes(search.toLowerCase()) ||
    h.description?.toLowerCase().includes(search.toLowerCase())
  );

  const followed = followedHashtags.map((h) => h.id);

  const handleFollow = (hashtagId: string) => {
    if (followed.includes(hashtagId)) {
      unfollowHashtag(hashtagId, user?.id || '');
      setLocalHashtags((prev) => prev.map((h) => h.id === hashtagId ? { ...h, followers: h.followers.filter((f) => f !== user?.id) } : h));
    } else {
      followHashtag(hashtagId, user?.id || '');
      setLocalHashtags((prev) => prev.map((h) => h.id === hashtagId ? { ...h, followers: [...h.followers, user?.id || ''] } : h));
    }
  };

  const isFollowing = (id: string) => followed.includes(id) || localHashtags.find((h) => h.id === id)?.followers?.includes(user?.id || '');

  const getTrendIcon = (rank?: number) => {
    if (!rank) return null;
    if (rank <= 3) return <Flame size={14} className="text-orange-500" />;
    return <TrendingUp size={14} className="text-[#00C300]" />;
  };

  return (
    <div className="min-h-[100dvh] bg-white">
      {/* Header */}
      <div className="sticky top-0 bg-white border-b border-gray-100 z-10 px-4 py-3">
        <div className="flex items-center gap-3">
          <button type="button" onClick={() => navigate(-1)} className="p-2 hover:bg-gray-100 rounded-full">
            <X size={20} className="text-gray-500" />
          </button>
          <h1 className="font-bold text-lg text-gray-900">Hashtags</h1>
        </div>
      </div>

      {/* Search */}
      <div className="px-4 py-3">
        <div className="relative">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search hashtags..."
            className="w-full pl-9 pr-3 py-2.5 bg-gray-100 rounded-xl text-sm outline-none focus:ring-2 focus:ring-[#00C300]/20"
          />
        </div>
      </div>

      {/* Tabs */}
      <div className="px-4 pb-3 flex gap-1">
        {(['trending', 'following', 'discover'] as const).map((t) => (
          <button type="button" key={t}
            onClick={() => setTab(t)}
            className={`px-4 py-1.5 rounded-full text-sm font-medium transition-colors ${tab === t ? 'bg-[#00C300] text-white' : 'bg-gray-100 text-gray-600'}`}
          >
            {t === 'trending' ? 'Trending' : t === 'following' ? 'Following' : 'Discover'}
          </button>
        ))}
      </div>

      {/* Content */}
      <div className="px-4 pb-8">
        {tab === 'trending' && (
          <div className="space-y-2">
            {filtered
              .filter((h) => h.trending)
              .sort((a, b) => (b.trendRank || 999) - (a.trendRank || 999))
              .map((hashtag, idx) => (
                <motion.div
                  key={hashtag.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.05 }}
                  className="flex items-center gap-3 p-3 rounded-xl hover:bg-gray-50 transition-colors"
                >
                  <div className="w-8 h-8 rounded-full bg-[#00C300]/10 flex items-center justify-center shrink-0">
                    <span className="text-xs font-bold text-[#00C300]">#{hashtag.trendRank || idx + 1}</span>
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-1.5">
                      <p className="font-medium text-gray-900 text-sm">#{hashtag.tag}</p>
                      {getTrendIcon(hashtag.trendRank)}
                    </div>
                    <p className="text-xs text-gray-400">{hashtag.postCount.toLocaleString()} posts</p>
                    {hashtag.relatedTags && hashtag.relatedTags.length > 0 && (
                      <div className="flex gap-1 mt-1">
                        {hashtag.relatedTags.slice(0, 3).map((rt) => (
                          <span key={rt} className="text-[10px] text-gray-400 bg-gray-100 px-1.5 py-0.5 rounded-full">{rt}</span>
                        ))}
                      </div>
                    )}
                  </div>
                  <button type="button" onClick={() => handleFollow(hashtag.id)}
                    className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${isFollowing(hashtag.id) ? 'bg-gray-100 text-gray-500' : 'bg-[#00C300] text-white'}`}
                  >
                    {isFollowing(hashtag.id) ? 'Following' : 'Follow'}
                  </button>
                </motion.div>
              ))}
          </div>
        )}

        {tab === 'following' && (
          <div className="space-y-2">
            {filtered.filter((h) => isFollowing(h.id)).length === 0 ? (
              <div className="text-center py-16">
                <Bookmark size={48} className="mx-auto text-gray-200 mb-4" />
                <p className="text-gray-400 font-medium">No hashtags followed yet</p>
              </div>
            ) : (
              filtered.filter((h) => isFollowing(h.id)).map((hashtag) => (
                <div key={hashtag.id} className="flex items-center gap-3 p-3 rounded-xl bg-gray-50">
                  <Hash size={20} className="text-[#00C300]" />
                  <div className="flex-1">
                    <p className="font-medium text-gray-900 text-sm">#{hashtag.tag}</p>
                    <p className="text-xs text-gray-400">{hashtag.postCount.toLocaleString()} posts</p>
                  </div>
                  <button type="button" onClick={() => handleFollow(hashtag.id)}
                    className="px-3 py-1.5 rounded-full text-xs font-medium bg-gray-200 text-gray-600 hover:bg-gray-300 transition-colors"
                  >
                    Unfollow
                  </button>
                </div>
              ))
            )}
          </div>
        )}

        {tab === 'discover' && (
          <div className="space-y-2">
            {filtered.map((hashtag, idx) => (
              <motion.div
                key={hashtag.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: idx * 0.03 }}
                className="flex items-center gap-3 p-3 rounded-xl hover:bg-gray-50 transition-colors"
              >
                <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-[#00C300]/20 to-[#00C300]/5 flex items-center justify-center shrink-0">
                  <Hash size={20} className="text-[#00C300]" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-medium text-gray-900 text-sm">#{hashtag.tag}</p>
                  <p className="text-xs text-gray-400">{hashtag.postCount.toLocaleString()} posts · {(hashtag.followers?.length || 0).toLocaleString()} followers</p>
                </div>
                <button type="button" onClick={() => handleFollow(hashtag.id)}
                  className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${isFollowing(hashtag.id) ? 'bg-gray-100 text-gray-500' : 'bg-[#00C300] text-white'}`}
                >
                  {isFollowing(hashtag.id) ? 'Following' : 'Follow'}
                </button>
              </motion.div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

