                </button>
                {/* Condition badge */}
                <span className={`absolute top-2 left-2 px-2 py-0.5 rounded-md text-[10px] font-bold ${conditionColors[item.condition] || 'bg-[#8D8D8D] text-white'}`}>
                  {conditionLabels[item.condition] || item.condition}
