                <div className="flex items-center gap-1.5 mb-1.5">
                  <span className="text-[#00C300] font-bold text-sm">{item.price} {item.currency}</span>
                  {item.isNegotiable && (
                    <span className="text-[10px] px-1.5 py-0.5 rounded bg-[#2a2a2a] text-[#8D8D8D]">
