  blocked_interaction: 'Security',
};

function isToday(date: Date) {
  const now = new Date();
  return date.toDateString() === now.toDateString();
}

function isYesterday(date: Date) {
  const now = new Date();
  const yest = new Date(now);
  yest.setDate(yest.getDate() - 1);
  return date.toDateString() === yest.toDateString();
}

function isThisWeek(date: Date) {
  const now = new Date();
  const weekAgo = new Date(now);
  weekAgo.setDate(weekAgo.getDate() - 7);
  return date >= weekAgo && !isToday(date) && !isYesterday(date);
}

export default function NotificationsPage() {
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const { notifications, markRead, markAllRead, clearAll, subscribe, loading } = useNotificationStore();
  const [filterType, setFilterType] = useState<string | 'all'>('all');
  const [showFilter, setShowFilter] = useState(false);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [selectMode, setSelectMode] = useState(false);
  const { permission, supported, requestPermission } = usePushNotifications();

  const [showSettings, setShowSettings] = useState(false);
  const [mutedTypes, setMutedTypes] = useState<string[]>(() => {
    try { return JSON.parse(localStorage.getItem('gaga-muted-notif-types') || '[]'); } catch { return []; }
  });

  const toggleMuteType = (type: string) => {
    setMutedTypes(prev => {
      const next = prev.includes(type) ? prev.filter(t => t !== type) : [...prev, type];
      localStorage.setItem('gaga-muted-notif-types', JSON.stringify(next));
      return next;
    });
  };

  const isMuted = (type: string) => mutedTypes.includes(type);

  useEffect(() => {
    if (!user?.id) return;
    return subscribe(user.id);
  }, [user?.id]);

  const filtered = useMemo(() => {
    let list = [...notifications];
    if (filterType !== 'all') {
      list = list.filter(n => n.type === filterType);
    }
    return list;
  }, [notifications, filterType]);

  const grouped = useMemo(() => {
    const today: typeof filtered = [];
    const yesterday: typeof filtered = [];
    const thisWeek: typeof filtered = [];
    const earlier: typeof filtered = [];
    for (const n of filtered) {
      const d = new Date(n.timestamp);
      if (isToday(d)) today.push(n);
      else if (isYesterday(d)) yesterday.push(n);
      else if (isThisWeek(d)) thisWeek.push(n);
      else earlier.push(n);
    }
    return { today, yesterday, thisWeek, earlier };
  }, [filtered]);

  const unreadCount = notifications.filter(n => !n.read).length;

  const toggleSelect = (id: string) => {
    setSelectedIds(prev => prev.includes(id) ? prev.filter(s => s !== id) : [...prev, id]);
  };

  const handleDeleteSelected = async () => {
    if (isFirestoreAvailable()) {
      await batchDelete(selectedIds.map(id => ({ collection: 'notifications', docId: id })));
    }
    setSelectedIds([]);
    setSelectMode(false);
    toast.success('Notifications deleted');
  };

  const handleMarkSelectedRead = () => {
    selectedIds.forEach(id => markRead(id));
    setSelectedIds([]);
    setSelectMode(false);
  };

  const renderGroup = (title: string, items: typeof filtered, showDivider: boolean) => {
    if (items.length === 0) return null;
    return (
      <div className={showDivider ? 'border-t border-[#EBEBEB]' : ''}>
        <div className="px-4 py-2 bg-[#F5F5F5]">
          <p className="text-[#8D8D8D] text-xs font-medium uppercase tracking-wider">{title}</p>
        </div>
        {items.map((notif, i) => {
          const Icon = iconMap[notif.type] || Bell;
          const colorClass = iconColors[notif.type] || 'bg-[#F5F5F5] text-[#8D8D8D]';
          const isSelected = selectedIds.includes(notif.id);
          return (
            <motion.div
              key={notif.id}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: i * 0.03 }}
              onClick={() => {
                if (selectMode) {
                  toggleSelect(notif.id);
                } else {
                  markRead(notif.id);
                  if (notif.data?.chatId) navigate(`/chat/${notif.data.chatId}`);
                  else if (notif.data?.groupId) navigate(`/group/${notif.data.groupId}`);
                  else if (notif.data?.userId) navigate(`/profile/${notif.data.userId}`);
                  else if (notif.data?.fromUserId) navigate(`/profile/${notif.data.fromUserId}`);
                  else if (notif.type === 'friend_request') navigate('/add-friends');
                }
              }}
              className={`flex items-start gap-3 p-4 active:bg-gray-50 transition-colors cursor-pointer relative ${
                !notif.read ? 'bg-[#00C300]/5' : 'bg-white'
              } ${isSelected ? 'bg-[#00C300]/10' : ''}`}
            >
              {selectMode && (
                <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 mt-2 ${
                  isSelected ? 'bg-[#00C300] border-[#00C300]' : 'border-[#C7C7CC]'
                }`}>
                  {isSelected && <Check size={12} className="text-white" />}
                </div>
              )}
              <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 ${colorClass}`}>
                <Icon size={18} />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-[#111111] text-sm font-medium">{notif.title}</p>
                <p className="text-[#8D8D8D] text-xs mt-0.5">{notif.body}</p>
                <p className="text-[#C7C7CC] text-[10px] mt-1">{formatTime(notif.timestamp)}</p>
              </div>
              {!notif.read && !selectMode && <div className="w-2 h-2 rounded-full bg-[#00C300] shrink-0 mt-2" />}
              {!selectMode && (
                <ChevronRight size={16} className="text-[#C7C7CC] shrink-0 mt-2" />
              )}
            </motion.div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="min-h-[100dvh] bg-[#F5F5F5]">
      {/* Header */}
      <div className="sticky top-0 z-10 bg-white/90 backdrop-blur-md border-b border-[#EBEBEB]">
        <div className="flex items-center justify-between p-4">
          <div className="flex items-center gap-3">
            <button type="button" onClick={() => navigate(-1)} className="text-[#111111] hover:text-[#8D8D8D] p-1 -ml-1">
              <ArrowLeft size={22} />
            </button>
            <div>
              <h1 className="text-lg font-bold text-[#111111]">Notifications</h1>
              {unreadCount > 0 && <p className="text-[#00C300] text-xs font-medium">{unreadCount} unread</p>}
            </div>
          </div>
          <div className="flex gap-2">
            {notifications.length > 0 && (
              <>
                <button type="button" onClick={() => setShowSettings(true)}
                  className="p-1.5 rounded-full text-[#8D8D8D] hover:text-[#111111] transition-colors"
                >
                  <Settings size={18} />
                </button>
                <button type="button" onClick={() => setSelectMode(!selectMode)}
                  className={`text-xs font-medium px-2 py-1 rounded-full transition-colors ${
                    selectMode ? 'bg-[#00C300] text-white' : 'text-[#00C300]'
                  }`}
                >
                  {selectMode ? 'Done' : 'Select'}
                </button>
                <button type="button" onClick={() => setShowFilter(!showFilter)}
                  className={`p-1.5 rounded-full transition-colors ${showFilter ? 'bg-[#00C300]/10 text-[#00C300]' : 'text-[#8D8D8D]'}`}
                >
                  <Filter size={18} />
                </button>
              </>
            )}
          </div>
        </div>

        {/* Push Notification Permission Banner */}
      {supported && permission === 'default' && (
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-[#00C300]/10 border-b border-[#00C300]/20 px-4 py-3 flex items-center gap-3"
        >
          <BellRing size={18} className="text-[#00C300] shrink-0" />
          <div className="flex-1">
            <p className="text-[#111111] text-sm font-medium">Enable push notifications</p>
            <p className="text-[#8D8D8D] text-xs">Get notified about messages and calls</p>
          </div>
          <button type="button" onClick={requestPermission}
            className="px-3 py-1.5 bg-[#00C300] text-white text-xs rounded-full font-medium active:bg-[#00A300] transition-colors"
          >
            Enable
          </button>
        </motion.div>
      )}

      {/* Filter Bar */}
        <AnimatePresence>
          {showFilter && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              className="overflow-hidden border-t border-[#EBEBEB]"
            >
              <div className="flex gap-2 p-3 overflow-x-auto scrollbar-hide">
                <button type="button" onClick={() => setFilterType('all')}
                  className={`px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap transition-colors ${
                    filterType === 'all' ? 'bg-[#00C300] text-white' : 'bg-[#F5F5F5] text-[#8D8D8D]'
                  }`}
                >
                  All
                </button>
                {Object.entries(typeLabels).map(([type, label]) => (
                  <button type="button" key={type}
                    onClick={() => setFilterType(type)}
                    className={`px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap transition-colors ${
                      filterType === type ? 'bg-[#00C300] text-white' : 'bg-[#F5F5F5] text-[#8D8D8D]'
                    }`}
                  >
                    {label}
                  </button>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Bulk Actions */}
        <AnimatePresence>
          {selectMode && selectedIds.length > 0 && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              className="overflow-hidden border-t border-[#EBEBEB]"
            >
              <div className="flex gap-2 p-3">
                <button type="button" onClick={handleMarkSelectedRead}
                  className="flex items-center gap-1 px-3 py-1.5 bg-[#00C300]/10 text-[#00C300] text-xs rounded-full font-medium"
                >
                  <CheckCheck size={12} /> Mark Read
                </button>
                <button type="button" onClick={handleDeleteSelected}
                  className="flex items-center gap-1 px-3 py-1.5 bg-[#FF3B30]/10 text-[#FF3B30] text-xs rounded-full font-medium"
                >
                  <Trash2 size={12} /> Delete
                </button>
                <button type="button" onClick={() => { setSelectedIds([]); setSelectMode(false); }}
                  className="flex items-center gap-1 px-3 py-1.5 bg-[#F5F5F5] text-[#8D8D8D] text-xs rounded-full font-medium ml-auto"
                >
                  <X size={12} /> Cancel
                </button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Notification List */}
      <div className="divide-y divide-[#EBEBEB]">
        {loading ? (
          <div className="p-4">
            <LoadingSkeleton count={6} variant="list" />
          </div>
        ) : notifications.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-64 text-[#8D8D8D]">
            <div className="w-16 h-16 rounded-full bg-[#F5F5F5] flex items-center justify-center mb-4">
              <Bell size={32} className="text-[#C7C7CC]" />
            </div>
            <p className="text-sm font-medium">No notifications</p>
            <p className="text-xs mt-1">You are all caught up!</p>
          </div>
        ) : filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-64 text-[#8D8D8D]">
            <Filter size={32} className="mb-3 text-[#C7C7CC]" />
            <p className="text-sm">No notifications match this filter</p>
          </div>
        ) : (
          <>
            {renderGroup('Today', grouped.today, false)}
            {renderGroup('Yesterday', grouped.yesterday, true)}
            {renderGroup('This Week', grouped.thisWeek, true)}
            {renderGroup('Earlier', grouped.earlier, true)}
          </>
        )}
      </div>

      {/* Floating Mark All Read */}
      {unreadCount > 0 && !selectMode && (
        <motion.button
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          onClick={markAllRead}
          className="fixed bottom-20 left-1/2 -translate-x-1/2 flex items-center gap-2 px-4 py-2.5 bg-[#00C300] text-white rounded-full text-sm font-medium shadow-lg hover:bg-[#00A300] transition-colors z-20"
        >
          <CheckCheck size={16} /> Mark all as read ({unreadCount})
        </motion.button>
      )}

      {/* Notification Settings Modal */}
      <AnimatePresence>
        {showSettings && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 bg-black/50 flex items-end sm:items-center justify-center"
            onClick={() => setShowSettings(false)}
          >
            <motion.div
              initial={{ y: '100%' }}
              animate={{ y: 0 }}
              exit={{ y: '100%' }}
              transition={{ type: 'spring', damping: 25, stiffness: 300 }}
              className="bg-white rounded-t-2xl sm:rounded-2xl w-full sm:max-w-sm max-h-[80vh] flex flex-col"
              onClick={e => e.stopPropagation()}
            >
              <div className="flex items-center justify-between p-4 border-b border-[#EBEBEB]">
                <h2 className="text-lg font-bold text-[#111111]">Notification Settings</h2>
                <button type="button" onClick={() => setShowSettings(false)} className="p-1 text-[#8D8D8D]">
                  <X size={20} />
                </button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-4">
                <p className="text-[#8D8D8D] text-xs">Mute notification types you don&apos;t want to receive</p>
                {Object.entries(typeLabels).map(([type, label]) => {
                  const Icon = iconMap[type] || Bell;
                  const muted = isMuted(type);
                  return (
                    <div key={type} className="flex items-center justify-between py-2">
                      <div className="flex items-center gap-3">
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center ${iconColors[type] || 'bg-[#F5F5F5] text-[#8D8D8D]'}`}>
                          <Icon size={14} />
                        </div>
                        <span className="text-sm text-[#111111]">{label}</span>
                      </div>
                      <button type="button" onClick={() => toggleMuteType(type)}
                        className={`p-1.5 rounded-full transition-colors ${muted ? 'bg-[#FF3B30]/10 text-[#FF3B30]' : 'bg-[#00C300]/10 text-[#00C300]'}`}
                      >
                        {muted ? <VolumeX size={16} /> : <Volume2 size={16} />}
                      </button>
                    </div>
                  );
                })}
              </div>
              <div className="p-4 border-t border-[#EBEBEB]">
                <button type="button" onClick={() => setShowSettings(false)}
                  className="w-full py-3 bg-[#00C300] text-white rounded-xl text-sm font-bold hover:bg-[#00A300] transition-colors"
                >
                  Done
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  MessageCircle, Users, Phone, Video, Wallet, Sparkles,
  ArrowRight, Check, Globe, Zap, Shield, ChevronRight
} from 'lucide-react';
import Logo from '@/components/Logo';

const STEPS = [
  {
    icon: Sparkles,
    title: 'Welcome to GaGa Chat',
    description: 'The free messaging app for everyone. Chat, call, share, and earn — all in one place. No VPN needed, supports all languages.',
    color: 'text-[#00C300]',
    bg: 'bg-[#00C300]/10',
  },
  {
    icon: Users,
    title: 'Find Your Friends',
    description: 'Add friends by username, phone number, or scan their QR code. See who\'s online and start chatting instantly.',
    color: 'text-[#2196F3]',
    bg: 'bg-[#2196F3]/10',
  },
  {
    icon: MessageCircle,
    title: 'Rich Messaging',
    description: 'Send text, photos, videos, voice messages, and files. React with emojis, reply to messages, and forward to anyone.',
    color: 'text-[#FF9800]',
    bg: 'bg-[#FF9800]/10',
  },
  {
    icon: Video,
    title: 'Voice & Video Calls',
    description: 'Crystal-clear voice and video calls with your friends. Free, unlimited, and built right into the app.',
    color: 'text-[#8B5CF6]',
    bg: 'bg-[#8B5CF6]/10',
  },
  {
    icon: Wallet,
    title: 'Wallet & Rewards',
    description: 'Earn Gaga Coins by using the app, referring friends, and staking. Use coins for premium features and tips.',
    color: 'text-[#FFD700]',
    bg: 'bg-[#FFD700]/10',
  },
  {
    icon: Shield,
    title: 'Privacy First',
    description: 'Your messages are private. Control who can see your profile, last seen status, and friend list. Built with security in mind.',
    color: 'text-[#00C3C3]',
    bg: 'bg-[#00C3C3]/10',
  },
];

export default function OnboardingPage() {
  const navigate = useNavigate();
  const [step, setStep] = useState(0);
  const [direction, setDirection] = useState(1);

  const goNext = () => {
    if (step < STEPS.length - 1) {
      setDirection(1);
      setStep(s => s + 1);
    } else {
      completeOnboarding();
    }
  };

  const goBack = () => {
    if (step > 0) {
      setDirection(-1);
      setStep(s => s - 1);
    }
  };

  const completeOnboarding = () => {
    localStorage.setItem('gaga-onboarding-complete', 'true');
    navigate('/contacts');
  };

  const skip = () => {
    localStorage.setItem('gaga-onboarding-complete', 'true');
    navigate('/contacts');
  };

  const current = STEPS[step];
  const Icon = current.icon;

  return (
    <div className="h-[100dvh] w-screen bg-white flex flex-col overflow-hidden">
      {/* Header */}
      <div className="shrink-0 flex items-center justify-between px-6 py-4">
        <div className="flex items-center gap-2">
          <Logo size={32} />
          <span className="text-[#111111] font-bold text-sm">GaGa Chat</span>
        </div>
        <button type="button" onClick={skip}
          className="text-[#8D8D8D] text-sm font-medium hover:text-[#111111] transition-colors"
        >
          Skip
        </button>
      </div>

      {/* Progress */}
      <div className="shrink-0 px-6 mb-4">
        <div className="flex gap-1.5">
          {STEPS.map((_, i) => (
            <div
              key={i}
              className={`h-1 rounded-full transition-all duration-300 ${
                i <= step ? 'bg-[#00C300] flex-1' : 'bg-[#EBEBEB] flex-1'
              }`}
            />
          ))}
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 flex items-center justify-center px-6 relative">
        <AnimatePresence mode="wait" custom={direction}>
          <motion.div
            key={step}
            custom={direction}
            initial={{ opacity: 0, x: direction * 50 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: direction * -50 }}
            transition={{ duration: 0.3, ease: 'easeInOut' }}
            className="text-center max-w-sm mx-auto"
          >
            <div className={`w-24 h-24 rounded-3xl ${current.bg} flex items-center justify-center mx-auto mb-6`}>
              <Icon size={40} className={current.color} />
            </div>
            <h2 className="text-2xl font-bold text-[#111111] mb-3">{current.title}</h2>
            <p className="text-[#8D8D8D] text-base leading-relaxed">{current.description}</p>
          </motion.div>
        </AnimatePresence>
      </div>

      {/* Footer */}
      <div className="shrink-0 px-6 pb-8 pt-4">
        <div className="flex items-center gap-3">
          {step > 0 && (
            <button type="button" onClick={goBack}
              className="px-4 py-3 rounded-xl bg-[#F5F5F5] text-[#111111] text-sm font-medium hover:bg-[#EBEBEB] transition-colors"
            >
              Back
            </button>
          )}
          <button type="button" onClick={goNext}
            className="flex-1 py-3 rounded-xl bg-[#00C300] text-white text-sm font-bold hover:bg-[#00A300] transition-colors flex items-center justify-center gap-2"
          >
            {step === STEPS.length - 1 ? (
              <>
                Get Started <Check size={16} />
              </>
            ) : (
              <>
                Next <ArrowRight size={16} />
              </>
            )}
          </button>
        </div>
        <p className="text-center text-[#8D8D8D] text-xs mt-4">
          Step {step + 1} of {STEPS.length}
        </p>
      </div>
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  ArrowLeft, Check, Sparkles, Crown, Zap, Star,
  Copy, Share2, Gift, Clock, Shield, Palette, BarChart3,
  Headphones, Megaphone, Globe, ArrowRight, Loader, Coins,
  Banknote, DollarSign, X
} from 'lucide-react';
import { useAuthStore } from '@/store/useAuthStore';
import {
  usePremiumStore,
  PREMIUM_PLANS,
  PLAN_PRICING_USD,
  PLAN_PRICING_COINS,
  REFERRAL_REWARD_COINS,
  type PremiumTier,
} from '@/store/usePremiumStore';
import { toast } from 'sonner';

const currencySymbols: Record<string, string> = {
  BDT: '৳',
  USD: '$',
  coins: 'G',
};

export default function PremiumPage() {
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const {
    currentTier,
    subscription,
    loading,
    referralCode,
    referralCount,
    subscribeToPremium,
    upgradePlan,
    generateReferralCode,
    getReferralStats,
    getDaysRemaining,
  } = usePremiumStore();

  const [selectedCurrency, setSelectedCurrency] = useState<'BDT' | 'USD' | 'coins'>('BDT');
  const [activePlan, setActivePlan] = useState<string | null>(null);
  const [upgrading, setUpgrading] = useState(false);
  const [showReferral, setShowReferral] = useState(false);
  const [referralInput, setReferralInput] = useState('');
  const [applyingReferral, setApplyingReferral] = useState(false);
  const [copied, setCopied] = useState(false);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (!user?.id) return;
    const unsub = subscribeToPremium(user.id);
    return () => { unsub(); };
  }, [user?.id, subscribeToPremium]);

  useEffect(() => {
    if (user?.id) {
      getReferralStats(user.id);
    }
  }, [user?.id, getReferralStats]);

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  const effectiveCode = referralCode || (user ? generateReferralCode(user.id) : '');

  const handleUpgrade = async (planId: string) => {
    if (!user) {
      toast.error('Please login first');
      navigate('/auth');
      return;
    }
    if (planId === 'free') return;
    setActivePlan(planId);
    setUpgrading(true);
    const success = await upgradePlan(user.id, planId, selectedCurrency);
    setUpgrading(false);
    if (!success) setActivePlan(null);
  };

  const handleCopyReferral = () => {
    navigator.clipboard.writeText(effectiveCode).then(() => {
      setCopied(true);
      toast.success('Referral code copied!');
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      timeoutRef.current = setTimeout(() => setCopied(false), 2000);
    });
  };

  const handleShareReferral = async () => {
    const shareData = {
      title: 'Join GaGa Chat',
      text: `Use my referral code ${effectiveCode} to join GaGa Chat and earn ${REFERRAL_REWARD_COINS} coins!`,
      url: window.location.origin,
    };
    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        handleCopyReferral();
      }
    } catch {
      // ignore
    }
  };

  const handleApplyReferral = async () => {
    if (!user || !referralInput.trim()) return;
    setApplyingReferral(true);
    const { usePremiumStore: store } = await import('@/store/usePremiumStore');
    const success = await store.getState().applyReferralCode(user.id, referralInput.trim(), user.name);
    setApplyingReferral(false);
    if (success) {
      setReferralInput('');
      setShowReferral(false);
    }
  };

  const daysRemaining = getDaysRemaining();
  const isSubscribed = currentTier !== 'free';

  const getPrice = (planId: string) => {
    if (planId === 'free') return 0;
    if (selectedCurrency === 'USD') return PLAN_PRICING_USD[planId];
    if (selectedCurrency === 'coins') return PLAN_PRICING_COINS[planId];
    return PREMIUM_PLANS.find(p => p.id === planId)?.price || 0;
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: { staggerChildren: 0.1 },
    },
  };

  const cardVariants = {
    hidden: { opacity: 0, y: 30 },
    show: { opacity: 1, y: 0, transition: { type: 'spring' as const, damping: 20, stiffness: 100 } },
  };

  const tierIcons: Record<string, React.ReactNode> = {
    free: <Star size={20} />,
    premium: <Sparkles size={20} />,
    vip: <Crown size={20} />,
    creator: <Zap size={20} />,
  };

  return (
    <div className="min-h-[100dvh] bg-[#F5F5F5] pb-20">
      {/* Header */}
      <div className="sticky top-0 z-30 bg-white/80 backdrop-blur-md border-b border-[#EBEBEB]">
        <div className="max-w-3xl mx-auto px-4 h-14 flex items-center justify-between">
          <button type="button" onClick={() => navigate(-1)}
            className="p-2 -ml-2 hover:bg-[#F5F5F5] rounded-full transition-colors"
          >
            <ArrowLeft size={22} className="text-[#111111]" />
          </button>
          <h1 className="text-lg font-bold text-[#111111]">GaGa Premium</h1>
          <div className="w-10" />
        </div>
      </div>

      <div className="max-w-3xl mx-auto px-4 py-6 space-y-8">
        {/* Current Status Hero */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-gradient-to-br from-[#00C300] to-[#00A300] rounded-2xl p-6 text-white relative overflow-hidden"
        >
          <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -translate-y-1/2 translate-x-1/2" />
          <div className="absolute bottom-0 left-0 w-24 h-24 bg-white/10 rounded-full translate-y-1/2 -translate-x-1/2" />
          <div className="relative z-10">
            <div className="flex items-center gap-2 mb-2">
              <div className="bg-white/20 rounded-lg px-2 py-1 text-xs font-bold uppercase tracking-wide">
                {currentTier}
              </div>
              {isSubscribed && daysRemaining > 0 && (
                <div className="bg-white/20 rounded-lg px-2 py-1 text-xs font-medium flex items-center gap-1">
                  <Clock size={12} /> {daysRemaining} days left
                </div>
              )}
            </div>
            <h2 className="text-2xl font-bold mb-1">
              {isSubscribed ? 'You\'re Premium!' : 'Unlock GaGa Premium'}
            </h2>
            <p className="text-white/90 text-sm max-w-xs">
              {isSubscribed
                ? `Enjoy your ${currentTier} benefits. Your subscription renews automatically.`
                : 'Get verified, go ad-free, and unlock exclusive features for creators and power users.'}
            </p>
            {isSubscribed && subscription && (
              <div className="mt-3 text-xs text-white/70">
                Expires: {new Date(subscription.expiresAt).toLocaleDateString()}
              </div>
            )}
          </div>
        </motion.div>

        {/* Currency Selector */}
        <div className="flex justify-center gap-2">
          {([
            { code: 'BDT' as const, icon: Banknote, label: 'BDT' },
            { code: 'USD' as const, icon: DollarSign, label: 'USD' },
            { code: 'coins' as const, icon: Coins, label: 'Coins' },
          ]).map((c) => (
            <button type="button" key={c.code}
              onClick={() => setSelectedCurrency(c.code)}
              className={`flex items-center gap-1.5 px-4 py-2 rounded-xl text-sm font-medium transition-all ${
                selectedCurrency === c.code
                  ? 'bg-[#111111] text-white shadow-md'
                  : 'bg-white text-[#8D8D8D] hover:text-[#111111]'
              }`}
            >
              <c.icon size={14} /> {c.label}
            </button>
          ))}
        </div>

        {/* Plans */}
        <motion.div
          variants={containerVariants}
          initial="hidden"
          animate="show"
          className="grid grid-cols-1 sm:grid-cols-2 gap-4"
        >
          {PREMIUM_PLANS.map((plan) => {
            const isCurrent = currentTier === plan.id;
            const price = getPrice(plan.id);
            const isPopular = plan.popular;
            const isUpgradingThis = activePlan === plan.id && upgrading;

            return (
              <motion.div
                key={plan.id}
                variants={cardVariants}
                whileHover={{ y: -4, scale: 1.01 }}
                className={`relative bg-white rounded-2xl border-2 p-5 transition-colors ${
                  isCurrent
                    ? 'border-[#00C300]'
                    : isPopular
                    ? 'border-[#00C300]/50'
                    : 'border-transparent'
                } ${isPopular ? 'shadow-lg shadow-[#00C300]/10' : 'shadow-sm'}`}
              >
                {isPopular && (
                  <div className="absolute -top-3 left-1/2 -translate-x-1/2 bg-[#00C300] text-white text-xs font-bold px-3 py-1 rounded-full">
                    Most Popular
                  </div>
                )}
                {isCurrent && (
                  <div className="absolute -top-3 right-4 bg-[#111111] text-white text-xs font-bold px-3 py-1 rounded-full flex items-center gap-1">
                    <Check size={12} /> Active
                  </div>
                )}

                <div className="flex items-center gap-2 mb-3">
                  <div
                    className="w-8 h-8 rounded-lg flex items-center justify-center text-white"
                    style={{ backgroundColor: plan.color }}
                  >
                    {tierIcons[plan.id]}
                  </div>
                  <div>
                    <h3 className="font-bold text-[#111111]">{plan.name}</h3>
                    <p className="text-xs text-[#8D8D8D]">{plan.description}</p>
                  </div>
                </div>

                <div className="mb-4">
                  <span className="text-3xl font-bold text-[#111111]">
