  bio?: string;
}

// Camera QR Scanner using BarcodeDetector API
function CameraQRScanner({ onScan, onClose }: { onScan: (data: string) => void; onClose: () => void }) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [error, setError] = useState('');
  const [scanning, setScanning] = useState(false);
  const streamRef = useRef<MediaStream | null>(null);
  const animFrameRef = useRef<number>(0);
  const detectedRef = useRef(false);

  const startCamera = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } }
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        await videoRef.current.play();
      }
      setScanning(true);
      setError('');
    } catch (err) {
      console.warn('[QRScanner] startCamera failed', err);
      setError('Camera access denied or not available. Please allow camera permission.');
      setScanning(false);
    }
  }, []);

  const stopCamera = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(t => t.stop());
      streamRef.current = null;
    }
    if (animFrameRef.current) {
      cancelAnimationFrame(animFrameRef.current);
    }
    setScanning(false);
  }, []);

  useEffect(() => {
    const initializeCamera = () => {
      startCamera();
    };
    initializeCamera();
    return () => { stopCamera(); detectedRef.current = false; };
  }, [startCamera, stopCamera]);

  // BarcodeDetector scanning loop
  useEffect(() => {
    if (!scanning || !videoRef.current) return;

    const BarcodeDetector = (window as any).BarcodeDetector;
    if (!BarcodeDetector) {
      // Fallback: just show video without auto-scan, user can manually enter
      const handleFallback = () => {
        setError('Auto-scan not available. Please paste the QR data below.');
      };
      handleFallback();
      return;
    }

    const detector = new BarcodeDetector({ formats: ['qr_code'] });
    const video = videoRef.current;
    detectedRef.current = false;

    const scanFrame = async () => {
      if (detectedRef.current || video.readyState < 2) {
        animFrameRef.current = requestAnimationFrame(scanFrame);
        return;
      }
      try {
        const barcodes = await detector.detect(video);
        if (barcodes.length > 0) {
          const raw = barcodes[0].rawValue;
          if (raw) {
            detectedRef.current = true;
            stopCamera();
            onScan(raw);
            return;
          }
        }
      } catch {
        // Frame detection failed, continue scanning
      }
      animFrameRef.current = requestAnimationFrame(scanFrame);
    };

    animFrameRef.current = requestAnimationFrame(scanFrame);

    return () => {
      if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current);
    };
  }, [scanning, onScan, stopCamera]);

  return (
    <div className="relative w-full">
      {/* Video Preview */}
      <div className="relative w-full aspect-square max-w-[340px] mx-auto rounded-3xl overflow-hidden bg-black">
        <video
          ref={videoRef}
          className="w-full h-full object-cover"
          playsInline
          muted
        />
        {/* Overlay */}
        <div className="absolute inset-0 pointer-events-none">
          {/* Corner brackets */}
          <div className="absolute top-8 left-8 w-12 h-12 border-t-4 border-l-4 border-[#00C300] rounded-tl-2xl" />
          <div className="absolute top-8 right-8 w-12 h-12 border-t-4 border-r-4 border-[#00C300] rounded-tr-2xl" />
          <div className="absolute bottom-8 left-8 w-12 h-12 border-b-4 border-l-4 border-[#00C300] rounded-bl-2xl" />
          <div className="absolute bottom-8 right-8 w-12 h-12 border-b-4 border-r-4 border-[#00C300] rounded-br-2xl" />
          {/* Scanning laser line */}
          {scanning && !error && (
            <motion.div
              className="absolute left-8 right-8 h-0.5 bg-[#00C300] shadow-[0_0_10px_#00C300]"
              animate={{ top: ['15%', '85%', '15%'] }}
              transition={{ duration: 2.5, repeat: Infinity, ease: 'linear' }}
            />
          )}
          {/* Center text */}
          {!scanning && !error && (
            <div className="absolute inset-0 flex items-center justify-center">
              <Loader size={32} className="text-white animate-spin" />
            </div>
          )}
        </div>
      </div>

      {/* Error message */}
      {error && (
        <div className="mt-4 mx-auto max-w-[340px] bg-[#FF3B30]/10 border border-[#FF3B30]/30 rounded-xl p-3 flex items-start gap-2">
          <AlertTriangle size={16} className="text-[#FF3B30] shrink-0 mt-0.5" />
          <p className="text-[#FF3B30] text-xs">{error}</p>
        </div>
      )}

      {/* Controls */}
      <div className="flex justify-center gap-4 mt-4">
        <button type="button" onClick={() => { stopCamera(); startCamera(); }}
          className="p-3 bg-white/10 rounded-full text-white hover:bg-white/20 transition-colors"
        >
          <RotateCcw size={20} />
        </button>
        <button type="button" onClick={() => { stopCamera(); onClose(); }}
          className="p-3 bg-white/10 rounded-full text-white hover:bg-white/20 transition-colors"
        >
          <X size={20} />
        </button>
      </div>
    </div>
  );
}

export default function QRScannerPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const initialTab = searchParams.get('tab') === 'scan' ? 'scan' : 'myqr';
  const { user } = useAuthStore();
  const { sendRequest, getUserById, getFriendStatus } = useFriendStore();
  const { wallet, sendFromChat } = useWalletStore();
  const { groups } = useGroupStore();
  const [tab, setTab] = useState<'myqr' | 'scan'>(initialTab);
  const [qrType, setQrType] = useState<QRType>('profile');
  const [copiedProfile, setCopiedProfile] = useState(false);
  const [copiedWallet, setCopiedWallet] = useState(false);
  const [showAddFriend, setShowAddFriend] = useState(false);
  const [showTransfer, setShowTransfer] = useState(false);
  const [scannedData, setScannedData] = useState<{ type: string; userId?: string; amount?: number; walletId?: string; groupId?: string } | null>(null);
  const [scannedUser, setScannedUser] = useState<ScannedUser | null>(null);
  const [friendAdded, setFriendAdded] = useState(false);
  const [scanInput, setScanInput] = useState('');
  const [transferAmount, setTransferAmount] = useState('');
  const [transferNote, setTransferNote] = useState('');
  const [selectedGroup, setSelectedGroup] = useState<string | null>(null);
  const [showCamera, setShowCamera] = useState(false);
  const [scanning, setScanning] = useState(false);

  // Auto-open camera when navigated with tab=scan
  useEffect(() => {
    if (initialTab === 'scan') {
      setShowCamera(true);
    }
  }, [initialTab]);

  const profileUrl = user ? buildGagaChatWebUrl(user.id) : '';
  const qrCodeUri = user ? buildGagaChatUri(user.id) : '';
  const walletId = user ? `GC-${user.id.slice(0, 8).toUpperCase()}` : '';

  const getQrData = () => {
    if (!user) return '';
    switch (qrType) {
      case 'profile': return JSON.stringify({ type: 'profile', userId: user.id, name: user.name });
      case 'transfer': return JSON.stringify({ type: 'transfer', walletId, userId: user.id, name: user.name });
      case 'group': return selectedGroup ? JSON.stringify({ type: 'group', groupId: selectedGroup }) : '';
      case 'wallet': return JSON.stringify({ type: 'wallet', walletId, userId: user.id });
      default: return qrCodeUri;
    }
  };

  const handleCopyProfile = async () => {
    try {
      await navigator.clipboard.writeText(profileUrl);
      setCopiedProfile(true);
      toast.success('Copied to clipboard');
      setTimeout(() => setCopiedProfile(false), 2000);
    } catch { toast.error('Failed to copy'); }
  };

  const handleCopyWallet = async () => {
    try {
      await navigator.clipboard.writeText(walletId);
      setCopiedWallet(true);
      toast.success('Copied to clipboard');
      setTimeout(() => setCopiedWallet(false), 2000);
    } catch { toast.error('Failed to copy'); }
  };

  const handleShare = async () => {
    try {
      if (navigator.share) {
        await navigator.share({
          title: `Add ${user?.name || 'me'} on GaGa Chat`,
          text: qrType === 'transfer' ? `Send money to ${user?.name}` : `Connect with me on GaGa Chat!`,
          url: qrType === 'profile' ? profileUrl : undefined,
        });
      } else {
        handleCopyProfile();
      }
    } catch { /* cancelled */ }
  };

  const parseQRData = useCallback(async (data: string) => {
    setScanning(true);
    try {
      let parsed: any = null;
      
      // Try JSON parse first (QR codes generated by our app are JSON)
      try {
        parsed = JSON.parse(data);
      } catch {
        // Not JSON, try other formats
      }

      if (parsed && (parsed.type === 'profile' || parsed.type === 'friend')) {
        const found = await getUserById(parsed.userId);
        if (found) {
          setScannedUser({ id: found.id, name: found.name, avatar: found.avatar, statusMessage: found.statusMessage, bio: found.bio });
        } else {
          setScannedUser({ id: parsed.userId, name: parsed.name || 'Unknown' });
        }
        setScannedData(parsed);
        setShowAddFriend(true);
      } else if (parsed && (parsed.type === 'transfer' || parsed.type === 'wallet')) {
        const found = parsed.userId ? await getUserById(parsed.userId) : null;
        if (found) setScannedUser({ id: found.id, name: found.name, avatar: found.avatar });
        setScannedData(parsed);
        setShowTransfer(true);
      } else if (parsed && parsed.type === 'group' && parsed.groupId) {
        navigate(`/group/${parsed.groupId}`);
        return;
      } else {
        // Fallback: try URL / URI parsing
        await handleFallbackScan(data);
      }
    } catch {
      await handleFallbackScan(data);
    } finally {
      setScanning(false);
    }
  }, [getUserById, navigate]);

  const handleFallbackScan = async (data: string) => {
    // Handle QR login URLs: https://oumagachat.web.app/qr-login?session=xxx
    const qrLoginMatch = data.match(/qr-login\?session=([a-zA-Z0-9_\-]+)/);
    if (qrLoginMatch?.[1]) {
      const sessionId = qrLoginMatch[1];
      if (!user) {
        toast.error('Please log in first to confirm QR login');
        navigate('/auth');
        return;
      }
      try {
        if (isSupabaseConfigured()) {
          const supabase = getSupabase();
          if (supabase) {
            await supabase.from('qr_sessions').update({
              status: 'confirmed',
              user_id: user.id,
              updated_at: new Date().toISOString(),
            }).eq('session_id', sessionId);
            toast.success('QR login confirmed! Desktop session logged in.');
            navigate('/contacts');
            return;
          }
        }
        if (isFirestoreAvailable()) {
          const db = getFirestoreDB();
          if (db) {
            const sessionRef = doc(db, 'qr_sessions', sessionId);
            await updateDoc(sessionRef, {
              status: 'confirmed',
              userId: user.id,
              userName: user.name,
              confirmedAt: new Date().toISOString(),
            });
            toast.success('QR login confirmed! Desktop session logged in.');
            navigate('/contacts');
            return;
          }
        }
      } catch (err) {
        toast.error('Failed to confirm QR login. Session may have expired.');
      }
      return;
    }

    // Handle web URLs like https://oumagachat.web.app/add-friends?from=xxx or /profile/xxx
    const urlMatch = data.match(/(?:from=|profile\/)([^?&\/\s]+)/);
    if (urlMatch?.[1]) {
      const userId = urlMatch[1];
      const found = await getUserById(userId);
      setScannedUser(found ? { id: found.id, name: found.name, avatar: found.avatar, statusMessage: found.statusMessage } : { id: userId, name: 'Unknown' });
      setScannedData({ type: 'friend', userId });
      setShowAddFriend(true);
      return;
    }

    // Handle wallet ID like GC-XXXX
    if (/^GC-[A-Z0-9]+$/i.test(data)) {
      setScannedData({ type: 'transfer', walletId: data });
      setShowTransfer(true);
      return;
    }

    // Handle gagachat:// URI scheme
    const gagachatMatch = data.match(/^gagachat:\/\/user\/(.+)$/) || data.match(/^gagachat:\/\/(.+)$/);
    if (gagachatMatch?.[1]) {
      const userId = gagachatMatch[1];
      const found = await getUserById(userId);
      setScannedUser(found ? { id: found.id, name: found.name, avatar: found.avatar } : { id: userId, name: 'Unknown' });
      setScannedData({ type: 'friend', userId });
      setShowAddFriend(true);
      return;
    }

    toast.error('Invalid QR code data. Could not recognize format.');
  };

  const handleScanFromCamera = (data: string) => {
    setShowCamera(false);
    parseQRData(data);
  };

  const handleAddFriend = async () => {
    if (!scannedData?.userId || !user?.id) return;
    try {
      // Check if already friends or request already sent/received
      const status = await getFriendStatus(user.id, scannedData.userId);
      if (status === 'friends') {
        toast.info('You are already friends!');
        setShowAddFriend(false);
        navigate(`/chat/${scannedData.userId}`);
        return;
      }
      if (status === 'request_sent') {
        toast.info('Friend request already sent');
        setFriendAdded(true);
        return;
      }
      if (status === 'request_received') {
        toast.info('They already sent you a request. Accept it from the requests tab.');
        setFriendAdded(true);
        return;
      }
      if (status === 'blocked') {
        toast.error('You have blocked this user. Unblock them first.');
        return;
      }
      if (status === 'self') {
        toast.info('This is your own QR code!');
        return;
      }

      await sendRequest(scannedData.userId, user.id);
      setFriendAdded(true);
      toast.success('Friend request sent');
      // Auto-navigate to chat after a short delay for faster connection
      setTimeout(() => {
        setShowAddFriend(false);
        navigate(`/chat/${scannedData.userId}`);
      }, 1500);
    } catch (err: any) {
      toast.error(err?.message || 'Failed to send friend request');
    }
  };

  const handleTransfer = async () => {
    if (!transferAmount || !user?.id) return;
    const amount = parseFloat(transferAmount);
    if (!amount || amount <= 0) { toast.error('Enter a valid amount'); return; }
    const toUserId = scannedData?.userId;
    if (!toUserId) { toast.error('No recipient found'); return; }
    const chatId = 'dm_' + [user.id, toUserId].sort().join('_');
    const ok = await sendFromChat(user.id, user.name || 'User', chatId, toUserId, amount, 'GAGA', transferNote);
    if (ok) {
      toast.success(`Sent ${amount} GAGA coins!`);
      setShowTransfer(false);
      setTransferAmount('');
      setTransferNote('');
    } else {
      toast.error('Transfer failed. Check your balance.');
    }
  };

  return (
    <div className="min-h-[100dvh] bg-[#0d0d0d] text-white">
      {/* Header */}
      <div className="flex items-center gap-3 p-4">
        <button type="button" onClick={() => navigate(-1)} className="p-2 -ml-2 active:bg-white/10 rounded-full text-white transition-colors">
          <ArrowLeft size={22} />
        </button>
        <h1 className="text-lg font-bold">QR Code</h1>
        <div className="ml-auto flex bg-white/10 rounded-full p-0.5">
          {(['myqr', 'scan'] as const).map(t => (
            <button type="button" key={t}
              onClick={() => { setTab(t); setShowCamera(false); }}
              className={`px-4 py-1.5 rounded-full text-xs font-medium transition-colors ${
                tab === t ? 'bg-[#00C300] text-white' : 'text-white/60'
              }`}
            >
              {t === 'myqr' ? 'My QR' : 'Scan'}
            </button>
          ))}
        </div>
      </div>

      <AnimatePresence mode="wait">
        {tab === 'myqr' ? (
          <motion.div
            key="myqr"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="px-6 pb-8"
          >
            {/* QR Type Selector */}
            <div className="flex gap-2 mb-4 overflow-x-auto pb-1 scrollbar-hide">
              {([
                { type: 'profile' as QRType, label: 'Profile', icon: UserPlus },
                { type: 'transfer' as QRType, label: 'Transfer', icon: Wallet },
                { type: 'group' as QRType, label: 'Group', icon: Users },
                { type: 'wallet' as QRType, label: 'Wallet', icon: Wallet },
              ]).map(({ type, label, icon: Icon }) => (
                <button type="button" key={type}
                  onClick={() => setQrType(type)}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap transition-colors ${
                    qrType === type ? 'bg-[#00C300] text-white' : 'bg-white/10 text-white/60'
                  }`}
                >
                  <Icon size={12} /> {label}
                </button>
              ))}
            </div>

            {/* QR Card */}
            <div className="bg-white rounded-3xl p-6 text-[#111111]">
              {/* Profile Header */}
              <div className="flex items-center gap-3 mb-6">
                <div className="w-14 h-14 rounded-full bg-[#F5F5F5] flex items-center justify-center overflow-hidden">
                  {sanitizeMediaUrl(user?.avatar) ? (
                    <img src={sanitizeMediaUrl(user?.avatar)} className="w-full h-full object-cover" alt="User avatar" />
                  ) : (
                    <img src={getDefaultAvatar(user?.id || user?.name || 'user')} className="w-full h-full object-cover" alt="User avatar" />
                  )}
                </div>
                <div>
                  <h2 className="font-bold text-lg">{user?.name || 'My Profile'}</h2>
                  <p className="text-[#8D8D8D] text-xs">
                    {qrType === 'profile' && 'Scan to add friend'}
                    {qrType === 'transfer' && 'Scan to send money'}
                    {qrType === 'group' && 'Scan to join group'}
                    {qrType === 'wallet' && 'Scan to view wallet'}
                  </p>
                </div>
              </div>

              {/* Group selector for group QR */}
              {qrType === 'group' && (
                <div className="mb-4">
                  <select
                    value={selectedGroup || ''}
                    onChange={e => setSelectedGroup(e.target.value || null)}
                    className="w-full bg-[#F5F5F5] rounded-xl px-3 py-2 text-sm focus:outline-none"
                  >
                    <option value="">Select a group</option>
                    {groups.map(g => (
                      <option key={g.id} value={g.id}>{g.name}</option>
                    ))}
                  </select>
                </div>
              )}

              {/* QR Code */}
              <div className="w-56 h-56 mx-auto bg-[#F5F5F5] rounded-2xl flex items-center justify-center mb-6 relative overflow-hidden p-3">
                <div className="w-full h-full">
                  <QRCodeSVG data={getQrData()} size={200} />
                </div>
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                  <div className="w-10 h-10 bg-white rounded-lg flex items-center justify-center border-2 border-[#00C300] shadow-lg">
                    <Logo size={28} />
                  </div>
                </div>
              </div>

              {/* Wallet ID */}
              <div className="flex items-center justify-between bg-[#F5F5F5] rounded-xl px-4 py-3 mb-4">
                <div>
                  <p className="text-[#8D8D8D] text-[10px]">Wallet ID</p>
                  <p className="text-[#111111] font-mono text-sm font-bold">{walletId}</p>
                </div>
                <button type="button" onClick={handleCopyWallet} className="p-2 text-[#00C300]">
                  {copiedWallet ? <Check size={18} /> : <Copy size={18} />}
                </button>
              </div>

              {/* Balance Preview */}
              <div className="flex justify-between text-center bg-[#F5F5F5] rounded-xl p-3 mb-4">
                <div>
                  <p className="text-[#00C300] font-bold">{(wallet?.coins || 0).toLocaleString()}</p>
                  <p className="text-[#8D8D8D] text-[10px]">GAGA</p>
                </div>
                <div>
                  <p className="text-[#2196F3] font-bold">৳{(wallet?.bdtBalance || 0).toFixed(0)}</p>
                  <p className="text-[#8D8D8D] text-[10px]">BDT</p>
                </div>
              </div>

              {/* Actions */}
              <div className="flex gap-2">
                <button type="button" onClick={handleShare}
                  className="flex-1 flex items-center justify-center gap-2 py-3 bg-[#00C300] text-white rounded-xl text-sm font-bold active:bg-[#00A300] transition-colors"
                >
                  <Share2 size={16} /> Share
                </button>
                <button type="button" onClick={handleCopyProfile}
                  className="flex-1 flex items-center justify-center gap-2 py-3 bg-[#F5F5F5] text-[#111111] rounded-xl text-sm font-bold active:bg-[#EBEBEB] transition-colors"
                >
                  <Copy size={16} /> {copiedProfile ? 'Copied!' : 'Copy Link'}
                </button>
              </div>
            </div>

            {/* Quick Tips */}
            <div className="mt-6 space-y-3">
              <p className="text-white/60 text-xs text-center">What others can do with your QR</p>
              {[
                { icon: UserPlus, text: 'Add you as a friend' },
                { icon: Wallet, text: 'Send you Gaga Coins or BDT' },
                { icon: ScanLine, text: 'View your profile or join group' },
              ].map((tip, i) => (
                <div key={i} className="flex items-center gap-3 px-4 py-2 bg-white/5 rounded-xl">
                  <tip.icon size={16} className="text-[#00C300]" />
                  <span className="text-white/80 text-sm">{tip.text}</span>
                </div>
              ))}
            </div>
          </motion.div>
        ) : (
          /* Scan Tab */
          <motion.div
            key="scan"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="px-4 pb-8"
          >
            {/* Camera Scanner */}
            {showCamera ? (
              <CameraQRScanner
                onScan={handleScanFromCamera}
                onClose={() => setShowCamera(false)}
              />
            ) : (
              <div className="text-center">
                {/* Start Camera Button */}
                <div className="w-64 h-64 mx-auto mb-6 relative">
                  <div className="absolute inset-0 border-2 border-[#00C300]/40 rounded-3xl" />
                  <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-[#00C300] rounded-tl-2xl" />
                  <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-[#00C300] rounded-tr-2xl" />
                  <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-[#00C300] rounded-bl-2xl" />
                  <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-[#00C300] rounded-br-2xl" />
                  <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <Camera size={40} className="text-white/40 mb-3" />
                    <button type="button" onClick={() => setShowCamera(true)}
                      className="px-6 py-3 bg-[#00C300] text-white rounded-full text-sm font-bold flex items-center gap-2 hover:bg-[#00A300] transition-colors"
                    >
                      <Camera size={16} /> Open Camera
                    </button>
                  </div>
                </div>

                <p className="text-white/60 text-sm mb-6">
                  Scan a GaGa Chat QR code to add friends, send money, or join groups
                </p>
              </div>
            )}

            {/* Manual Input */}
            {!showCamera && (
              <div className="bg-white/5 rounded-2xl p-4">
                <p className="text-white/60 text-xs mb-2">Or paste QR data manually:</p>
                <textarea
                  value={scanInput}
                  onChange={e => setScanInput(e.target.value)}
                  placeholder='{"type":"profile","userId":"..."} or paste any QR text'
                  className="w-full bg-white/10 rounded-xl px-4 py-3 text-white text-sm placeholder:text-white/30 focus:outline-none focus:ring-2 focus:ring-[#00C300] resize-none h-20"
                />
                <button type="button" onClick={() => scanInput && parseQRData(scanInput)}
                  disabled={!scanInput || scanning}
                  className="w-full mt-3 bg-[#00C300] text-white rounded-xl py-3 text-sm font-bold disabled:opacity-30 active:bg-[#00A300] transition-colors flex items-center justify-center gap-2"
                >
                  {scanning ? <Loader size={16} className="animate-spin" /> : <ScanLine size={16} />}
                  {scanning ? 'Processing...' : 'Process QR Data'}
                </button>
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Add Friend Dialog */}
      <Dialog open={showAddFriend} onOpenChange={setShowAddFriend}>
        <DialogContent className="bg-white border-[#EBEBEB] text-[#111111] sm:max-w-sm">
          <DialogHeader><DialogTitle className="text-[#111111]">Add Friend</DialogTitle></DialogHeader>
          <div className="pt-4 text-center">
            {friendAdded ? (
              <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} className="py-8">
                <div className="w-16 h-16 rounded-full bg-[#00C300]/10 flex items-center justify-center mx-auto mb-3">
                  <Check size={32} className="text-[#00C300]" />
                </div>
                <p className="text-[#00C300] font-bold text-lg">Friend Added!</p>
                <p className="text-[#8D8D8D] text-sm">Redirecting to chat...</p>
              </motion.div>
            ) : (
              <>
                <div className="w-16 h-16 rounded-full bg-[#F5F5F5] flex items-center justify-center mx-auto mb-3 overflow-hidden">
                  {sanitizeMediaUrl(scannedUser?.avatar) ? (
                    <img src={sanitizeMediaUrl(scannedUser?.avatar)} className="w-full h-full object-cover" alt="User avatar" />
                  ) : (
                    <img src={getDefaultAvatar(scannedUser?.id || scannedUser?.name || 'friend')} className="w-full h-full object-cover" alt="User avatar" />
                  )}
                </div>
                <p className="text-[#111111] font-bold text-lg">{scannedUser?.name || 'New Friend'}</p>
                {scannedUser?.statusMessage && (
                  <p className="text-[#8D8D8D] text-sm mt-1">{scannedUser.statusMessage}</p>
                )}
                {scannedUser?.bio && (
                  <p className="text-[#8D8D8D] text-xs mt-1 line-clamp-2">{scannedUser.bio}</p>
                )}
                <p className="text-[#8D8D8D] text-sm mt-2">Add this person to your friends?</p>
                <div className="flex gap-2 mt-4">
                  <button type="button" onClick={() => setShowAddFriend(false)} className="flex-1 py-3 bg-[#F5F5F5] text-[#111111] rounded-xl text-sm font-bold">
                    Cancel
                  </button>
                  <button type="button" onClick={handleAddFriend} className="flex-1 py-3 bg-[#00C300] text-white rounded-xl text-sm font-bold active:bg-[#00A300]">
                    Add Friend
                  </button>
                </div>
              </>
            )}
          </div>
        </DialogContent>
      </Dialog>

      {/* Transfer Dialog */}
      <Dialog open={showTransfer} onOpenChange={setShowTransfer}>
        <DialogContent className="bg-white border-[#EBEBEB] text-[#111111] sm:max-w-sm">
          <DialogHeader><DialogTitle className="text-[#111111]">Send Money</DialogTitle></DialogHeader>
          <div className="pt-4 space-y-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-[#F5F5F5] flex items-center justify-center overflow-hidden">
                {sanitizeMediaUrl(scannedUser?.avatar) ? (
                  <img src={sanitizeMediaUrl(scannedUser?.avatar)} className="w-full h-full object-cover" alt="User avatar" />
                ) : (
                  <img src={getDefaultAvatar(scannedUser?.id || scannedUser?.name || 'friend')} className="w-full h-full object-cover" alt="User avatar" />
                )}
              </div>
              <div>
                <p className="text-[#111111] text-sm font-medium">{scannedUser?.name || 'Recipient'}</p>
                <p className="text-[#8D8D8D] text-[10px] font-mono">{scannedData?.walletId || scannedData?.userId?.slice(0, 12)}...</p>
              </div>
            </div>
            <div>
              <label className="text-[#8D8D8D] text-xs mb-1 block">Amount</label>
              <input
                type="number"
                value={transferAmount}
                onChange={e => setTransferAmount(e.target.value)}
                placeholder="0.00"
                className="w-full bg-[#F5F5F5] rounded-xl px-4 py-3 text-[#111111] text-lg font-bold focus:outline-none focus:ring-2 focus:ring-[#00C300]"
              />
            </div>
            <div>
              <label className="text-[#8D8D8D] text-xs mb-1 block">Note (optional)</label>
              <input
                value={transferNote}
                onChange={e => setTransferNote(e.target.value)}
                placeholder="What's this for?"
                className="w-full bg-[#F5F5F5] rounded-xl px-4 py-2.5 text-[#111111] text-sm focus:outline-none focus:ring-2 focus:ring-[#00C300]"
              />
            </div>
            <div className="flex gap-2">
              <button type="button" onClick={() => setShowTransfer(false)} className="flex-1 py-3 bg-[#F5F5F5] text-[#111111] rounded-xl text-sm font-bold">
                Cancel
              </button>
              <button type="button" onClick={handleTransfer} className="flex-1 py-3 bg-[#00C300] text-white rounded-xl text-sm font-bold active:bg-[#00A300]">
                Send
              </button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Heart, MessageCircle, Share2, Bookmark, Music, Volume2, VolumeX,
  Play, Send, ChevronLeft, MoreHorizontal, UserPlus, Download, BarChart3
} from 'lucide-react';
import { useAuthStore } from '@/store/useAuthStore';
import { useReelStore } from '@/store/useReelStore';
import BottomNav from '@/components/layout/BottomNav';
import EmptyState from '@/components/EmptyState';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import { getDefaultAvatar } from '@/lib/utils';
import { toast } from 'sonner';
import type { Reel } from '@/types';

export default function ReelsPage() {
  const { user } = useAuthStore();
  const { reels, loading, getReels, likeReel, unlikeReel, saveReel, shareReel, commentOnReel } = useReelStore();
  const [activeIndex, setActiveIndex] = useState(0);
  const [localLiked, setLocalLiked] = useState<Record<string, boolean>>({});
  const [localSaved, setLocalSaved] = useState<Record<string, boolean>>({});
  const [muted, setMuted] = useState(true);
  const [playing, setPlaying] = useState<Record<string, boolean>>({});
  const [showComments, setShowComments] = useState<Reel | null>(null);
  const [showInsights, setShowInsights] = useState<Reel | null>(null);
  const [commentText, setCommentText] = useState('');
  const [feedType, setFeedType] = useState<'foryou' | 'following'>('foryou');
  const scrollRef = useRef<HTMLDivElement>(null);
  const videoRefs = useRef<Record<string, HTMLVideoElement | null>>({});
  const navigate = useNavigate();

  useEffect(() => {
    getReels(20);
  }, [getReels]);

  // Auto-play/pause based on active index
  useEffect(() => {
    const reel = reels[activeIndex];
    if (!reel) return;
    Object.entries(videoRefs.current).forEach(([id, video]) => {
      if (!video) return;
      if (id === reel.id) {
        video.play().catch(() => {});
        setPlaying(prev => ({ ...prev, [id]: true }));
      } else {
        video.pause();
        setPlaying(prev => ({ ...prev, [id]: false }));
      }
    });
  }, [activeIndex, reels]);

  // Track view when reel becomes active (3 second watch)
  useEffect(() => {
    const reel = reels[activeIndex];
    if (!reel || !user?.id) return;
    const timer = setTimeout(() => {
      if (!reel.viewedBy?.includes(user.id)) {
        useReelStore.getState().viewReel?.(reel.id, user.id);
      }
    }, 3000);
    return () => clearTimeout(timer);
  }, [activeIndex, reels, user?.id]);

  const handleScroll = useCallback(() => {
    if (!scrollRef.current) return;
    const scrollTop = scrollRef.current.scrollTop;
    const height = scrollRef.current.clientHeight;
    const index = Math.round(scrollTop / height);
    if (index !== activeIndex) {
      setActiveIndex(index);
    }
  }, [activeIndex]);

  const handleLike = async (reel: Reel) => {
    if (!user?.id) return;
    const isLiked = localLiked[reel.id] ?? reel.likes.includes(user.id);
    setLocalLiked(prev => ({ ...prev, [reel.id]: !isLiked }));
    if (isLiked) {
      await unlikeReel(reel.id, user.id);
    } else {
      await likeReel(reel.id, user.id);
    }
  };

  const handleSave = async (reel: Reel) => {
    if (!user?.id) return;
    const isSaved = localSaved[reel.id] ?? reel.savedBy.includes(user.id);
    setLocalSaved(prev => ({ ...prev, [reel.id]: !isSaved }));
    await saveReel(reel.id, user.id);
  };

  const handleShare = async (reel: Reel) => {
    if (!user?.id) return;
    await shareReel(reel.id, user.id);
    try {
      await navigator.clipboard.writeText(`https://oumagachat.web.app/reel/${reel.id}`);
      toast.success('Link copied to clipboard');
    } catch { /* noop */ }
  };

  const handleDownload = async (reel: Reel) => {
    if (!reel.videoUrl) { toast.error('No video to download'); return; }
    try {
      const a = document.createElement('a');
      a.href = reel.videoUrl;
      a.download = `gaga-reel-${reel.id.slice(0, 8)}.mp4`;
      a.target = '_blank';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      toast.success('Download started');
    } catch {
      toast.error('Download failed');
    }
  };

  const handleInsights = (reel: Reel) => {
    setShowInsights(reel);
  };

  const handleAddComment = async () => {
    if (!user?.id || !showComments || !commentText.trim()) return;
    await commentOnReel(showComments.id, user.id, commentText.trim());
    setCommentText('');
    getReels(20);
  };

  const isLiked = (reel: Reel) => {
    if (localLiked[reel.id] !== undefined) return localLiked[reel.id];
    return user?.id ? reel.likes.includes(user.id) : false;
  };

  const isSaved = (reel: Reel) => {
    if (localSaved[reel.id] !== undefined) return localSaved[reel.id];
    return user?.id ? reel.savedBy.includes(user.id) : false;
  };

  return (
    <div className="h-full flex flex-col bg-black relative">
      {/* Header overlay */}
      <div className="absolute top-0 left-0 right-0 z-20 flex flex-col px-4 py-3 bg-gradient-to-b from-black/70 to-transparent">
        <div className="flex items-center justify-between mb-2">
          <button type="button" onClick={() => navigate(-1)} className="text-white p-1">
            <ChevronLeft size={24} />
          </button>
          <div className="flex items-center gap-4">
            <button type="button" onClick={() => setFeedType('following')}
              className={`text-sm font-semibold transition-colors ${feedType === 'following' ? 'text-white' : 'text-white/50'}`}
            >
              Following
            </button>
            <button type="button" onClick={() => setFeedType('foryou')}
              className={`text-sm font-semibold transition-colors ${feedType === 'foryou' ? 'text-white' : 'text-white/50'}`}
            >
              For You
            </button>
          </div>
          <button type="button" className="text-white p-1">
            <MoreHorizontal size={24} />
          </button>
        </div>
        {feedType === 'following' && (
          <div className="text-center">
            <span className="text-white/70 text-xs">Following feed coming soon</span>
          </div>
        )}
      </div>

      {/* Reels feed */}
      <div
        ref={scrollRef}
        onScroll={handleScroll}
        className="flex-1 overflow-y-auto snap-y snap-mandatory scroll-smooth"
      >
        {loading && reels.length === 0 && (
          <div className="h-full flex items-center justify-center">
            <LoadingSkeleton />
          </div>
        )}

        {!loading && reels.length === 0 && (
          <div className="h-full flex items-center justify-center">
            <EmptyState icon={Play} title="No reels yet" description="Be the first to share a reel!" />
          </div>
        )}

        {reels.map((reel, index) => (
          <div
            key={reel.id}
            className="h-full w-full snap-start relative shrink-0 overflow-hidden"
          >
            {/* Video / Placeholder */}
            {reel.videoUrl ? (
              <video
                ref={el => { videoRefs.current[reel.id] = el; }}
                src={reel.videoUrl}
                muted={muted}
                loop
                playsInline
                className="absolute inset-0 w-full h-full object-cover"
                poster={reel.thumbnailUrl}
              />
            ) : (
              <div className="absolute inset-0 bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] flex items-center justify-center">
                <div className="w-24 h-24 rounded-full bg-[#2a2a2a] flex items-center justify-center">
                  <Play size={40} className="text-white/50" />
                </div>
              </div>
            )}

            {/* Gradient overlay */}
            <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-black/30 pointer-events-none" />

            {/* Play/Pause overlay tap */}
            <button type="button" className="absolute inset-0 z-10"
              onClick={() => {
                const video = videoRefs.current[reel.id];
                if (!video) return;
                if (video.paused) {
                  video.play().catch(() => {});
                  setPlaying(prev => ({ ...prev, [reel.id]: true }));
                } else {
                  video.pause();
                  setPlaying(prev => ({ ...prev, [reel.id]: false }));
                }
              }}
            />

            {/* Mute toggle */}
            <button type="button" onClick={() => setMuted(!muted)}
              className="absolute top-20 right-4 z-20 p-2 rounded-full bg-black/40 text-white"
            >
              {muted ? <VolumeX size={18} /> : <Volume2 size={18} />}
            </button>

            {/* Right side actions */}
            <div className="absolute right-3 bottom-24 z-20 flex flex-col items-center gap-5">
              {/* Avatar */}
              <div className="relative">
                <img
                  src={reel.userAvatar || getDefaultAvatar(reel.userId)}
                  alt={reel.userName}
                  className="w-10 h-10 rounded-full object-cover border border-white/20"
                />
                <button type="button" className="absolute -bottom-2 left-1/2 -translate-x-1/2 bg-[#00C300] rounded-full p-0.5">
                  <UserPlus size={12} className="text-black" />
                </button>
              </div>

              {/* Like */}
              <button type="button" onClick={() => handleLike(reel)} className="flex flex-col items-center gap-0.5">
                <Heart
                  size={28}
                  className={isLiked(reel) ? 'text-red-500 fill-red-500' : 'text-white'}
                />
                <span className="text-white text-xs font-medium">
                  {(reel.likes.length + (localLiked[reel.id] && !reel.likes.includes(user?.id || '') ? 1 : 0)).toLocaleString()}
                </span>
              </button>

              {/* Comment */}
              <button type="button" onClick={() => setShowComments(reel)} className="flex flex-col items-center gap-0.5">
                <MessageCircle size={28} className="text-white" />
                <span className="text-white text-xs font-medium">{reel.comments.length}</span>
              </button>

              {/* Save */}
              <button type="button" onClick={() => handleSave(reel)} className="flex flex-col items-center gap-0.5">
                <Bookmark
                  size={28}
                  className={isSaved(reel) ? 'text-[#00C300] fill-[#00C300]' : 'text-white'}
                />
              </button>

              {/* Share */}
              <button type="button" onClick={() => handleShare(reel)} className="flex flex-col items-center gap-0.5">
                <Share2 size={28} className="text-white" />
                <span className="text-white text-xs font-medium">{reel.shares.length}</span>
              </button>

              {/* Download */}
              <button type="button" onClick={() => handleDownload(reel)} className="flex flex-col items-center gap-0.5">
                <Download size={28} className="text-white" />
                <span className="text-white text-xs font-medium">Save</span>
              </button>

              {/* Insights */}
              <button type="button" onClick={() => handleInsights(reel)} className="flex flex-col items-center gap-0.5">
                <BarChart3 size={28} className="text-white" />
                <span className="text-white text-xs font-medium">{reel.viewCount.toLocaleString()}</span>
              </button>

              {/* More */}
              <button type="button" className="text-white">
                <MoreHorizontal size={24} />
              </button>
            </div>

            {/* Bottom info */}
            <div className="absolute left-4 bottom-8 right-20 z-20">
              <div className="flex items-center gap-2 mb-2">
                <img
                  src={reel.userAvatar || getDefaultAvatar(reel.userId)}
                  alt="User avatar"
                  className="w-8 h-8 rounded-full object-cover"
                />
                <span className="text-white font-semibold text-sm">{reel.userName || 'User'}</span>
                <button type="button" className="px-3 py-1 rounded-full border border-white/30 text-white text-xs font-medium">
                  Follow
                </button>
              </div>
              <p className="text-white text-sm leading-relaxed mb-2 line-clamp-2">
                {reel.caption}
              </p>
              {reel.tags && reel.tags.length > 0 && (
                <div className="flex flex-wrap gap-1 mb-2">
                  {reel.tags.map(tag => (
                    <span key={tag} className="text-[#00C300] text-sm">#{tag}</span>
                  ))}
                </div>
              )}
              {reel.musicTitle && (
                <div className="flex items-center gap-2">
                  <Music size={14} className="text-white" />
                  <div className="overflow-hidden w-40">
                    <motion.div
                      animate={{ x: [0, -80, 0] }}
                      transition={{ repeat: Infinity, duration: 8, ease: 'linear' }}
                      className="text-white text-xs whitespace-nowrap"
                    >
                      {reel.musicTitle} • Original Sound
                    </motion.div>
                  </div>
                </div>
              )}
            </div>

            {/* Progress indicator */}
            <div className="absolute top-1 left-4 right-4 z-20 flex gap-1">
              {reels.map((_, i) => (
                <div key={i} className="h-0.5 flex-1 rounded-full bg-white/30 overflow-hidden">
                  {i === activeIndex && (
                    <motion.div
                      className="h-full bg-white"
                      initial={{ width: '0%' }}
                      animate={{ width: '100%' }}
                      transition={{ duration: 5, ease: 'linear' }}
                    />
                  )}
                  {i < activeIndex && <div className="h-full bg-white" />}
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {/* Comments Sheet */}
      <AnimatePresence>
        {showComments && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 bg-black/50 flex items-end"
            onClick={() => setShowComments(null)}
          >
            <motion.div
              initial={{ y: '100%' }}
              animate={{ y: 0 }}
              exit={{ y: '100%' }}
              transition={{ type: 'spring', damping: 25, stiffness: 300 }}
              className="bg-[#1a1a1a] rounded-t-2xl w-full max-h-[70vh] flex flex-col"
              onClick={e => e.stopPropagation()}
            >
              <div className="flex items-center justify-center py-3 border-b border-[#2a2a2a]">
                <div className="w-10 h-1 rounded-full bg-[#8D8D8D]" />
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-4">
                {showComments.comments.length === 0 ? (
                  <p className="text-center text-[#8D8D8D] text-sm py-8">No comments yet</p>
                ) : (
                  showComments.comments.map((comment: any) => (
                    <div key={comment.id || comment.userId + comment.timestamp} className="flex gap-3">
                      <img
                        src={comment.userAvatar || getDefaultAvatar(comment.userId)}
                        alt="User avatar"
                        className="w-8 h-8 rounded-full object-cover shrink-0"
                      />
                      <div className="flex-1">
                        <p className="text-white text-sm font-medium">{comment.userName || 'User'}</p>
                        <p className="text-[#8D8D8D] text-sm">{comment.content}</p>
                      </div>
                    </div>
                  ))
                )}
              </div>
              <div className="p-3 border-t border-[#2a2a2a] flex gap-2">
                <input
                  type="text"
                  value={commentText}
                  onChange={e => setCommentText(e.target.value)}
                  placeholder="Add a comment..."
                  className="flex-1 bg-[#2a2a2a] text-white rounded-full px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#00C300]"
                  onKeyDown={e => e.key === 'Enter' && handleAddComment()}
                />
                <button type="button" onClick={handleAddComment}
                  disabled={!commentText.trim()}
                  className="p-2 rounded-full bg-[#00C300] text-black disabled:opacity-50"
                >
                  <Send size={18} />
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Insights Sheet */}
      <AnimatePresence>
        {showInsights && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 bg-black/50 flex items-end"
            onClick={() => setShowInsights(null)}
          >
            <motion.div
              initial={{ y: '100%' }}
              animate={{ y: 0 }}
              exit={{ y: '100%' }}
              transition={{ type: 'spring', damping: 25, stiffness: 300 }}
              className="bg-[#1a1a1a] rounded-t-2xl w-full max-h-[50vh] flex flex-col"
              onClick={e => e.stopPropagation()}
            >
              <div className="flex items-center justify-center py-3 border-b border-[#2a2a2a]">
                <div className="w-10 h-1 rounded-full bg-[#8D8D8D]" />
              </div>
              <div className="p-6 space-y-4">
                <h3 className="text-white font-bold text-lg">Reel Insights</h3>
                <div className="grid grid-cols-3 gap-4">
                  <div className="text-center">
                    <p className="text-white text-2xl font-bold">{showInsights.viewCount.toLocaleString()}</p>
                    <p className="text-[#8D8D8D] text-xs">Views</p>
                  </div>
                  <div className="text-center">
                    <p className="text-white text-2xl font-bold">{showInsights.likes.length.toLocaleString()}</p>
                    <p className="text-[#8D8D8D] text-xs">Likes</p>
                  </div>
                  <div className="text-center">
                    <p className="text-white text-2xl font-bold">{showInsights.comments.length.toLocaleString()}</p>
                    <p className="text-[#8D8D8D] text-xs">Comments</p>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="text-center">
                    <p className="text-white text-2xl font-bold">{showInsights.shares.length.toLocaleString()}</p>
                    <p className="text-[#8D8D8D] text-xs">Shares</p>
                  </div>
                  <div className="text-center">
                    <p className="text-white text-2xl font-bold">{showInsights.savedBy.length.toLocaleString()}</p>
                    <p className="text-[#8D8D8D] text-xs">Saves</p>
                  </div>
                </div>
                <button type="button" onClick={() => setShowInsights(null)}
                  className="w-full py-3 bg-[#2a2a2a] text-white rounded-xl text-sm font-bold"
                >
                  Close
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <BottomNav />
    </div>
  );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  ArrowLeft, Bookmark, Trash2, Search, X, MessageCircle,
  FileText, Image as ImageIcon, MapPin, File, Clock
} from 'lucide-react';
import { useAuthStore } from '@/store/useAuthStore';
import { useSavedMessages } from '@/hooks/useSavedMessages';
import { formatTime } from '@/lib/utils';
import { toast } from 'sonner';

export default function SavedMessagesPage() {
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const { saved, unsaveMessage, clearAll } = useSavedMessages(user?.id);
  const [search, setSearch] = useState('');
  const [showConfirm, setShowConfirm] = useState(false);

  const filtered = saved.filter(s =>
    s.content.toLowerCase().includes(search.toLowerCase()) ||
    s.senderName.toLowerCase().includes(search.toLowerCase())
  );

  const iconForType = (type: string) => {
    switch (type) {
      case 'image': return <ImageIcon size={16} className="text-[#00C300]" />;
      case 'video': return <ImageIcon size={16} className="text-[#FF3B30]" />;
      case 'file': return <File size={16} className="text-[#8B5CF6]" />;
      case 'location': return <MapPin size={16} className="text-[#FF3B30]" />;
      case 'voice': return <MessageCircle size={16} className="text-[#2196F3]" />;
      default: return <MessageCircle size={16} className="text-[#8D8D8D]" />;
    }
  };

  return (
    <div className="min-h-[100dvh] bg-[#F5F5F5]">
      {/* Header */}
      <div className="bg-white border-b border-[#EBEBEB] sticky top-0 z-10">
        <div className="flex items-center gap-3 p-4">
          <button type="button" onClick={() => navigate(-1)} className="p-2 -ml-2 hover:bg-[#F5F5F5] rounded-full text-[#111111]">
            <ArrowLeft size={22} />
          </button>
          <h1 className="text-lg font-bold text-[#111111] flex-1">Saved Messages</h1>
          {saved.length > 0 && (
            <button type="button" onClick={() => setShowConfirm(true)}
              className="text-[#FF3B30] text-sm font-medium"
            >
              Clear All
            </button>
          )}
        </div>
        <div className="px-4 pb-3">
          <div className="relative">
            <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8D8D8D]" />
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search saved messages..."
              className="w-full bg-[#F5F5F5] rounded-xl pl-9 pr-9 py-2.5 text-sm text-[#111111] focus:outline-none focus:ring-2 focus:ring-[#00C300] placeholder:text-[#8D8D8D]"
            />
            {search && (
              <button type="button" onClick={() => setSearch('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-[#8D8D8D]">
                <X size={14} />
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="p-4 space-y-2">
        {filtered.length === 0 ? (
          <div className="text-center py-12">
            <Bookmark size={48} className="text-[#C7C7CC] mx-auto mb-3" />
            <p className="text-[#8D8D8D] text-sm">
              {search ? 'No messages match your search' : 'No saved messages yet'}
            </p>
            <p className="text-[#C7C7CC] text-xs mt-1">
              {search ? 'Try a different search term' : 'Long press a message and tap Save'}
            </p>
          </div>
        ) : (
          filtered.map((msg, i) => (
            <motion.div
              key={msg.id}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.03 }}
              className="bg-white rounded-xl border border-[#EBEBEB] p-4 hover:shadow-sm transition-shadow"
            >
              <div className="flex items-center gap-2 mb-2">
                {iconForType(msg.type)}
                <p className="text-[#111111] text-sm font-medium">{msg.senderName}</p>
                <span className="text-[#C7C7CC] text-xs ml-auto">{formatTime(msg.timestamp)}</span>
              </div>
              <p className="text-[#111111] text-sm whitespace-pre-wrap break-words">{msg.content}</p>
              {msg.mediaUrl && msg.type === 'image' && (
                <a href={msg.mediaUrl} target="_blank" rel="noopener noreferrer" className="mt-2 block">
                  <img src={msg.mediaUrl} className="rounded-lg max-h-48 object-cover" alt="Shared image" />
                </a>
              )}
              {msg.mediaUrl && msg.type === 'video' && (
                <video src={msg.mediaUrl} className="mt-2 rounded-lg max-h-48 w-full" controls />
              )}
              <div className="flex items-center justify-between mt-3">
                <span className="text-[#8D8D8D] text-[10px] flex items-center gap-1">
                  <Clock size={10} /> Saved {new Date(msg.savedAt).toLocaleDateString()}
                </span>
                <button type="button" onClick={() => {
                    unsaveMessage(msg.id);
                    toast.success('Message removed');
                  }}
                  className="text-[#FF3B30] text-xs flex items-center gap-1 hover:bg-[#FF3B30]/10 px-2 py-1 rounded-lg transition-colors"
                >
                  <Trash2 size={12} /> Remove
                </button>
              </div>
            </motion.div>
          ))
        )}
      </div>

      {/* Clear All Confirm */}
      <AnimatePresence>
        {showConfirm && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4"
            onClick={() => setShowConfirm(false)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="bg-white rounded-2xl p-6 max-w-sm w-full"
              onClick={e => e.stopPropagation()}
            >
              <h3 className="text-lg font-bold text-[#111111] mb-2">Clear All Saved?</h3>
              <p className="text-[#8D8D8D] text-sm mb-4">This will remove all saved messages. This cannot be undone.</p>
              <div className="flex gap-2">
                <button type="button" onClick={() => setShowConfirm(false)}
                  className="flex-1 py-3 bg-[#F5F5F5] text-[#111111] rounded-xl text-sm font-bold"
                >
                  Cancel
                </button>
                <button type="button" onClick={() => { clearAll(); setShowConfirm(false); toast.success('All saved messages cleared'); }}
                  className="flex-1 py-3 bg-[#FF3B30] text-white rounded-xl text-sm font-bold"
                >
                  Clear All
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Search, X, User, Hash, MessageSquare, Calendar, ShoppingBag, Users, Loader,
  ArrowRight, TrendingUp, Clock, MapPin, Filter, SlidersHorizontal
} from 'lucide-react';
import { useEnhancedTimelineStore } from '@/store/useEnhancedTimelineStore';
import { useEventStore } from '@/store/useEventStore';
import { useMarketplaceStore } from '@/store/useMarketplaceStore';
import { useGroupStore } from '@/store/useGroupStore';
import { isFirestoreAvailable, queryCollection, COLLECTIONS } from '@/lib/firestore';
import { where, orderBy, limit } from '@/lib/firestore';
import { getDefaultAvatar, formatTime } from '@/lib/utils';
import type { Chat, TimelinePost, User as UserType, EventData, MarketplaceItem, Hashtag } from '@/types';
import BottomNav from '@/components/layout/BottomNav';

const TABS = [
  { key: 'all', label: 'All', icon: Search },
  { key: 'users', label: 'People', icon: User },
  { key: 'posts', label: 'Posts', icon: MessageSquare },
  { key: 'hashtags', label: 'Tags', icon: Hash },
  { key: 'events', label: 'Events', icon: Calendar },
  { key: 'marketplace', label: 'Market', icon: ShoppingBag },
  { key: 'groups', label: 'Groups', icon: Users },
] as const;

type TabKey = typeof TABS[number]['key'];

interface SearchResult {
  id: string;
  type: TabKey;
  title: string;
  subtitle: string;
  image?: string;
  meta?: string;
  data: UserType | TimelinePost | EventData | MarketplaceItem | Chat | Hashtag;
}

export default function SearchPage() {
  const navigate = useNavigate();
  const { searchHashtags } = useEnhancedTimelineStore();
  const { events } = useEventStore();
  const { listings } = useMarketplaceStore();
  const { groups } = useGroupStore();

  const [query, setQuery] = useState('');
  const [activeTab, setActiveTab] = useState<TabKey>('all');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [recentSearches, setRecentSearches] = useState<string[]>([]);
  const [trendingSearches] = useState([
    'gagachat', 'tech', 'gaming', 'music', 'food', 'travel', 'photography', 'memes', 'coding', 'fitness',
  ]);

  // Load recent searches from localStorage
  useEffect(() => {
    const loadRecentSearches = () => {
      try {
        const saved = localStorage.getItem('gaga-recent-searches');
        if (saved) setRecentSearches(JSON.parse(saved));
      } catch {
        // ignore
      }
    };

    loadRecentSearches();
  }, []);

  const saveRecentSearch = useCallback((q: string) => {
    if (!q.trim()) return;
    setRecentSearches(prev => {
      const next = [q.trim(), ...prev.filter(s => s !== q.trim())].slice(0, 10);
      localStorage.setItem('gaga-recent-searches', JSON.stringify(next));
      return next;
    });
  }, []);

  const performSearch = useCallback(async (q: string) => {
    if (!q.trim() || q.trim().length < 2) {
      setResults([]);
      return;
    }
    setLoading(true);
    const term = q.trim().toLowerCase();
    const all: SearchResult[] = [];

    try {
      // Search users by name AND username (parallel queries)
      if (activeTab === 'all' || activeTab === 'users') {
        if (isFirestoreAvailable()) {
          const [nameData, usernameData] = await Promise.all([
            queryCollection<UserType>(COLLECTIONS.USERS, [
              where('name', '>=', term),
              where('name', '<=', term + '\uf8ff'),
              limit(20),
            ]),
            queryCollection<UserType>(COLLECTIONS.USERS, [
              where('username', '>=', term),
              where('username', '<=', term + '\uf8ff'),
              limit(20),
            ]),
          ]);
          const userMap = new Map<string, UserType>();
          (nameData || []).forEach((u) => userMap.set(u.id, u));
          (usernameData || []).forEach((u) => userMap.set(u.id, u));
          userMap.forEach((u) => {
            all.push({
              id: u.id,
              type: 'users',
              title: u.name || 'User',
              subtitle: u.username ? '@' + u.username : u.email || '',
              image: u.avatar || getDefaultAvatar(u.name || 'U'),
              meta: u.bio || '',
              data: u,
            });
          });
        }
      }

      // Search posts
      if (activeTab === 'all' || activeTab === 'posts') {
        if (isFirestoreAvailable()) {
          const postData = await queryCollection<TimelinePost>(COLLECTIONS.POSTS, [
            where('content', '>=', term),
            where('content', '<=', term + '\uf8ff'),
            orderBy('timestamp', 'desc'),
            limit(20),
          ]);
          (postData || []).forEach((p) => {
            all.push({
              id: p.id,
              type: 'posts',
              title: p.content?.slice(0, 60) || 'Post',
              subtitle: p.userName || 'User',
              image: p.images?.[0] || undefined,
              meta: p.timestamp ? formatTime(p.timestamp) : '',
              data: p,
            });
          });
        }
      }

      // Search hashtags
      if (activeTab === 'all' || activeTab === 'hashtags') {
        const hashtags = await searchHashtags(term);
        hashtags.forEach((h: Hashtag) => {
          all.push({
            id: h.id,
            type: 'hashtags',
            title: '#' + h.tag,
            subtitle: `${h.postCount.toLocaleString()} posts`,
            meta: h.trending ? 'Trending' : '',
            data: h,
          });
        });
      }

      // Search events
      if (activeTab === 'all' || activeTab === 'events') {
        const eventResults = events.filter(e =>
          e.title.toLowerCase().includes(term) ||
          e.description.toLowerCase().includes(term) ||
          e.location.toLowerCase().includes(term)
        );
        eventResults.forEach((e: EventData) => {
          all.push({
            id: e.id,
            type: 'events',
            title: e.title,
            subtitle: `${e.location} · ${e.startDate.toLocaleDateString()}`,
            meta: `${e.attendees.length} going`,
            data: e,
          });
        });
      }

      // Search marketplace
      if (activeTab === 'all' || activeTab === 'marketplace') {
        const marketResults = listings.filter(l =>
          l.title.toLowerCase().includes(term) ||
          l.description.toLowerCase().includes(term) ||
          l.category.toLowerCase().includes(term)
        );
        marketResults.forEach((l: MarketplaceItem) => {
          all.push({
            id: l.id,
            type: 'marketplace',
            title: l.title,
            subtitle: `৳${l.price.toLocaleString()} · ${l.condition}`,
            image: l.images?.[0] || undefined,
            meta: l.status,
            data: l,
          });
        });
      }

      // Search groups
      if (activeTab === 'all' || activeTab === 'groups') {
        const groupResults = groups.filter((g: Chat) =>
          (g.name || '').toLowerCase().includes(term) ||
          ((g.description || '') as string).toLowerCase().includes(term)
        );
        groupResults.forEach((g) => {
          all.push({
            id: g.id,
            type: 'groups',
            title: g.name || 'Group',
            subtitle: `${g.participants.length} members`,
            meta: 'Group',
            data: g,
          });
        });
      }
    } catch (err) {
      console.error('Search error:', err);
    }

    setResults(all);
    setLoading(false);
  }, [activeTab, events, listings, groups, searchHashtags]);

  // Debounced search
  useEffect(() => {
    const timer = setTimeout(() => {
      performSearch(query);
    }, 300);
    return () => clearTimeout(timer);
  }, [query, activeTab, performSearch]);

  const handleResultClick = (result: SearchResult) => {
    saveRecentSearch(query);
    switch (result.type) {
      case 'users':
        navigate('/profile/' + result.id);
        break;
      case 'posts':
        navigate('/timeline', { state: { highlightPostId: result.id } });
        break;
      case 'hashtags':
        if ('tag' in result.data) {
          navigate('/hashtags', { state: { tag: result.data.tag } });
        } else {
          navigate('/hashtags');
        }
        break;
      case 'events':
        navigate('/events', { state: { highlightEventId: result.id } });
        break;
      case 'marketplace':
        navigate('/marketplace', { state: { highlightItemId: result.id } });
        break;
      case 'groups':
        navigate(`/group/${result.id}`);
        break;
    }
  };

  const clearRecents = () => {
    setRecentSearches([]);
    localStorage.removeItem('gaga-recent-searches');
  };

  return (
    <div className="h-full flex flex-col bg-[#0d0d0d]">
      {/* Header */}
      <div className="shrink-0 px-4 py-3 border-b border-[#1a1a1a]">
        <div className="flex items-center gap-3">
          <button type="button" onClick={() => navigate(-1)} className="p-1.5 rounded-lg hover:bg-[#1a1a1a] text-[#8D8D8D]">
            <X size={20} />
          </button>
          <div className="relative flex-1">
            <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8D8D8D]" />
            <input
              type="text"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search people, posts, tags, events..."
              className="w-full bg-[#1a1a1a] text-white pl-10 pr-10 py-2.5 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#00C300] placeholder:text-[#8D8D8D]"
              autoFocus
            />
            {query && (
              <button type="button" onClick={() => setQuery('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-[#8D8D8D]">
                <X size={14} />
              </button>
            )}
          </div>
          <button type="button" className="p-2 rounded-lg hover:bg-[#1a1a1a] text-[#8D8D8D]">
            <SlidersHorizontal size={18} />
          </button>
        </div>

        {/* Tabs */}
        <div className="flex gap-1 mt-3 overflow-x-auto scrollbar-hide">
          {TABS.map(tab => (
            <button type="button" key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={`flex items-center gap-1 px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap transition-colors ${
                activeTab === tab.key ? 'bg-[#00C300] text-black' : 'bg-[#1a1a1a] text-[#8D8D8D]'
              }`}
            >
              <tab.icon size={12} /> {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto">
        {!query && (
          <div className="p-4">
            {/* Recent searches */}
            {recentSearches.length > 0 && (
              <div className="mb-6">
                <div className="flex items-center justify-between mb-2">
                  <h3 className="text-xs font-semibold text-[#8D8D8D] uppercase tracking-wider">Recent</h3>
                  <button type="button" onClick={clearRecents} className="text-xs text-[#FF3B30]">Clear</button>
                </div>
                <div className="flex flex-wrap gap-2">
                  {recentSearches.map((s, i) => (
                    <button type="button" key={i}
                      onClick={() => setQuery(s)}
                      className="flex items-center gap-1 px-3 py-1.5 rounded-full bg-[#1a1a1a] text-[#8D8D8D] text-xs hover:bg-[#2a2a2a]"
                    >
                      <Clock size={10} /> {s}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Trending searches */}
            <div>
              <h3 className="text-xs font-semibold text-[#8D8D8D] uppercase tracking-wider mb-2">Trending</h3>
              <div className="flex flex-wrap gap-2">
                {trendingSearches.map((s, i) => (
                  <button type="button" key={i}
                    onClick={() => setQuery(s)}
                    className="flex items-center gap-1 px-3 py-1.5 rounded-full bg-[#1a1a1a] text-[#00C300] text-xs hover:bg-[#2a2a2a]"
                  >
                    <TrendingUp size={10} /> {s}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Loading */}
        {loading && (
          <div className="flex justify-center py-12">
            <Loader size={24} className="text-[#00C300] animate-spin" />
          </div>
        )}

        {/* Results */}
        {!loading && query && results.length === 0 && (
          <div className="text-center py-16">
            <Search size={48} className="mx-auto text-[#2a2a2a] mb-4" />
            <p className="text-[#8D8D8D] font-medium">No results found</p>
            <p className="text-[#8D8D8D]/60 text-sm mt-1">Try different keywords</p>
          </div>
        )}

        {!loading && results.length > 0 && (
          <div className="p-4 space-y-2">
            {results.map((result, i) => (
              <motion.button
                key={`${result.type}-${result.id}`}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.03 }}
                onClick={() => handleResultClick(result)}
                className="w-full flex items-center gap-3 p-3 rounded-xl bg-[#1a1a1a] hover:bg-[#2a2a2a] transition-colors text-left"
              >
                {result.image ? (
                  <img src={result.image} alt="Cover image" className="w-12 h-12 rounded-xl object-cover bg-[#2a2a2a] shrink-0" />
                ) : (
                  <div className="w-12 h-12 rounded-xl bg-[#2a2a2a] flex items-center justify-center shrink-0">
                    {(() => {
                      const TabIcon = TABS.find(t => t.key === result.type)?.icon || Search;
                      return <TabIcon size={20} className="text-[#8D8D8D]" />;
                    })()}
                  </div>
                )}
                <div className="flex-1 min-w-0">
                  <p className="text-white text-sm font-medium truncate">{result.title}</p>
                  <p className="text-[#8D8D8D] text-xs truncate">{result.subtitle}</p>
                </div>
                <div className="text-right shrink-0">
                  {result.meta && (
                    <span className="text-[10px] text-[#00C300] bg-[#00C300]/10 px-2 py-0.5 rounded-full">{result.meta}</span>
                  )}
                  <ArrowRight size={14} className="text-[#8D8D8D] mt-1 ml-auto" />
                </div>
              </motion.button>
            ))}
          </div>
        )}
      </div>

      <BottomNav />
    </div>
  );
}
